--
-- Name: get_contact_timeline(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_contact_timeline(p_contact_id uuid, p_company_id uuid) RETURNS TABLE(kind text, ts timestamp with time zone, id uuid, direction text, body text, media_urls text[], actor uuid, status text, duration_seconds integer, recording_path text, transcript text, summary text, sentiment text, voicemail_id uuid, ai_reply_sent_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT t.* FROM (
  SELECT 'text'::text AS kind, m.created_at AS ts, m.id, m.direction, m.body, m.media_urls,
         m.sent_by AS actor, m.status,
         NULL::int AS duration_seconds, NULL::text AS recording_path, NULL::text AS transcript, NULL::text AS summary, NULL::text AS sentiment,
         NULL::uuid AS voicemail_id, NULL::timestamptz AS ai_reply_sent_at
  FROM public.txt_messages m
  WHERE m.contact_id = p_contact_id
    AND m.company_id = p_company_id

  UNION ALL

  SELECT 'call'::text, c.created_at, c.id, c.direction, NULL::text, NULL::text[],
         c.initiated_by, c.status,
         c.duration_seconds,
         COALESCE(v.recording_storage_path, c.recording_storage_path),
         COALESCE(v.transcript, c.transcript),
         COALESCE(v.summary, c.ai_summary),
         c.sentiment,
         v.id,
         v.ai_reply_sent_at
  FROM public.calls c
  LEFT JOIN public.voicemails v
    ON v.call_id = c.id
   AND v.deleted_at IS NULL
   AND v.company_id = p_company_id
  WHERE c.contact_id = p_contact_id
    AND c.company_id = p_company_id

  UNION ALL

  SELECT 'voicemail'::text, vm.created_at, vm.id, 'inbound'::text, NULL::text, NULL::text[],
         NULL::uuid, NULL::text,
         vm.recording_duration_sec, vm.recording_storage_path, vm.transcript, vm.summary,
         NULL::text,
         vm.id,
         vm.ai_reply_sent_at
  FROM public.voicemails vm
  WHERE vm.contact_id = p_contact_id
    AND vm.company_id = p_company_id
    AND vm.deleted_at IS NULL
    AND NOT EXISTS (
      SELECT 1 FROM public.calls c2
      WHERE c2.id = vm.call_id
        AND c2.contact_id = p_contact_id
        AND c2.company_id = p_company_id
    )

  UNION ALL

  SELECT 'note'::text, n.created_at, n.id, NULL::text, n.body, NULL::text[],
         n.created_by, NULL::text,
         NULL::int, NULL::text, NULL::text, NULL::text, NULL::text,
         NULL::uuid, NULL::timestamptz
  FROM public.txt_notes n
  JOIN public.txt_conversations conv ON conv.id = n.conversation_id
  WHERE conv.contact_id = p_contact_id
    AND n.company_id = p_company_id
    AND conv.company_id = p_company_id
  ) t
  WHERE (select auth.uid()) IS NULL
     OR EXISTS (
       SELECT 1 FROM public.user_profiles up
       WHERE up.id = (select auth.uid())
         AND up.company_id = p_company_id
         AND (up.role = 'admin' OR up.can_access_unified_inbox = true OR up.can_access_txt = true)
     )
  ORDER BY 2 ASC, 1 ASC;
$$;


ALTER FUNCTION public.get_contact_timeline(p_contact_id uuid, p_company_id uuid) OWNER TO postgres;

--
-- Name: get_last_top_level_message_per_conversation(uuid[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_last_top_level_message_per_conversation(conv_ids uuid[]) RETURNS TABLE(conversation_id uuid, content text, created_at timestamp with time zone)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT DISTINCT ON (m.conversation_id)
    m.conversation_id,
    m.content,
    m.created_at
  FROM messages m
  WHERE m.conversation_id = ANY(conv_ids)
    AND m.deleted_at IS NULL
  ORDER BY m.conversation_id, m.created_at DESC;
$$;


ALTER FUNCTION public.get_last_top_level_message_per_conversation(conv_ids uuid[]) OWNER TO postgres;

