--
-- Name: get_unread_state_for_user(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_unread_state_for_user(p_user_id uuid, p_company_id uuid) RETURNS TABLE(scope text, scope_id uuid, last_at timestamp with time zone)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT u.scope, u.scope_id, u.last_at FROM (
    SELECT 'room'::text AS scope, rm.room_id AS scope_id, MAX(m.created_at) AS last_at
    FROM room_members rm
    JOIN messages m ON m.room_id = rm.room_id
    WHERE rm.user_id = p_user_id AND m.parent_id IS NULL AND m.deleted_at IS NULL
    GROUP BY rm.room_id
    UNION ALL
    SELECT 'conversation'::text AS scope, cm.conversation_id AS scope_id, MAX(m.created_at) AS last_at
    FROM conversation_members cm
    JOIN messages m ON m.conversation_id = cm.conversation_id
    WHERE cm.user_id = p_user_id AND m.parent_id IS NULL AND m.deleted_at IS NULL
    GROUP BY cm.conversation_id
  ) u
  WHERE (SELECT auth.uid()) IS NULL OR (SELECT auth.uid()) = p_user_id
$$;


ALTER FUNCTION public.get_unread_state_for_user(p_user_id uuid, p_company_id uuid) OWNER TO postgres;

--
-- Name: get_visits_report(uuid, date, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_visits_report(p_company_id uuid, p_start date, p_end date) RETURNS TABLE(tech_name text, tech_external_id text, dept_prefix text, is_recurring boolean, visit_count bigint, total_value numeric)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT
    ju.name                       AS tech_name,
    ju.external_id                AS tech_external_id,
    j.dept_prefix,
    j.is_recurring,
    COUNT(DISTINCT v.id)::bigint  AS visit_count,
    COALESCE(SUM(li.total), 0)    AS total_value
  FROM visits v
  CROSS JOIN LATERAL unnest(v.tech_external_user_ids) AS tech_gid
  JOIN jobber_users ju
    ON ju.external_id = tech_gid
   AND ju.company_id  = v.company_id
  LEFT JOIN jobs j
    ON j.id = v.job_id AND j.deleted_at IS NULL
  LEFT JOIN line_items li
    ON li.parent_external_id = v.external_id
   AND li.parent_type        = 'visit'
   AND li.company_id         = p_company_id
   AND li.deleted_at         IS NULL
  WHERE v.company_id     = p_company_id
    AND v.deleted_at     IS NULL
    AND v.visit_status   = 'COMPLETED'
    AND v.scheduled_date BETWEEN p_start AND p_end
    AND UPPER(COALESCE(v.title, '')) NOT LIKE '%BILLING%'
    AND (
      (SELECT auth.uid()) IS NULL
      OR EXISTS (
        SELECT 1 FROM user_profiles up
        WHERE up.id = (SELECT auth.uid())
          AND up.role = 'admin'
          AND up.company_id = p_company_id
      )
    )
  GROUP BY ju.name, ju.external_id, j.dept_prefix, j.is_recurring
  ORDER BY ju.name, j.dept_prefix NULLS LAST
$$;


ALTER FUNCTION public.get_visits_report(p_company_id uuid, p_start date, p_end date) OWNER TO postgres;

--
-- Name: get_visits_report_detail(uuid, date, date, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_visits_report_detail(p_company_id uuid, p_start date, p_end date, p_tech_external_id text) RETURNS TABLE(visit_id uuid, scheduled_date date, client_name text, job_title text, dept_prefix text, is_recurring boolean, total_value numeric)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT
    v.id,
    v.scheduled_date,
    c.name,
    j.title,
    j.dept_prefix,
    j.is_recurring,
    COALESCE(SUM(li.total), 0) AS total_value
  FROM visits v
  CROSS JOIN LATERAL unnest(v.tech_external_user_ids) AS tech_gid
  LEFT JOIN clients c ON c.id = v.client_id AND c.deleted_at IS NULL
  LEFT JOIN jobs j    ON j.id = v.job_id     AND j.deleted_at IS NULL
  LEFT JOIN line_items li
    ON li.parent_external_id = v.external_id
   AND li.parent_type        = 'visit'
   AND li.deleted_at         IS NULL
  WHERE v.company_id     = p_company_id
    AND v.deleted_at     IS NULL
    AND v.visit_status   = 'COMPLETED'
    AND v.scheduled_date BETWEEN p_start AND p_end
    AND tech_gid         = p_tech_external_id
    AND UPPER(COALESCE(v.title, '')) NOT LIKE '%BILLING%'
    AND (
      (SELECT auth.uid()) IS NULL
      OR EXISTS (
        SELECT 1 FROM user_profiles up
        WHERE up.id = (SELECT auth.uid())
          AND up.role = 'admin'
          AND up.company_id = p_company_id
      )
    )
  GROUP BY v.id, v.scheduled_date, c.name, j.title, j.dept_prefix, j.is_recurring
  ORDER BY v.scheduled_date DESC, c.name
$$;


ALTER FUNCTION public.get_visits_report_detail(p_company_id uuid, p_start date, p_end date, p_tech_external_id text) OWNER TO postgres;

--
-- Name: handle_new_user(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.handle_new_user() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_company_id uuid;
  v_domain text;
BEGIN
  v_domain := split_part(NEW.email, '@', 2);

  SELECT id INTO v_company_id
  FROM companies
  WHERE google_domain = v_domain
  LIMIT 1;

  IF v_company_id IS NOT NULL THEN
    INSERT INTO user_profiles (id, company_id, role,
      can_access_routing, can_access_lawn, can_access_call_log,
      can_access_responder, can_access_timesheet, can_access_books,
      can_access_tracker, can_access_hub)
    VALUES (NEW.id, v_company_id, 'user',
      false, false, false, false, false, false, false, true)
    ON CONFLICT (id) DO NOTHING;

    INSERT INTO hub_users (id, company_id, display_name)
    VALUES (
      NEW.id,
      v_company_id,
      COALESCE(NEW.raw_user_meta_data->>'full_name', split_part(NEW.email, '@', 1))
    )
    ON CONFLICT (id) DO NOTHING;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.handle_new_user() OWNER TO postgres;

