-- Name: hub_files_remove_tag(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.hub_files_remove_tag(p_company_id uuid, p_name text) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  updated_count integer;
BEGIN
  UPDATE hub_files
  SET tags = array_remove(tags, p_name)
  WHERE company_id = p_company_id
    AND p_name = ANY(tags);
  GET DIAGNOSTICS updated_count = ROW_COUNT;
  RETURN updated_count;
END;
$$;


