--
-- Name: mcp_rate_limit_hit(text, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.mcp_rate_limit_hit(p_key text, p_limit integer, p_window_seconds integer) RETURNS TABLE(allowed boolean, retry_after integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_window_start timestamptz;
  v_hits integer;
BEGIN
  v_window_start := to_timestamp(
    floor(extract(epoch FROM now()) / p_window_seconds) * p_window_seconds
  );

  INSERT INTO public.mcp_rate_limits (bucket_key, window_start, hits)
  VALUES (p_key, v_window_start, 1)
  ON CONFLICT (bucket_key, window_start)
  DO UPDATE SET hits = public.mcp_rate_limits.hits + 1
  RETURNING public.mcp_rate_limits.hits INTO v_hits;

  IF random() < 0.01 THEN
    DELETE FROM public.mcp_rate_limits WHERE window_start < now() - interval '1 hour';
  END IF;

  allowed := v_hits <= p_limit;
  retry_after := GREATEST(
    1,
    ceil(extract(epoch FROM (v_window_start + make_interval(secs => p_window_seconds) - now())))::integer
  );
  RETURN NEXT;
END;
$$;


ALTER FUNCTION public.mcp_rate_limit_hit(p_key text, p_limit integer, p_window_seconds integer) OWNER TO postgres;

--
-- Name: merge_contacts(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.merge_contacts(p_winner uuid, p_loser uuid, p_company uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  l public.txt_contacts%rowtype;
  v_win_direct  uuid;
  v_lose_direct uuid;
begin
  if p_winner = p_loser then
    raise exception 'Cannot merge a contact into itself';
  end if;

  select * into l from public.txt_contacts
    where id = p_loser and company_id = p_company and deleted_at is null;
  if not found then
    raise exception 'Loser contact not found in company';
  end if;

  if not exists (
    select 1 from public.txt_contacts
    where id = p_winner and company_id = p_company and deleted_at is null
  ) then
    raise exception 'Winner contact not found in company';
  end if;

  -- Direct SMS threads: partial-unique (company_id, contact_id) where kind='direct'.
  -- If both sides have one, fold the loser's messages into the winner's thread
  -- and drop the emptied loser thread so the later repoint can't collide.
  select id into v_win_direct  from public.txt_conversations
    where company_id = p_company and contact_id = p_winner and kind = 'direct' limit 1;
  select id into v_lose_direct from public.txt_conversations
    where company_id = p_company and contact_id = p_loser  and kind = 'direct' limit 1;
  if v_win_direct is not null and v_lose_direct is not null then
    update public.txt_messages set conversation_id = v_win_direct where conversation_id = v_lose_direct;
    delete from public.txt_conversation_contacts where conversation_id = v_lose_direct;
    delete from public.txt_conversations where id = v_lose_direct;
  end if;

  -- Dedup the composite-unique join tables (winner already holds the row) first.
  delete from public.contact_tag_assignments a
    where a.contact_id = p_loser
      and exists (select 1 from public.contact_tag_assignments b
                  where b.contact_id = p_winner and b.tag_id = a.tag_id);
  delete from public.email_automation_enrollments a
    where a.contact_id = p_loser
      and exists (select 1 from public.email_automation_enrollments b
                  where b.contact_id = p_winner and b.automation_id = a.automation_id);
  delete from public.txt_broadcast_recipients a
    where a.contact_id = p_loser
      and exists (select 1 from public.txt_broadcast_recipients b
                  where b.contact_id = p_winner and b.broadcast_id = a.broadcast_id);
  delete from public.txt_conversation_contacts a
    where a.contact_id = p_loser
      and exists (select 1 from public.txt_conversation_contacts b
                  where b.contact_id = p_winner and b.conversation_id = a.conversation_id);

  -- Repoint all history loser -> winner.
  update public.calls                        set contact_id = p_winner where contact_id = p_loser;
  update public.contact_tag_assignments      set contact_id = p_winner where contact_id = p_loser;
  update public.drip_enrollments             set contact_id = p_winner where contact_id = p_loser;
  update public.email_automation_enrollments set contact_id = p_winner where contact_id = p_loser;
  update public.email_campaign_recipients    set contact_id = p_winner where contact_id = p_loser;
  update public.inbox_threads                set contact_id = p_winner where contact_id = p_loser;
  update public.txt_broadcast_recipients     set contact_id = p_winner where contact_id = p_loser;
  update public.txt_conversation_contacts    set contact_id = p_winner where contact_id = p_loser;
  update public.txt_conversations            set contact_id = p_winner where contact_id = p_loser;
  update public.txt_messages                 set contact_id = p_winner where contact_id = p_loser;
  update public.voicemails                   set contact_id = p_winner where contact_id = p_loser;

  -- Free the loser's unique keys + soft-delete BEFORE copying onto the winner,
  -- so the winner adopting the loser's phone/email can't trip the
  -- (company_id, phone_digits) / lower(email) partial-unique indexes.
  update public.txt_contacts set
    phone = null, phone_digits = null, email = null,
    in_directory = false, deleted_at = now(), updated_at = now()
  where id = p_loser;

  -- Fill blanks on the winner from the captured loser row; never overwrite.
  update public.txt_contacts w set
    email            = coalesce(w.email, l.email),
    phone            = coalesce(w.phone, l.phone),
    phone_digits     = coalesce(w.phone_digits, l.phone_digits),
    first_name       = coalesce(w.first_name, l.first_name),
    last_name        = coalesce(w.last_name, l.last_name),
    company_name     = coalesce(w.company_name, l.company_name),
    is_company       = w.is_company or l.is_company,
    address_line1    = coalesce(w.address_line1, l.address_line1),
    address_line2    = coalesce(w.address_line2, l.address_line2),
    city             = coalesce(w.city, l.city),
    state            = coalesce(w.state, l.state),
    postal_code      = coalesce(w.postal_code, l.postal_code),
    country          = coalesce(w.country, l.country),
    jobber_client_id = coalesce(w.jobber_client_id, l.jobber_client_id),
    notes            = case
                         when coalesce(l.notes,'') = '' then w.notes
                         when coalesce(w.notes,'') = '' then l.notes
                         else w.notes || E'\n\n— merged —\n' || l.notes
                       end,
    do_not_text      = w.do_not_text or l.do_not_text,
    sources          = (select array(select distinct e
                          from unnest(coalesce(w.sources,'{}'::text[]) || coalesce(l.sources,'{}'::text[])) e)),
    manually_edited  = true,
    in_directory     = true,
    updated_at       = now()
  where w.id = p_winner;
end;
$$;


ALTER FUNCTION public.merge_contacts(p_winner uuid, p_loser uuid, p_company uuid) OWNER TO postgres;

--
-- Name: recurring_program_cadence_check(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.recurring_program_cadence_check(p_company_id uuid) RETURNS TABLE(line_item_name text, display_name text, dept_prefix text, is_auxiliary boolean, declared_per_year integer, live_jobs integer, measured_rounds_typical integer, measured_rounds_min integer, measured_rounds_max integer)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
  with defs as (select * from public.recurring_program_definitions where company_id = p_company_id),
  live_jobs as (
    select j.id from public.jobs j join public.clients c on c.id = j.client_id
    where j.company_id = p_company_id and j.is_recurring = true and j.job_status <> 'archived'
      and j.deleted_at is null and coalesce(j.title,'') not ilike '%billing%'
      and not (coalesce(c.email,'') ilike '%fakemail%'
               or regexp_replace(coalesce(c.phone,''),'\D','','g') = '2812540991')
  ),
  job_program as (
    select distinct d.line_item_name, lj.id as job_id
    from public.line_items li
    join live_jobs lj on lj.id = li.parent_id
    join defs d on d.line_item_name = regexp_replace(li.name, '\s*-\s*T[0-9]+$', '')
    where li.company_id = p_company_id and li.parent_type = 'job' and li.deleted_at is null
  ),
  job_rounds as (
    select jp.line_item_name, jp.job_id, count(*) filter (where t.new_round) as rounds
    from job_program jp
    cross join lateral (
      select coalesce(lag(v.scheduled_date) over (order by v.scheduled_date) < v.scheduled_date - 3, true) as new_round
      from public.visits v
      where v.job_id = jp.job_id and v.deleted_at is null
        and v.scheduled_date >= current_date and v.scheduled_date < current_date + 365
    ) t
    group by jp.line_item_name, jp.job_id
  )
  select d.line_item_name, d.display_name, d.dept_prefix, d.is_auxiliary,
    d.visits_per_year::integer,
    (select count(*) from job_program jp where jp.line_item_name = d.line_item_name)::integer,
    (select mode() within group (order by jr.rounds) from job_rounds jr
      where jr.line_item_name = d.line_item_name and jr.rounds > 0)::integer,
    (select min(jr.rounds) from job_rounds jr where jr.line_item_name = d.line_item_name and jr.rounds > 0)::integer,
    (select max(jr.rounds) from job_rounds jr where jr.line_item_name = d.line_item_name and jr.rounds > 0)::integer
  from defs d order by d.is_auxiliary, d.dept_prefix, d.display_name
$_$;


ALTER FUNCTION public.recurring_program_cadence_check(p_company_id uuid) OWNER TO postgres;

--
-- Name: recurring_services_move_upgraded(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.recurring_services_move_upgraded() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF NEW.cancelled_status = 'Upgraded' THEN
    NEW.monday_group = 'Upgraded';
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.recurring_services_move_upgraded() OWNER TO postgres;

--
-- Name: recurring_unmapped_line_items(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.recurring_unmapped_line_items(p_company_id uuid) RETURNS TABLE(line_item_name text, live_jobs integer, per_visit_total numeric, guessed_prefix text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
  with live_jobs as (
    select j.id from public.jobs j join public.clients c on c.id = j.client_id
    where j.company_id = p_company_id and j.is_recurring = true and j.job_status <> 'archived'
      and j.deleted_at is null and coalesce(j.title,'') not ilike '%billing%'
      and not (coalesce(c.email,'') ilike '%fakemail%'
               or regexp_replace(coalesce(c.phone,''),'\D','','g') = '2812540991')
  ),
  defs as (select line_item_name from public.recurring_program_definitions where company_id = p_company_id)
  select
    regexp_replace(li.name, '\s*-\s*T[0-9]+$', '')            as line_item_name,
    count(distinct li.parent_id)::integer                     as live_jobs,
    round(sum(li.total)::numeric, 2)                          as per_visit_total,
    nullif(upper(split_part(regexp_replace(li.name, '\s*-\s*', '-', 'g'), '-', 1)), '') as guessed_prefix
  from public.line_items li
  join live_jobs lj on lj.id = li.parent_id
  where li.company_id = p_company_id and li.parent_type = 'job' and li.deleted_at is null
    and li.name not ilike '%discount%'
    and regexp_replace(li.name, '\s*-\s*T[0-9]+$', '') not in (select line_item_name from defs)
  group by 1, 4
  having sum(li.total) <> 0          -- a $0 line adds nothing to the book either way
  order by round(sum(li.total)::numeric, 2) desc
$_$;


ALTER FUNCTION public.recurring_unmapped_line_items(p_company_id uuid) OWNER TO postgres;

--
-- Name: route_capacity_sync_date(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.route_capacity_sync_date() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.sync_date IS NULL THEN NEW.sync_date = CURRENT_DATE; END IF;
  ELSIF TG_OP = 'UPDATE' THEN
    IF NEW.name IS DISTINCT FROM OLD.name THEN NEW.sync_date = CURRENT_DATE; END IF;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.route_capacity_sync_date() OWNER TO postgres;

--
-- Name: scoreboard_board_technicians(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.scoreboard_board_technicians(p_company_id uuid, p_board_slug text) RETURNS TABLE(employee_id uuid, jobber_external_id text, display_name text, salesperson_name text)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT
    e.id AS employee_id,
    (SELECT ju.external_id FROM jobber_users ju
      WHERE ju.company_id = e.company_id
        AND ju.name ILIKE '%' || e.last_name || '%'
        AND (ju.name ILIKE '%' || e.first_name || '%'
             OR (NULLIF(e.preferred_name, '') IS NOT NULL AND ju.name ILIKE '%' || e.preferred_name || '%'))
      ORDER BY ju.is_active DESC NULLS LAST, ju.external_id
      LIMIT 1) AS jobber_external_id,
    COALESCE(NULLIF(e.preferred_name, ''), e.first_name) || ' ' || e.last_name AS display_name,
    COALESCE(NULLIF(e.preferred_name, ''), e.first_name) AS salesperson_name
  FROM public.scoreboard_technicians st
  JOIN public.employees e ON e.id = st.employee_id AND e.company_id = p_company_id
  WHERE st.company_id = p_company_id
    AND st.board_slug = p_board_slug
    AND e.is_active
    AND (
      (SELECT auth.uid()) IS NULL
      OR EXISTS (
        SELECT 1 FROM public.user_profiles up
        WHERE up.id = (SELECT auth.uid())
          AND up.company_id = p_company_id
          AND (up.role = 'admin' OR up.can_access_scoreboards)
      )
    )
  ORDER BY e.last_name, e.first_name
$$;


ALTER FUNCTION public.scoreboard_board_technicians(p_company_id uuid, p_board_slug text) OWNER TO postgres;

--
-- Name: scoreboard_channel_scorecard(uuid, date, date, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.scoreboard_channel_scorecard(p_company_id uuid, p_start date, p_end date, p_credit_rule text DEFAULT 'acquisition'::text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  with allowed as (select public.scoreboard_reports_allowed(p_company_id) ok),
  rule as (
    select case when p_credit_rule = 'recent_touch' then 'recent_touch' else 'acquisition' end c
  ),
  sale_stages as (
    select key from tracker_stages
    where company_id = p_company_id and counts_as_sale and key <> 'closed_won'
  ),
  lead_side as (
    select
      coalesce(public.churn_normalize_source(p_company_id, l.lead_source), 'Other / Unknown') as src,
      count(*)                                                          as leads,
      count(*) filter (where l.stage = 'closed_won')                    as closed_won,
      count(*) filter (where l.stage = 'closed_lost')                   as closed_lost,
      count(*) filter (where l.stage in (select key from sale_stages))  as sold_other,
      count(*) filter (where l.stage not in ('closed_won','closed_lost','closed_other')
                         and l.stage not in (select key from sale_stages)) as still_open,
      coalesce(sum(l.annual_value) filter (
        where l.stage = 'closed_won' or l.stage in (select key from sale_stages)
      ), 0)                                                             as tracker_value_sold
    from leads l, allowed a
    where a.ok
      and l.company_id = p_company_id
      and l.lead_creation_date >= p_start
      and l.lead_creation_date <= p_end
    group by 1
  ),
  scoped as (
    select i.id, i.client_id, i.total, coalesce(i.payments_total, 0) as paid
    from invoices i, allowed a
    where a.ok
      and i.company_id = p_company_id
      and i.deleted_at is null
      and i.issued_date >= p_start
      and i.issued_date <= p_end
  ),
  cli as (
    select distinct c.id, c.email, c.phone, c.name,
      public.churn_normalize_source(
        p_company_id, nullif(btrim(c.custom_fields->'HLC105 Lead Source'->>'value'), '')
      ) as jobber_src
    from scoped s join clients c on c.id = s.client_id
    where c.company_id = p_company_id
  ),
  labelled as (
    select cli.id, cli.jobber_src,
      (
        select public.churn_normalize_source(p_company_id, l.lead_source)
        from leads l
        where l.company_id = p_company_id
          and coalesce(l.lead_source, '') <> ''
          and (
            (coalesce(cli.email, '') <> '' and lower(l.email) = lower(cli.email))
            or (regexp_replace(coalesce(cli.phone, ''), '\D', '', 'g') <> ''
                and regexp_replace(coalesce(l.phone, ''), '\D', '', 'g')
                  = regexp_replace(coalesce(cli.phone, ''), '\D', '', 'g'))
            or (coalesce(cli.name, '') <> ''
                and lower(btrim(coalesce(l.first_name, '') || ' ' || coalesce(l.last_name, '')))
                  = lower(btrim(cli.name)))
          )
        order by l.created_at desc nulls last
        limit 1
      ) as tracker_src
    from cli
  ),
  money as (
    select
      coalesce(
        case when (select c from rule) = 'recent_touch'
             then coalesce(b.tracker_src, b.jobber_src)
             else coalesce(b.jobber_src, b.tracker_src) end,
        'Other / Unknown'
      ) as src,
      round(sum(s.total), 2)        as revenue,
      round(sum(s.paid), 2)         as collected,
      count(distinct b.id)          as customers,
      count(*)                      as invoices
    from scoped s join labelled b on b.id = s.client_id
    group by 1
  ),
  spend as (
    select ms.source as src, sum(ms.amount) as spend, count(*) as months
    from marketing_spend ms, allowed a
    where a.ok
      and ms.company_id = p_company_id
      and ms.period_start >= date_trunc('month', p_start)::date
      and ms.period_start <= p_end
    group by 1
  ),
  merged as (
    select
      coalesce(l.src, m.src, sp.src)                as source,
      coalesce(l.leads, 0)                          as leads,
      coalesce(l.closed_won, 0)                     as closed_won,
      coalesce(l.closed_lost, 0)                    as closed_lost,
      coalesce(l.sold_other, 0)                     as sold_other,
      coalesce(l.still_open, 0)                     as still_open,
      coalesce(l.tracker_value_sold, 0)             as tracker_value_sold,
      coalesce(m.revenue, 0)                        as revenue,
      coalesce(m.collected, 0)                      as collected,
      coalesce(m.customers, 0)                      as customers,
      coalesce(m.invoices, 0)                       as invoices,
      sp.spend                                      as spend,
      coalesce(sp.months, 0)                        as spend_months
    from lead_side l
    full outer join money m on m.src = l.src
    full outer join spend sp on sp.src = coalesce(l.src, m.src)
  ),
  rows as (
    select g.*,
      coalesce(max(mm.source_group), 'Other') as source_group,
      coalesce(max(mm.cost_type), 'Unknown')  as cost_type
    from merged g
    left join lead_sources_master mm
      on mm.company_id = p_company_id and lower(mm.master_source) = lower(g.source)
    group by g.source, g.leads, g.closed_won, g.closed_lost, g.sold_other, g.still_open,
             g.tracker_value_sold, g.revenue, g.collected, g.customers, g.invoices,
             g.spend, g.spend_months
  )
  select case when not (select ok from allowed) then null::jsonb else jsonb_build_object(
    'credit_rule', (select c from rule),
    'leads',       coalesce((select sum(leads)::int      from rows), 0),
    'closed_won',  coalesce((select sum(closed_won)::int from rows), 0),
    'closed_lost', coalesce((select sum(closed_lost)::int from rows), 0),
    'revenue',     coalesce((select round(sum(revenue),2) from rows), 0),
    'customers',   coalesce((select sum(customers)::int  from rows), 0),
    'spend',       (select sum(spend) from rows where spend is not null),
    'has_spend',   exists (select 1 from rows where spend is not null),
    'by_source', coalesce((
      select jsonb_agg(x order by (x->>'revenue')::numeric desc, (x->>'leads')::int desc)
      from (
        select jsonb_build_object(
          'source',        source,
          'source_group',  source_group,
          'cost_type',     cost_type,
          'leads',         leads,
          'closed_won',    closed_won,
          'closed_lost',   closed_lost,
          'sold_other',    sold_other,
          'still_open',    still_open,
          'close_rate',    case when closed_won + closed_lost > 0
                                then round(100.0 * closed_won / (closed_won + closed_lost), 1)
                           end,
          'customers',     customers,
          'invoices',      invoices,
          'revenue',       revenue,
          'collected',     collected,
          'tracker_value_sold', tracker_value_sold,
          'spend',         spend,
          'spend_months',  spend_months,
          'revenue_per_lead',  case when leads > 0 then round(revenue / leads, 2) end,
          'cost_per_lead',     case when spend is not null and leads > 0 then round(spend / leads, 2) end,
          'cost_per_customer', case when spend is not null and customers > 0 then round(spend / customers, 2) end,
          'roas',              case when spend is not null and spend > 0 then round(revenue / spend, 2) end
        ) x
        from rows
      ) y
    ), '[]'::jsonb)
  ) end
$$;


ALTER FUNCTION public.scoreboard_channel_scorecard(p_company_id uuid, p_start date, p_end date, p_credit_rule text) OWNER TO postgres;

--
-- Name: scoreboard_churn_summary(uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.scoreboard_churn_summary(p_company_id uuid, p_year integer) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  result jsonb;
  ys date := make_date(p_year, 1, 1);
  ye date := make_date(p_year + 1, 1, 1);
begin
  if (select auth.uid()) is not null and not exists (
    select 1 from public.user_profiles up
    where up.id = (select auth.uid())
      and up.company_id = p_company_id
      and (up.role = 'admin' or up.can_access_scoreboards)
  ) then
    raise exception 'not authorized';
  end if;

  with scope as (
    select rs.*,
      (rs.sold_date < ye and (rs.cancel_date is null or rs.cancel_date >= ys)) as on_book,
      (rs.cancelled_status = 'Cancelled' and rs.cancel_date >= ys and rs.cancel_date < ye) as churned_in_year
    from public.recurring_services rs
    where rs.company_id = p_company_id
  ),
  ch as (
    select s.annual_value, s.cancel_date,
      coalesce(m.master_reason, nullif(btrim(coalesce(s.cancellation_reason,'')),''), 'Unknown') as reason_master,
      coalesce(m.churn_type, 'Review')          as churn_type,
      coalesce(m.in_gross_churn, true)          as in_gross,
      coalesce(m.in_controllable_churn, false)  as in_ctrl
    from scope s
    left join lateral public.churn_map_reason(p_company_id, s.cancellation_reason) m on true
    where s.churned_in_year
  ),
  base as (
    select
      (select count(*) from scope where on_book)                                          as book_size,
      (select count(*) from scope where cancelled_status = 'Active')                       as active_now,
      (select count(*) from scope where extract(year from sold_date) = p_year)             as new_in_year,
      (select coalesce(sum(annual_value),0) from scope where cancelled_status = 'Active')  as active_annual_value,
      count(*) filter (where in_gross)                                                     as churned_gross,
      count(*) filter (where in_ctrl)                                                      as churned_ctrl,
      count(*) filter (where churn_type = 'Company-Initiated')                             as churned_company,
      count(*) filter (where churn_type = 'Uncontrollable')                                as churned_uncontrollable,
      count(*) filter (where churn_type = 'Review')                                        as churned_review,
      coalesce(sum(annual_value) filter (where in_gross), 0)                               as churned_annual_value
    from ch
  )
  select jsonb_build_object(
    'year', p_year,
    'book_size', b.book_size,
    'active_now', b.active_now,
    'new_in_year', b.new_in_year,
    'churned_gross', b.churned_gross,
    'churned_controllable', b.churned_ctrl,
    'churned_company_initiated', b.churned_company,
    'churned_uncontrollable', b.churned_uncontrollable,
    'churned_review', b.churned_review,
    'churned_annual_value', b.churned_annual_value,
    'active_annual_value', b.active_annual_value,
    'retention_pct', case when b.book_size > 0 then round(100.0 * (b.book_size - b.churned_gross) / b.book_size, 1) end,
    'gross_churn_pct', case when b.book_size > 0 then round(100.0 * b.churned_gross / b.book_size, 1) end,
    'controllable_churn_pct', case when b.book_size > 0 then round(100.0 * b.churned_ctrl / b.book_size, 1) end,
    'by_reason', (
      select coalesce(jsonb_agg(jsonb_build_object(
        'reason', reason_master, 'churn_type', churn_type, 'count', n, 'annual_value', av) order by n desc), '[]'::jsonb)
      from (select reason_master, churn_type, count(*) n, coalesce(sum(annual_value),0) av from ch group by 1,2) x
    ),
    'by_type', (
      select coalesce(jsonb_agg(jsonb_build_object(
        'churn_type', churn_type, 'count', n, 'annual_value', av) order by n desc), '[]'::jsonb)
      from (select churn_type, count(*) n, coalesce(sum(annual_value),0) av from ch group by 1) x
    ),
    'monthly', (
      select coalesce(jsonb_agg(jsonb_build_object(
        'month', mon, 'gross', gross_n, 'controllable', ctrl_n) order by mon), '[]'::jsonb)
      from (select to_char(cancel_date,'YYYY-MM') mon,
                   count(*) filter (where in_gross) gross_n,
                   count(*) filter (where in_ctrl) ctrl_n
            from ch group by 1) x
    )
  ) into result
  from base b;

  return result;
end
$$;


ALTER FUNCTION public.scoreboard_churn_summary(p_company_id uuid, p_year integer) OWNER TO postgres;

--
-- Name: scoreboard_clients(uuid, date, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.scoreboard_clients(p_company_id uuid, p_start date, p_end date) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  with allowed as (select public.scoreboard_reports_allowed(p_company_id) ok),
  base as (
    select c.id, c.name, c.external_created_at, c.is_lead, c.is_archived, c.balance
    from clients c
    where c.company_id = p_company_id and c.deleted_at is null
  ),
  -- A "client" excludes rows Jobber still holds as leads: they have not bought
  -- anything, and counting them would inflate the base and deflate every average.
  customers as (select * from base where not coalesce(is_lead, false)),
  billed as (
    select i.client_id, sum(i.total) amt, count(*) invoices,
           min(i.issued_date) first_billed, max(i.issued_date) last_billed
    from invoices i
    where i.company_id = p_company_id and i.deleted_at is null
      and i.invoice_status <> 'draft'
      and i.issued_date between p_start and p_end
    group by i.client_id
  ),
  -- Billing across ALL history we hold, for the per-client table. Deliberately NOT
  -- called lifetime: the invoice mirror starts at the Jobber backfill floor, which
  -- is later than the oldest client, so "total spend" here means "billed since we
  -- started holding invoices" and the widgets say so.
  billed_all as (
    select i.client_id, sum(i.total) amt, count(*) invoices,
           min(i.issued_date) first_billed, max(i.issued_date) last_billed
    from invoices i
    where i.company_id = p_company_id and i.deleted_at is null and i.invoice_status <> 'draft'
    group by i.client_id
  ),
  recurring as (
    select count(*) filter (where cancel_date is null) active_services,
           coalesce(sum(annual_value) filter (where cancel_date is null), 0) annual_value
    from recurring_services where company_id = p_company_id
  )
  select case when not (select ok from allowed) then null else jsonb_build_object(
    'coverage', jsonb_build_object(
      'first_client',  (select (min(external_created_at) at time zone 'America/Chicago')::date from base),
      -- The billing floor. Any "total spend" figure starts here, not at the
      -- client's first job, so nothing on this page may be called lifetime value.
      'first_invoice', (select min(issued_date) from invoices where company_id = p_company_id and deleted_at is null),
      'requested_start', p_start,
      'requested_end', p_end
    ),
    'clients_total',    (select count(*) from customers),
    'clients_active',   (select count(*) from customers where not coalesce(is_archived, false)),
    'clients_archived', (select count(*) from customers where coalesce(is_archived, false)),
    'leads_open',       (select count(*) from base where coalesce(is_lead, false)),

    'new_in_window', (select count(*) from customers
                      where (external_created_at at time zone 'America/Chicago')::date between p_start and p_end),
    'new_30d',       (select count(*) from customers where external_created_at >= now() - interval '30 days'),

    'billed_clients',  (select count(*) from billed),
    'billed_total',    coalesce((select round(sum(amt), 2) from billed), 0),
    'billed_avg',      (select round(avg(amt), 2) from billed),

    'recurring_services', (select active_services from recurring),
    'recurring_annual_value', (select round(annual_value, 2) from recurring),

    'new_by_month', coalesce((
      select jsonb_agg(m order by m->>'month')
      from (
        select jsonb_build_object(
          'month', to_char(date_trunc('month', (external_created_at at time zone 'America/Chicago')), 'YYYY-MM'),
          'count', count(*)
        ) m
        from customers
        where (external_created_at at time zone 'America/Chicago')::date between p_start and p_end
        group by date_trunc('month', (external_created_at at time zone 'America/Chicago'))
      ) x
    ), '[]'::jsonb),

    -- Service area from property addresses. One row per client-city pair so a
    -- client with two properties in one city is counted once for that city.
    'by_city', coalesce((
      select jsonb_agg(c order by (c->>'clients')::int desc)
      from (
        select jsonb_build_object('city', city, 'clients', count(distinct client_id)) c
        from (
          select distinct p.client_id, initcap(trim(p.city)) city
          from properties p
          join customers cu on cu.id = p.client_id
          where p.company_id = p_company_id and p.deleted_at is null
            and nullif(trim(p.city), '') is not null
        ) z
        group by city
      ) y
    ), '[]'::jsonb),

    'top_clients', coalesce((
      select jsonb_agg(t order by (t->>'billed')::numeric desc)
      from (
        select jsonb_build_object(
          'client_id', cu.id,
          'name', coalesce(nullif(trim(cu.name), ''), 'Unnamed client'),
          'billed', round(ba.amt, 2),
          'invoices', ba.invoices,
          'first_billed', ba.first_billed,
          'last_billed', ba.last_billed,
          'days_since_last', (current_date - ba.last_billed),
          'archived', coalesce(cu.is_archived, false)
        ) t
        from billed_all ba
        join customers cu on cu.id = ba.client_id
        order by ba.amt desc
        limit 50
      ) w
    ), '[]'::jsonb)
  ) end;
$$;


ALTER FUNCTION public.scoreboard_clients(p_company_id uuid, p_start date, p_end date) OWNER TO postgres;

--
-- Name: FUNCTION scoreboard_clients(p_company_id uuid, p_start date, p_end date); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.scoreboard_clients(p_company_id uuid, p_start date, p_end date) IS 'Clients report 8.4. Per-client spend is billed-since-the-invoice-floor, NEVER lifetime value: the invoice mirror starts later than the oldest client. Leads are excluded from client counts. No residential/commercial split - is_company is unpopulated (15 of 1663).';


--
-- Name: scoreboard_clients_geo(uuid, date, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.scoreboard_clients_geo(p_company_id uuid, p_start date, p_end date) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  -- Per-ZIP geography for the Clients report: where the money and the customers are.
  --
  -- Jobber-native throughout — clients, properties, jobs and invoices — deliberately
  -- NOT recurring_services, which is the stale imported board.
  --
  -- ⚠ ZIPs are normalised to their 5-digit prefix, because the mirror holds ZIP+4
  -- forms ('77354-4141') that would otherwise split a ZIP into two dots.
  -- ⚠ Leads are excluded, matching every other figure on the Clients report — they
  -- have bought nothing and would inflate the counts.
  with allowed as (select public.scoreboard_reports_allowed(p_company_id) ok),
  -- One ZIP per client. A client with several properties is counted once, at the
  -- lowest ZIP, so the customer counts across the map still sum to the customer count.
  cz as (
    select c.id client_id,
           min(substring(trim(p.zip) from '^[0-9]{5}')) zip
    from clients c
    join properties p on p.client_id = c.id and p.deleted_at is null
    where c.company_id = p_company_id and c.deleted_at is null
      and coalesce(c.is_lead, false) = false
      and substring(trim(p.zip) from '^[0-9]{5}') is not null
    group by c.id
  ),
  -- Billed in the window. Drafts excluded, same rule the Revenue report uses.
  rev as (
    select cz.zip, sum(i.total) amount
    from invoices i join cz on cz.client_id = i.client_id
    where i.company_id = p_company_id and i.deleted_at is null
      and coalesce(i.invoice_status,'') <> 'draft'
      and i.issued_date between p_start and p_end
    group by cz.zip
  ),
  -- Recurring is point-in-time (who is on the book now); one-off is windowed (who
  -- bought a job in the period). Different questions, so they are counted differently
  -- and each card says which.
  recur as (
    select cz.zip, count(distinct cz.client_id) n
    from cz join jobs j on j.client_id = cz.client_id
    where j.company_id = p_company_id and j.deleted_at is null
      and j.is_recurring and j.job_status <> 'archived'
    group by cz.zip
  ),
  oneoff as (
    select cz.zip, count(distinct cz.client_id) n
    from cz join jobs j on j.client_id = cz.client_id
    where j.company_id = p_company_id and j.deleted_at is null
      and not j.is_recurring
      and coalesce(j.external_created_at::date, j.start_at::date) between p_start and p_end
    group by cz.zip
  ),
  tot as (select zip, count(*) n from cz group by zip),
  joined as (
    select t.zip, z.lat, z.lng,
           coalesce(r.amount,0) revenue, coalesce(rc.n,0) recurring_clients,
           coalesce(o.n,0) oneoff_clients, t.n total_clients
    from tot t
    left join zip_centroids z on z.zip = t.zip
    left join rev r  on r.zip  = t.zip
    left join recur rc on rc.zip = t.zip
    left join oneoff o on o.zip = t.zip
  )
  select case when not (select ok from allowed) then null else jsonb_build_object(
    -- A ZIP with no centroid cannot be drawn. Reported, never dropped silently.
    'unmapped_zips',    (select count(*) from joined where lat is null),
    'unmapped_clients', (select coalesce(sum(total_clients),0) from joined where lat is null),
    'points', coalesce((select jsonb_agg(jsonb_build_object(
        'zip', zip, 'lat', lat, 'lng', lng,
        'revenue', round(revenue,2),
        'recurring_clients', recurring_clients,
        'oneoff_clients', oneoff_clients,
        'total_clients', total_clients
      ) order by revenue desc) from joined where lat is not null), '[]'::jsonb)
  ) end;
$$;


ALTER FUNCTION public.scoreboard_clients_geo(p_company_id uuid, p_start date, p_end date) OWNER TO postgres;

--
-- Name: scoreboard_commission_production(uuid, date, date, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.scoreboard_commission_production(p_company_id uuid, p_start date, p_end date, p_buckets text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  with allowed as (select public.scoreboard_reports_allowed(p_company_id) ok),
  buckets as (
    select split_part(t, ':', 1) as k,
           split_part(t, ':', 2)::date as s,
           split_part(t, ':', 3)::date as e,
           ord
    from unnest(string_to_array(coalesce(nullif(btrim(p_buckets), ''), ''), ',')) with ordinality as u(t, ord)
    where t <> '' and split_part(t, ':', 2) <> '' and split_part(t, ':', 3) <> ''
  ),
  span as (
    select least(p_start, coalesce((select min(s) from buckets), p_start)) as s,
           greatest(p_end, coalesce((select max(e) from buckets), p_end)) as e
  ),
  roster as (
    select e.id as employee_id,
      (select ju.external_id from jobber_users ju
        where ju.company_id = e.company_id and ju.name ilike '%' || e.last_name || '%'
          and (ju.name ilike '%' || e.first_name || '%'
               or (nullif(e.preferred_name,'') is not null and ju.name ilike '%' || e.preferred_name || '%'))
        order by ju.is_active desc nulls last, ju.external_id limit 1) as jobber_id
    from employees e
    where e.company_id = p_company_id
  ),
  vis as (
    select v.id, v.scheduled_date as d, v.tech_external_user_ids as techs,
           coalesce((select sum(li.total) from line_items li
                      where li.parent_type = 'visit' and li.parent_id = v.id
                        and li.deleted_at is null), 0)
             / nullif(array_length(v.tech_external_user_ids, 1), 0) as share
    from visits v, span
    where v.company_id = p_company_id
      and v.deleted_at is null
      and v.visit_status = 'COMPLETED'
      and v.scheduled_date between span.s and span.e
      and array_length(v.tech_external_user_ids, 1) > 0
  ),
  tech_day as (
    select t.tid, v.d, sum(v.share) amt
    from vis v cross join lateral unnest(v.techs) t(tid)
    where v.share is not null
    group by 1, 2
  ),
  emp_day as (
    select te.employee_id, te.date as d, sum(te.total_hours) hours
    from time_entries te, span
    where te.company_id = p_company_id
      and te.total_hours > 0
      and te.date between span.s and span.e
    group by 1, 2
  ),
  bucket_span as (
    select min(s) as s, max(e) as e from buckets
  ),
  win as (
    select r.employee_id, r.jobber_id,
      coalesce((select round(sum(td.amt), 2) from tech_day td
                 where td.tid = r.jobber_id and td.d between p_start and p_end), 0) as revenue,
      coalesce((select round(sum(ed.hours), 2) from emp_day ed
                 where ed.employee_id = r.employee_id and ed.d between p_start and p_end), 0) as hours,
      coalesce((select round(sum(td.amt), 2) from tech_day td, bucket_span bs
                 where td.tid = r.jobber_id and td.d between bs.s and bs.e), 0) as weeks_revenue,
      coalesce((select round(sum(ed.hours), 2) from emp_day ed, bucket_span bs
                 where ed.employee_id = r.employee_id and ed.d between bs.s and bs.e), 0) as weeks_hours
    from roster r
  ),
  per_bucket as (
    select r.employee_id, b.ord, b.k,
      coalesce((select round(sum(td.amt), 2) from tech_day td
                 where td.tid = r.jobber_id and td.d between b.s and b.e), 0) as revenue,
      coalesce((select round(sum(ed.hours), 2) from emp_day ed
                 where ed.employee_id = r.employee_id and ed.d between b.s and b.e), 0) as hours,
      b.s, b.e
    from roster r cross join buckets b
  )
  select case when not (select ok from allowed) then null else jsonb_build_object(
    'coverage', jsonb_build_object(
      'requested_start', p_start,
      'requested_end', p_end,
      'timeclock_first', (select min(d) from emp_day),
      'timeclock_last', (select max(d) from emp_day),
      'revenue_dated_by', 'scheduled_date',
      'tech_credit', 'split',
      'buckets', (select count(*) from buckets)
    ),
    'people', coalesce((
      select jsonb_agg(jsonb_build_object(
        'employee_id', w.employee_id,
        'attributable', (w.jobber_id is not null),
        'revenue', w.revenue,
        'hours', w.hours,
        'rev_per_hour', case when w.hours > 0 then round(w.revenue / w.hours, 2) end,
        'weeks_revenue', case when (select count(*) from buckets) > 0 then w.weeks_revenue end,
        'weeks_hours', case when (select count(*) from buckets) > 0 then w.weeks_hours end,
        'weeks_rev_per_hour', case when w.weeks_hours > 0 then round(w.weeks_revenue / w.weeks_hours, 2) end,
        'buckets', coalesce((
          select jsonb_agg(jsonb_build_object(
            'k', pb.k, 'start', pb.s, 'end', pb.e,
            'revenue', pb.revenue, 'hours', pb.hours,
            'rev_per_hour', case when pb.hours > 0 then round(pb.revenue / pb.hours, 2) end
          ) order by pb.ord)
          from per_bucket pb where pb.employee_id = w.employee_id), '[]'::jsonb)
      ))
      from win w), '[]'::jsonb)
  ) end;
$$;


ALTER FUNCTION public.scoreboard_commission_production(p_company_id uuid, p_start date, p_end date, p_buckets text) OWNER TO postgres;

--
-- Name: scoreboard_communications(uuid, date, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.scoreboard_communications(p_company_id uuid, p_start date, p_end date) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  with allowed as (select public.scoreboard_reports_allowed(p_company_id) ok),
  inbound as (
    select c.id, c.created_at, c.answered_at, c.duration_seconds, c.handled_by_ai,
      (c.answered_at is not null and not c.handled_by_ai) as human_answered,
      c.handled_by_ai as ai_answered,
      (c.answered_at is null and not c.handled_by_ai) as missed,
      exists (select 1 from voicemails v where v.call_id = c.id) as left_voicemail
    from calls c
    where c.company_id = p_company_id
      and c.direction = 'inbound'
      and (c.created_at at time zone 'America/Chicago')::date between p_start and p_end
  ),
  outbound as (
    select c.id from calls c
    where c.company_id = p_company_id and c.direction = 'outbound'
      and (c.created_at at time zone 'America/Chicago')::date between p_start and p_end
  ),
  -- Speed to answer, human pickups only. Bounded to 10 minutes: a handful of rows
  -- carry a stale answered_at from a stuck leg, and one 4-hour outlier would move
  -- an average that is otherwise measured in seconds.
  answer_times as (
    select extract(epoch from (answered_at - created_at)) secs
    from inbound
    where human_answered and answered_at >= created_at
      and answered_at - created_at < interval '10 minutes'
  ),
  texts as (
    select m.direction, m.created_at, m.status, m.conversation_id
    from txt_messages m
    where m.company_id = p_company_id
      and (m.created_at at time zone 'America/Chicago')::date between p_start and p_end
  ),
  -- Reply time = an inbound text followed by an outbound one in the same thread.
  -- Capped at 24h so an answer three days later doesn't masquerade as responsiveness.
  reply_seq as (
    select direction, created_at,
      lead(created_at) over (partition by conversation_id order by created_at) nxt_at,
      lead(direction)  over (partition by conversation_id order by created_at) nxt_dir
    from texts
  ),
  replies as (
    select extract(epoch from (nxt_at - created_at)) secs
    from reply_seq
    where direction = 'inbound' and nxt_dir = 'outbound'
      and nxt_at - created_at between interval '0' and interval '24 hours'
  ),
  vm as (
    select v.id, v.heard_at, v.deleted_at
    from voicemails v
    where v.company_id = p_company_id
      and (v.created_at at time zone 'America/Chicago')::date between p_start and p_end
  )
  select case when not (select ok from allowed) then null else jsonb_build_object(
    'coverage', jsonb_build_object(
      'first_call', (select (min(created_at) at time zone 'America/Chicago')::date from calls where company_id = p_company_id),
      'first_text', (select (min(created_at) at time zone 'America/Chicago')::date from txt_messages where company_id = p_company_id),
      'requested_start', p_start,
      'requested_end', p_end
    ),
    'inbound_calls',   (select count(*) from inbound),
    'outbound_calls',  (select count(*) from outbound),
    'answered_human',  (select count(*) filter (where human_answered) from inbound),
    'answered_ai',     (select count(*) filter (where ai_answered) from inbound),
    'missed',          (select count(*) filter (where missed) from inbound),
    'missed_pct',      (select case when count(*) > 0
                          then round(100.0 * count(*) filter (where missed) / count(*), 1) end from inbound),
    'missed_with_voicemail', (select count(*) filter (where missed and left_voicemail) from inbound),
    'missed_no_message',     (select count(*) filter (where missed and not left_voicemail) from inbound),
    -- Under 5 seconds nobody could realistically have answered; counting these as
    -- service failures would overstate the problem.
    'missed_quick_hangup',   (select count(*) filter (where missed and coalesce(duration_seconds,0) <= 5) from inbound),
    'median_answer_sec', (select percentile_disc(0.5) within group (order by secs) from answer_times),
    'avg_answer_sec',    (select round(avg(secs)::numeric, 1) from answer_times),
    'answer_sample',     (select count(*) from answer_times),

    'texts_in',      (select count(*) filter (where direction='inbound') from texts),
    'texts_out',     (select count(*) filter (where direction='outbound') from texts),
    'texts_failed',  (select count(*) filter (where direction='outbound' and status in ('failed','undelivered')) from texts),
    'median_reply_sec', (select percentile_disc(0.5) within group (order by secs) from replies),
    'p90_reply_sec',    (select percentile_disc(0.9) within group (order by secs) from replies),
    'reply_sample',     (select count(*) from replies),

    'voicemails',        (select count(*) from vm),
    'voicemails_unheard',(select count(*) from vm where heard_at is null and deleted_at is null),

    'by_hour', coalesce((
      select jsonb_agg(h order by (h->>'hour')::int)
      from (
        select jsonb_build_object(
          'hour',    extract(hour from (created_at at time zone 'America/Chicago'))::int,
          'inbound', count(*),
          'missed',  count(*) filter (where missed)
        ) h
        from inbound
        group by extract(hour from (created_at at time zone 'America/Chicago'))::int
      ) x
    ), '[]'::jsonb),

    'by_weekday', coalesce((
      select jsonb_agg(d order by (d->>'dow')::int)
      from (
        select jsonb_build_object(
          'dow',     extract(dow from (created_at at time zone 'America/Chicago'))::int,
          'label',   trim(to_char((created_at at time zone 'America/Chicago'), 'Dy')),
          'inbound', count(*),
          'missed',  count(*) filter (where missed)
        ) d
        from inbound
        group by extract(dow from (created_at at time zone 'America/Chicago'))::int,
                 trim(to_char((created_at at time zone 'America/Chicago'), 'Dy'))
      ) y
    ), '[]'::jsonb)
  ) end;
$$;


ALTER FUNCTION public.scoreboard_communications(p_company_id uuid, p_start date, p_end date) OWNER TO postgres;

--
-- Name: FUNCTION scoreboard_communications(p_company_id uuid, p_start date, p_end date); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.scoreboard_communications(p_company_id uuid, p_start date, p_end date) IS 'Communications report 8.10 - Dialer + Txt responsiveness. Missed keys off answered_at, NOT status (completed means ended, not answered). Amber-handled calls count as answered. Coaching grades deliberately excluded: they are gated to can_access_coaching.';


--
-- Name: scoreboard_crew_labor(uuid, date, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.scoreboard_crew_labor(p_company_id uuid, p_start date, p_end date) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  with allowed as (select public.scoreboard_reports_allowed(p_company_id) ok),
  tc as (
    select min(te.date) first_day, max(te.date) last_day
    from time_entries te join employees e on e.id = te.employee_id
    where te.company_id = p_company_id and te.total_hours > 0
      and e.is_field_labor and e.pay_type = 'hourly'
  ),
  pay as (
    select min(period_start) pay_first, max(period_end) pay_last
    from payroll_periods
    where company_id = p_company_id and coalesce(flsa_status,'') <> 'Exempt'
  ),
  bounds as (
    select least(coalesce(tc.first_day, pay.pay_first), coalesce(pay.pay_first, tc.first_day)) data_first,
           least(coalesce(tc.last_day, pay.pay_last), coalesce(pay.pay_last, tc.last_day)) data_last,
           pay.pay_last, tc.last_day tc_last, tc.first_day tc_first
    from tc, pay
  ),
  eff as (
    select greatest(p_start, b.data_first) s, least(p_end, b.data_last) e,
           b.data_first, b.data_last, b.pay_last, b.tc_last, b.tc_first from bounds b
  ),
  -- The timeclock's OWN window, free of the payroll edge. greatest/least ignore nulls,
  -- so a company with no timeclock would otherwise get the full requested range here
  -- and report 0 hours as though it had measured them; ok carries that test explicitly.
  clock_eff as (
    select greatest(p_start, b.tc_first) s, least(p_end, b.tc_last) e,
           (b.tc_first is not null
            and greatest(p_start, b.tc_first) <= least(p_end, b.tc_last)) ok
    from bounds b
  ),
  tc_hours as (
    select te.employee_id, sum(te.total_hours) hours
    from time_entries te, eff
    where te.company_id = p_company_id and te.total_hours > 0
      and te.date between greatest(eff.s, coalesce(eff.tc_first, eff.s)) and eff.e
    group by 1
  ),
  -- Hours over the timeclock window rather than the payroll-clamped one. Same rows,
  -- same definition of an hour -- only the right-hand edge differs.
  tc_hours_full as (
    select te.employee_id, sum(te.total_hours) hours
    from time_entries te, clock_eff ce
    where te.company_id = p_company_id and te.total_hours > 0
      and ce.ok and te.date between ce.s and ce.e
    group by 1
  ),
  pr_hours_pre as (
    select pp.employee_id, sum((pp.regular_hours + pp.overtime_hours) * f.frac) hours
    from payroll_periods pp, eff
    cross join lateral (
      select greatest(0, (least(pp.period_end, least(eff.e, coalesce(eff.tc_first, eff.e) - 1))
             - greatest(pp.period_start, eff.s) + 1))::numeric
             / nullif(pp.period_end - pp.period_start + 1, 0) as frac
    ) f
    where pp.company_id = p_company_id and coalesce(pp.flsa_status,'') <> 'Exempt'
      and eff.tc_first is not null
      and pp.period_start <= least(eff.e, eff.tc_first - 1)
      and pp.period_end >= eff.s and f.frac > 0
    group by pp.employee_id
  ),
  pr_cost as (
    select pp.employee_id, sum(pp.wages_cost * f.frac) cost,
           sum(coalesce(pp.commission,0) * f.frac) commission,
           sum((pp.regular_hours + pp.overtime_hours) * f.frac) paid_hours
    from payroll_periods pp, eff
    cross join lateral (
      select greatest(0, (least(pp.period_end, eff.e) - greatest(pp.period_start, eff.s) + 1))::numeric
             / nullif(pp.period_end - pp.period_start + 1, 0) as frac
    ) f
    where pp.company_id = p_company_id and coalesce(pp.flsa_status,'') <> 'Exempt'
      and pp.period_start <= eff.e and pp.period_end >= eff.s and f.frac > 0
    group by pp.employee_id
  ),
  people_raw as (
    select e.id,
      coalesce(nullif(e.preferred_name,''), e.first_name) || ' ' || e.last_name as name,
      coalesce(nullif(e.department,''), 'Unassigned') as department,
      e.pay_type, e.hourly_rate, e.is_active,
      coalesce(t.hours, 0) + coalesce(hp.hours, 0) as hours,
      coalesce(tf.hours, 0) as clock_hours,
      round(coalesce(c.cost, 0), 2) as labor_cost,
      round(coalesce(c.commission, 0), 2) as commission,
      (select ju.external_id from jobber_users ju
        where ju.company_id = e.company_id and ju.name ilike '%' || e.last_name || '%'
          and (ju.name ilike '%' || e.first_name || '%'
               or (nullif(e.preferred_name,'') is not null and ju.name ilike '%' || e.preferred_name || '%'))
        order by ju.is_active desc nulls last, ju.external_id limit 1) as jobber_id
    from employees e
    left join tc_hours t on t.employee_id = e.id
    left join tc_hours_full tf on tf.employee_id = e.id
    left join pr_hours_pre hp on hp.employee_id = e.id
    left join pr_cost c on c.employee_id = e.id
    where e.company_id = p_company_id and e.is_field_labor
      -- UNCHANGED on purpose -- tf is deliberately NOT in this list. Widening it would
      -- change who appears in the ranking, the table and by-department for every caller.
      and (t.employee_id is not null or hp.employee_id is not null or c.employee_id is not null)
  ),
  people as (
    select pr.*, (pr.hours >= 1 and pr.jobber_id is not null and pr.labor_cost > 0) as rankable
    from people_raw pr
  ),
  vis as (
    select v.id, v.external_id, v.job_id, v.tech_external_user_ids, v.completed_at
    from visits v, eff
    where v.company_id = p_company_id and v.deleted_at is null
      and v.visit_status = 'COMPLETED' and v.completed_at::date between eff.s and eff.e
      and upper(coalesce(v.title,'')) not like '%BILLING%'
  ),
  rev_recurring as (
    select v.id visit_id, sum(li.total) amt from vis v
    join jobs j on j.id = v.job_id and j.deleted_at is null and j.is_recurring = true
    join line_items li on li.parent_external_id = v.external_id and li.parent_type = 'visit'
      and li.company_id = p_company_id and li.deleted_at is null
    group by v.id
  ),
  rev_oneoff as (
    select v.id visit_id, (j.total / nullif(jc.n,0)) amt from vis v
    join jobs j on j.id = v.job_id and j.deleted_at is null and j.is_recurring = false
    join lateral (select count(*) n from visits v2 where v2.job_id = j.id
                  and v2.deleted_at is null and v2.visit_status='COMPLETED') jc on true
  ),
  visit_rev as (select visit_id, amt from rev_recurring union all select visit_id, amt from rev_oneoff),
  credited_jobs as (
    select distinct job_id from install_labor_credits where company_id = p_company_id
  ),
  tech_rev_parts as (
    select t.tid, vr.amt
    from (select distinct jobber_id tid from people where jobber_id is not null) t
    join vis v on t.tid = any(v.tech_external_user_ids)
    join visit_rev vr on vr.visit_id = v.id
    where not exists (select 1 from credited_jobs cj where cj.job_id = v.job_id)
    union all
    select c.jobber_user_external_id, c.credit_amount
    from install_labor_credits c, eff
    where c.company_id = p_company_id
      and c.credit_date between eff.s and eff.e
      and c.jobber_user_external_id is not null
  ),
  tech_rev as (select tid, sum(amt) amt from tech_rev_parts group by tid),
  totals as (
    select (select round(sum(hours),1) from people) hours,
           (select round(sum(clock_hours),1) from people) clock_hours,
           (select round(sum(labor_cost),2) from people) labor_cost,
           (select round(sum(commission),2) from people) commission,
           (select round(sum(amt),2) from visit_rev) revenue,
           (select count(*) from vis) visits
  )
  select case when not (select ok from allowed) then null else jsonb_build_object(
    'coverage', jsonb_build_object(
      'timeclock_first', (select data_first from eff), 'timeclock_last', (select data_last from eff),
      'effective_start', (select s from eff), 'effective_end', (select e from eff),
      'requested_start', p_start, 'requested_end', p_end,
      'clamped', (select (s <> p_start or e <> p_end) from eff),
      'has_data', (select (s <= e) from eff),
      'backfilled', true, 'backfill_until', (select tc_first - 1 from eff),
      'payroll_through', (select pay_last from eff),
      'unpaid_tail_days', (select greatest(0, tc_last - pay_last) from eff),
      'clock_has_data', (select ok from clock_eff),
      'clock_start', (select case when ok then s end from clock_eff),
      'clock_end', (select case when ok then e end from clock_eff),
      'install_credits_applied', (select count(*) from install_labor_credits c, eff
                                  where c.company_id = p_company_id and c.credit_date between eff.s and eff.e)
    ),
    'hours', coalesce((select hours from totals), 0),
    'clock_hours', coalesce((select clock_hours from totals), 0),
    'labor_cost', coalesce((select labor_cost from totals), 0),
    'commission', coalesce((select commission from totals), 0),
    'revenue', coalesce((select revenue from totals), 0),
    'visits', coalesce((select visits from totals), 0),
    'rev_per_hour', (select case when hours > 0 then round(revenue / hours, 2) end from totals),
    'rev_per_visit',(select case when visits > 0 then round(revenue / visits, 2) end from totals),
    'labor_pct', (select case when revenue > 0 then round(100 * labor_cost / revenue, 1) end from totals),
    'unattributed_count', (select count(*) from people where jobber_id is null),
    'unattributed_hours', coalesce((select round(sum(hours),1) from people where jobber_id is null), 0),
    'unattributed_names', coalesce((select jsonb_agg(name order by hours desc) from people where jobber_id is null), '[]'::jsonb),
    'salaried_note', (select count(*) from employees where company_id = p_company_id and pay_type <> 'hourly' and is_active),
    'people', coalesce((select jsonb_agg(p order by (p->>'hours')::numeric desc) from (
        select jsonb_build_object('employee_id', pe.id, 'name', pe.name, 'department', pe.department,
          'is_active', pe.is_active, 'pay_type', pe.pay_type, 'hours', round(pe.hours, 1),
          'clock_hours', round(pe.clock_hours, 1),
          'labor_cost', pe.labor_cost, 'commission', pe.commission,
          'attributable', (pe.jobber_id is not null), 'rankable', pe.rankable,
          'revenue', case when pe.jobber_id is not null then round(coalesce(tr.amt, 0), 2) end,
          'rev_per_hour', case when pe.rankable then round(coalesce(tr.amt,0) / pe.hours, 2) end) p
        from people pe left join tech_rev tr on tr.tid = pe.jobber_id) x), '[]'::jsonb),
    'by_department', coalesce((select jsonb_agg(d order by (d->>'hours')::numeric desc) from (
        select jsonb_build_object('department', department, 'hours', round(sum(hours), 1),
          'labor_cost', round(sum(labor_cost), 2), 'people', count(*)) d
        from people group by department) y), '[]'::jsonb)
  ) end;
$$;


ALTER FUNCTION public.scoreboard_crew_labor(p_company_id uuid, p_start date, p_end date) OWNER TO postgres;

--
-- Name: FUNCTION scoreboard_crew_labor(p_company_id uuid, p_start date, p_end date); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.scoreboard_crew_labor(p_company_id uuid, p_start date, p_end date) IS 'Crew and Labor Efficiency report 8.6 - revenue per clocked labor hour. CLAMPS the window to where timeclock data exists (an unclamped YTD reads 3x high). Includes departed employees; excludes people with no Jobber identity from per-person revenue and names them.';


--
-- Name: scoreboard_goal_periods(uuid, date, date, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.scoreboard_goal_periods(p_company_id uuid, p_start date, p_end date, p_today date) RETURNS TABLE(goal_id uuid, metric text, grain text, period_start date, period_end date, target numeric, employee_id uuid, repeating boolean)
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $_$
  with base as (
    select r.id, r.metric, r.grain, r.period_start, r.period_end, r.target, r.employee_id,
           coalesce(r.repeats, false) as is_repeating,
           case r.grain when 'month' then interval '1 month'
                        when 'quarter' then interval '3 months'
                        else interval '1 year' end as iv,
           case r.grain when 'month' then 'month'
                        when 'quarter' then 'quarter'
                        else 'year' end as unit
    from report_goals r
    where r.company_id = p_company_id
      and case when coalesce(r.repeats, false)
               -- A template applies from its first period ONWARD, so it only has to
               -- have started by the end of the window -- unlike a one-off, which has
               -- to overlap it.
               then r.period_start <= p_end
               else r.period_start <= p_end and r.period_end >= p_start
          end
  ),
  expanded as (
    select b.id, b.metric, b.grain, b.period_start, b.period_end, b.target, b.employee_id,
           false as repeating
    from base b
    where not b.is_repeating
    union all
    -- One row per period of this grain, aligned to the template's own boundaries (the
    -- API always stores an aligned period_start, so stepping by the grain's interval
    -- stays aligned).
    select b.id, b.metric, b.grain,
           gs::date,
           (gs + b.iv - interval '1 day')::date,
           b.target, b.employee_id, true
    from base b
    cross join generate_series(
      greatest(b.period_start, date_trunc(b.unit, p_start::timestamp)::date)::timestamp,
      -- ⚠ Bounded by TODAY as well as the window: expanding into periods that have not
      -- begun would fill a year-to-date board with rows reading "Not started", which
      -- buries the months you can actually act on.
      least(p_end, p_today)::timestamp,
      b.iv
    ) gs
    where b.is_repeating
  )
  select e.id, e.metric, e.grain, e.period_start, e.period_end, e.target, e.employee_id, e.repeating
  from expanded e
  -- ⚠ A target set for ONE specific period beats the template covering it, which is
  -- what makes "$50k every month, except December" two rows instead of twelve.
  where not e.repeating
     or not exists (
       select 1 from report_goals o
       where o.company_id = p_company_id
         and o.metric = e.metric
         and o.grain = e.grain
         and o.period_start = e.period_start
         and o.employee_id is not distinct from e.employee_id
         and coalesce(o.repeats, false) = false
     )
$_$;


ALTER FUNCTION public.scoreboard_goal_periods(p_company_id uuid, p_start date, p_end date, p_today date) OWNER TO postgres;

--
-- Name: scoreboard_goals(uuid, date, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.scoreboard_goals(p_company_id uuid, p_start date, p_end date) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
declare
  g record;
  v_rows jsonb := '[]'::jsonb;
  v_actual numeric;
  v_total int;
  v_today date := (now() at time zone 'America/Chicago')::date;
  v_elapsed numeric;
  v_expected numeric;
  v_attain numeric;
  v_cumulative boolean;
  v_direction text;
  v_judge text;
  v_status text;
  -- One cache slot per source, all keyed on the period below.
  v_period_key text;
  v_invoice jsonb;
  v_invoiced numeric;
  v_clients jsonb;
  v_sales jsonb;
  v_quotes jsonb;
  v_crew jsonb;
  v_comms jsonb;
  v_churn jsonb;
  v_visit_rev numeric;
  v_people jsonb;
  v_person jsonb;
  v_person_name text;
begin
  if not public.scoreboard_reports_allowed(p_company_id) then
    return null;
  end if;

  -- Counted from the SAME expansion the loop reads, so the truncation note can
  -- never disagree with the list it describes.
  select count(*) into v_total
  from public.scoreboard_goal_periods(p_company_id, p_start, p_end, v_today);

  for g in
    -- Repeating targets are already expanded into one row per period here, so a
    -- "monthly" target is judged month by month rather than once.
    select * from public.scoreboard_goal_periods(p_company_id, p_start, p_end, v_today)
    -- Period first, and this is load-bearing rather than cosmetic: every source
    -- cache below holds ONE period, so goals must arrive period-major or each
    -- would refill it. Company rows ahead of person rows so the table reads
    -- company-then-people within a period.
    -- ⚠⚠ ORDERED ON period_end, NOT period_start, and that is a bug fix rather
    -- than a preference. A yearly target starts 1 January, so under period_start
    -- it sorted BEHIND all twelve months inside its own year and was the first
    -- thing the cap threw away. Heroes lost the $750,000 company goal for 2026
    -- off its card exactly that way, at rank 61 of 69 with the cap at 60.
    -- ⚠ Still period-major, which is load-bearing: every source cache below holds
    -- ONE period and would refill on every row otherwise. (period_end,
    -- period_start) IS that cache key, so the grouping stays exact. Company rows
    -- ahead of person rows so the table reads company-then-people in a period.
    order by period_end desc, period_start desc, (employee_id is not null), metric
    -- ⚠ Counts TARGETS, but the cost is one set of source calls per distinct
    -- PERIOD, and periods are bounded by the window whatever this says. Heroes'
    -- 69 targets span 10 periods, the same 10 at 60 or at 400.
    limit 400
  loop
    -- A new period invalidates every cached source at once.
    if v_period_key is distinct from (g.period_start::text || '|' || g.period_end::text) then
      v_period_key := g.period_start::text || '|' || g.period_end::text;
      v_invoice := null; v_clients := null; v_sales := null; v_quotes := null;
      v_crew := null; v_comms := null; v_churn := null; v_visit_rev := null;
      v_people := null;
    end if;

    v_person := null;
    v_person_name := null;
    v_cumulative := null;
    v_direction := null;
    v_judge := null;

    -- How this measure is judged. A key missing here leaves v_cumulative null,
    -- which skips the actual entirely and reports "No data" -- loud, not guessed.
    select p.cumulative, p.direction, p.judge
      into v_cumulative, v_direction, v_judge
    from (values
      ('invoiced',               true,  'higher', 'running'),
      ('collected',              true,  'higher', 'running'),
      ('collection_rate',        false, 'higher', 'period_end'),
      ('leads',                  true,  'higher', 'running'),
      ('won_value',              true,  'higher', 'running'),
      ('new_business_value',     true,  'higher', 'running'),
      ('upsell_value',           true,  'higher', 'running'),
      ('won_count',              true,  'higher', 'running'),
      ('avg_deal',               false, 'higher', 'running'),
      ('close_rate',             false, 'higher', 'running'),
      ('quotes_sent',            true,  'higher', 'running'),
      ('quote_win_rate',         false, 'higher', 'running'),
      ('visit_revenue',          true,  'higher', 'running'),
      ('rev_per_visit',          false, 'higher', 'running'),
      ('rev_per_labor_hour',     false, 'higher', 'running'),
      ('labor_pct',              false, 'lower',  'running'),
      ('new_customers',          true,  'higher', 'running'),
      ('retention_pct',          false, 'higher', 'period_end'),
      ('controllable_churn_pct', false, 'lower',  'period_end'),
      ('missed_call_pct',        false, 'lower',  'running'),
      ('answer_seconds',         false, 'lower',  'running'),
      ('reply_seconds',          false, 'lower',  'running'),
      ('outbound_calls',         true,  'higher', 'running')
    ) as p(metric, cumulative, direction, judge)
    where p.metric = g.metric;

    if v_cumulative is null then
      -- Unknown measure: no actual, no verdict. The card says so.
      v_actual := null;

    elsif g.employee_id is null then
      -- Company-wide. Fill only the source this measure needs, once per period.
      if g.metric in ('invoiced','collected','collection_rate') and v_invoice is null then
        v_invoice := (public.scoreboard_invoice_window(p_company_id, g.period_start, g.period_end))::jsonb;
      end if;
      if g.metric = 'new_customers' and v_clients is null then
        v_clients := (public.scoreboard_clients(p_company_id, g.period_start, g.period_end))::jsonb;
      end if;
      if g.metric in ('leads','won_value','new_business_value','upsell_value','won_count','avg_deal','close_rate')
         and v_sales is null then
        v_sales := (public.scoreboard_sales(p_company_id, g.period_start, g.period_end))::jsonb;
      end if;
      if g.metric in ('quotes_sent','quote_win_rate') and v_quotes is null then
        v_quotes := (public.scoreboard_quotes(p_company_id, g.period_start, g.period_end))::jsonb;
      end if;
      if g.metric in ('rev_per_visit','rev_per_labor_hour','labor_pct') and v_crew is null then
        v_crew := (public.scoreboard_crew_labor(p_company_id, g.period_start, g.period_end))::jsonb;
      end if;
      if g.metric in ('missed_call_pct','answer_seconds','reply_seconds','outbound_calls') and v_comms is null then
        v_comms := (public.scoreboard_communications(p_company_id, g.period_start, g.period_end))::jsonb;
      end if;
      -- The UNCLAMPED revenue source, deliberately: scoreboard_crew_labor cuts its
      -- window to the days timeclock data covers, which is right for a rate and
      -- wrong for a total.
      if g.metric = 'visit_revenue' and v_visit_rev is null then
        select coalesce(sum(vr.total), 0) into v_visit_rev
        from public.scoreboard_visit_revenue(p_company_id, g.period_start, g.period_end, 'month') vr;
      end if;
      -- Retention and churn come from a function that takes a YEAR, so they are
      -- answerable only for a whole calendar year. The API refuses other grains; a
      -- row that got in anyway gets no actual rather than a figure for the wrong span.
      if g.metric in ('retention_pct','controllable_churn_pct') then
        if g.grain = 'year'
           and extract(year from g.period_start) = extract(year from g.period_end)
           and v_churn is null then
          v_churn := public.scoreboard_churn_summary(p_company_id, extract(year from g.period_start)::int);
        end if;
      end if;

      v_invoiced := nullif(v_invoice->>'invoiced', '')::numeric;

      v_actual := case g.metric
        when 'invoiced'  then nullif(v_invoice->>'invoiced', '')::numeric
        when 'collected' then nullif(v_invoice->>'collected', '')::numeric
        -- Derived from the SAME call as the two totals beside it, so the rate can
        -- never disagree with them. Null when nothing was billed: a period with no
        -- invoices has no collection rate, and 0% would read as a failure.
        when 'collection_rate' then case when coalesce(v_invoiced, 0) > 0
          then round(100 * nullif(v_invoice->>'collected', '')::numeric / v_invoiced, 1) end
        when 'new_customers' then nullif(v_clients->>'new_in_window', '')::numeric
        when 'leads'         then nullif(v_sales->>'leads', '')::numeric
        -- ⚠⚠ THE FIVE "HOW MUCH DID YOU SELL" MEASURES COUNT A DEAL IN THE PERIOD IT
        -- WAS SOLD, not the period its lead arrived. Ben: "we want close date not lead
        -- creation date." Same rule the commission bases use, so a sales target and the
        -- bonus paid on it cannot disagree.
        --
        -- ⚠ 'leads' and 'close_rate' deliberately KEEP the arrival cohort. A lead count
        -- is by definition about arrivals, and a close rate measured over deals that
        -- closed would be 100% by construction — the cohort IS the denominator.
        when 'won_value'     then nullif(v_sales->>'won_value_closed', '')::numeric
        -- New business by SUBTRACTION, exactly as the commission bases derive it,
        -- so the three sales measures cannot disagree about what a deal was.
        -- Null-preserving: `greatest(coalesce(a,0) - coalesce(b,0), 0)` alone would
        -- turn "no data at all" into a confident 0, which reads as a miss rather
        -- than as nothing to measure.
        when 'new_business_value' then case when v_sales->>'won_value_closed' is not null then greatest(
          coalesce(nullif(v_sales->>'won_value_closed', '')::numeric, 0)
          - coalesce(nullif(v_sales->>'upsold_value_closed', '')::numeric, 0), 0) end
        when 'upsell_value'  then nullif(v_sales->>'upsold_value_closed', '')::numeric
        when 'won_count'     then nullif(v_sales->>'won_closed', '')::numeric
        when 'avg_deal'      then nullif(v_sales->>'avg_deal_closed', '')::numeric
        when 'close_rate'    then nullif(v_sales->>'close_rate', '')::numeric
        when 'quotes_sent'   then nullif(v_quotes->>'sent', '')::numeric
        -- Null below the fair-rating floor the Quotes report itself uses.
        when 'quote_win_rate' then nullif(v_quotes->>'win_rate', '')::numeric
        when 'visit_revenue' then v_visit_rev
        when 'rev_per_visit' then nullif(v_crew->>'rev_per_visit', '')::numeric
        when 'rev_per_labor_hour' then nullif(v_crew->>'rev_per_hour', '')::numeric
        when 'labor_pct'     then nullif(v_crew->>'labor_pct', '')::numeric
        when 'retention_pct' then nullif(v_churn->>'retention_pct', '')::numeric
        when 'controllable_churn_pct' then nullif(v_churn->>'controllable_churn_pct', '')::numeric
        when 'missed_call_pct' then nullif(v_comms->>'missed_pct', '')::numeric
        -- Stored and compared in whole seconds: a target of 20 means 20 seconds.
        when 'answer_seconds' then round(nullif(v_comms->>'median_answer_sec', '')::numeric)
        when 'reply_seconds'  then round(nullif(v_comms->>'median_reply_sec', '')::numeric)
        when 'outbound_calls' then nullif(v_comms->>'outbound_calls', '')::numeric
        else null
      end;

      -- A period entirely BEFORE a source's first record reads "No data", never
      -- zero. Found while testing: an invoiced target for 2025 reported $0 against
      -- $10,000 and a red "Missed", and an outbound-call target for March reported
      -- 0 of 400 -- both failures the business never had, because the invoice mirror
      -- starts 2026-01-02 and the dialer 2026-05-25. A count silently reads zero
      -- where a rate already nulls itself, so the two halves of one family
      -- disagreed about what "we have no data" looks like.
      --
      -- Only the sources that publish their own floor can do this. Leads, quotes
      -- and visit revenue expose none, so a period before their history still reads
      -- zero; lib/reports/goals.ts records that.
      if v_actual is not null then
        v_actual := case
          when g.metric in ('invoiced','collected','collection_rate')
            and coalesce(nullif(v_invoice->>'earliest_invoice','')::date, 'infinity'::date) > g.period_end
            then null
          when g.metric = 'new_customers'
            and coalesce(nullif(v_clients->'coverage'->>'first_client','')::date, 'infinity'::date) > g.period_end
            then null
          when g.metric in ('missed_call_pct','answer_seconds','outbound_calls')
            and coalesce(nullif(v_comms->'coverage'->>'first_call','')::date, 'infinity'::date) > g.period_end
            then null
          when g.metric = 'reply_seconds'
            and coalesce(nullif(v_comms->'coverage'->>'first_text','')::date, 'infinity'::date) > g.period_end
            then null
          else v_actual
        end;
      end if;

    else
      -- One person. Scoped to this company as well as this id: an employee_id
      -- alone is not authorization, and a stray cross-tenant id must resolve to
      -- nothing.
      select nullif(trim(
               coalesce(nullif(trim(coalesce(e.preferred_name, '')), ''), e.first_name, '')
               || ' ' || coalesce(e.last_name, '')
             ), '')
      into v_person_name
      from employees e
      where e.id = g.employee_id and e.company_id = p_company_id;

      if v_people is null then
        v_people := public.scoreboard_people(p_company_id, g.period_start, g.period_end);
      end if;

      select e into v_person
      from jsonb_array_elements(coalesce(v_people->'people', '[]'::jsonb)) e
      where e->>'employee_id' = g.employee_id::text;

      -- EVERY personal figure comes out of scoreboard_people -- the composer the
      -- People report and commission are both built on -- so a person's target
      -- cannot disagree with the report it is judged against. Which is also why the
      -- list here is shorter than the company one: a measure absent from that
      -- composer is company-only, and the API refuses it per person.
      v_actual := case g.metric
        when 'leads'     then nullif(v_person->'sales'->>'leads', '')::numeric
        when 'won_value' then nullif(v_person->'sales'->>'sold_value_closed', '')::numeric
        -- Null-preserving for the same reason as the company branch above: somebody
        -- absent from the People composer has no figure, not a figure of zero.
        when 'new_business_value' then case when v_person->'sales'->>'sold_value_closed' is not null then greatest(
          coalesce(nullif(v_person->'sales'->>'sold_value_closed', '')::numeric, 0)
          - coalesce(nullif(v_person->'sales'->>'upsold_value_closed', '')::numeric, 0), 0) end
        when 'upsell_value' then nullif(v_person->'sales'->>'upsold_value_closed', '')::numeric
        when 'won_count'    then nullif(v_person->'sales'->>'won_closed', '')::numeric
        when 'avg_deal'     then nullif(v_person->'sales'->>'avg_deal_closed', '')::numeric
        -- Null below the fair-rating floor (scoreboard_people.rate_min_sample), so
        -- a rep with three decisions reads "no data" rather than a rate the People
        -- report itself refuses to state.
        when 'close_rate'   then nullif(v_person->'sales'->>'close_rate', '')::numeric
        -- A visit worked by two people credits BOTH, so personal figures do not add
        -- up to the company one. That is the same rule the technician charts state
        -- on their face, and it is correct for an individual's target.
        when 'visit_revenue' then nullif(v_person->'field'->>'revenue', '')::numeric
        when 'rev_per_labor_hour' then nullif(v_person->'field'->>'rev_per_hour', '')::numeric
        -- Their pay over their own credited work. NOT a slice of the company
        -- percentage: that one divides by all completed work, including work
        -- nobody is credited with, so the two are different questions.
        when 'labor_pct'          then nullif(v_person->'field'->>'labor_pct', '')::numeric
        else null
      end;
    end if;

    v_elapsed := case
      when v_today > g.period_end then 1
      when v_today < g.period_start then 0
      else (v_today - g.period_start + 1)::numeric / nullif((g.period_end - g.period_start + 1), 0)
    end;
    v_expected := case when v_cumulative and v_elapsed > 0 then round(g.target * v_elapsed, 2) end;

    -- Attainment is INVERTED for a ceiling measure. 23.8% labour against a 22%
    -- target is a miss; computed the other way up it reads 108% and the progress
    -- bars would colour it green.
    v_attain := case
      when v_actual is null or g.target <= 0 then null
      when v_direction = 'lower' then
        case when v_actual > 0 then round(100 * g.target / v_actual, 1) else 100 end
      else round(100 * v_actual / g.target, 1)
    end;

    v_status := case
      when v_actual is null then 'unknown'
      when v_elapsed = 0 then 'open'
      -- No verdict yet for a measure that can only be read as a share of the whole
      -- period: an annual retention target would otherwise read "Hit" every
      -- January, because nobody has cancelled yet.
      when v_judge = 'period_end' and v_today <= g.period_end then 'pending'
      when v_direction = 'lower' then case
        when v_actual <= g.target then 'hit'
        when v_today > g.period_end then 'missed'
        -- 'over' is the ceiling equivalent of 'under': being under a cost target is
        -- the good outcome, so the two cannot share a word.
        when not v_cumulative then 'over'
        when v_expected is not null and v_actual <= v_expected then 'on_track'
        else 'behind'
      end
      when v_actual >= g.target then 'hit'
      when v_today > g.period_end then 'missed'
      when not v_cumulative then 'under'
      when v_expected is not null and v_actual >= v_expected then 'on_track'
      else 'behind'
    end;

    v_rows := v_rows || jsonb_build_object(
      -- A repeating target yields several rows from ONE stored row, so the id has
      -- to carry the period or the table would hand React duplicate keys.
      'id', case when g.repeating then g.goal_id::text || ':' || g.period_start::text
                 else g.goal_id::text end,
      'repeating', g.repeating,
      'metric', g.metric,
      'grain', g.grain,
      'period_start', g.period_start,
      'period_end', g.period_end,
      'target', g.target,
      'actual', v_actual,
      'attainment_pct', v_attain,
      'elapsed_pct', round(100 * v_elapsed, 1),
      'expected_by_now', v_expected,
      'cumulative', v_cumulative,
      'closed', v_today > g.period_end,
      'status', v_status,
      'direction', v_direction,
      'employee_id', g.employee_id,
      'person_name', v_person_name
    );
  end loop;

  return jsonb_build_object(
    'as_of', v_today,
    'goals', v_rows,
    'total_in_window', v_total,
    'shown', jsonb_array_length(v_rows)
  );
end
$_$;


ALTER FUNCTION public.scoreboard_goals(p_company_id uuid, p_start date, p_end date) OWNER TO postgres;

--
-- Name: scoreboard_home_pulse(uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.scoreboard_home_pulse(p_company_id uuid, p_months integer DEFAULT 6) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
with allowed as (
  select public.scoreboard_reports_allowed(p_company_id) as ok
),
horizon as (
  select (date_trunc('month', current_date)
          + (greatest(1, least(24, coalesce(p_months, 6))) || ' months')::interval)::date as stop
),
fv as (
  select v.id, v.external_id, v.job_id, v.scheduled_date, j.is_recurring, j.total as job_total
  from visits v
  join jobs j on j.id = v.job_id and j.deleted_at is null and j.job_status <> 'archived'
  cross join horizon h
  where v.company_id = p_company_id and v.deleted_at is null and v.completed_at is null
    and v.scheduled_date >= current_date and v.scheduled_date < h.stop
    and upper(coalesce(v.title, '')) not like '%BILLING%'
),
rec as (
  select fv.id as vid, date_trunc('month', fv.scheduled_date)::date as m,
         coalesce(sum(li.total), 0) as amt, count(li.id) as n_items
  from fv
  left join line_items li
    on li.parent_type = 'visit' and li.parent_external_id = fv.external_id
   and li.deleted_at is null
  where fv.is_recurring
  group by 1, 2
),
one as (
  select fv.id as vid, date_trunc('month', fv.scheduled_date)::date as m,
         coalesce(fv.job_total, 0) / nullif(vc.n, 0) as amt, null::bigint as n_items
  from fv
  join lateral (select count(*) as n from visits v2
                where v2.job_id = fv.job_id and v2.deleted_at is null) vc on true
  where not fv.is_recurring
),
booked as (
  select vid, m, amt, n_items, 'recurring' as kind from rec
  union all
  select vid, m, amt, n_items, 'oneoff' from one
),
by_month as (
  select m,
         round(sum(case when kind = 'recurring' then amt else 0 end), 2) as recurring,
         round(sum(case when kind = 'oneoff' then amt else 0 end), 2) as oneoff,
         round(sum(amt), 2) as total,
         count(*) as visits,
         count(*) filter (where kind = 'recurring' and n_items = 0) as unpriced
  from booked group by m
),
active_rs as (
  select rs.id, rs.email
  from recurring_services rs
  where rs.company_id = p_company_id
    and rs.status ilike 'Sold%' and coalesce(rs.cancelled_status, '') = 'Active'
),
rs_client as (
  select ars.id as rs_id, cl.id as client_id
  from active_rs ars
  left join lateral (
    select cl.id from clients cl
    where cl.company_id = p_company_id and cl.deleted_at is null
      and coalesce(ars.email, '') <> '' and lower(cl.email) = lower(ars.email)
    -- ⚠ ORDER BY is load-bearing: without it a shared email returns an arbitrary
    -- row and the whole figure becomes non-reproducible. See the header note.
    order by cl.id
    limit 1
  ) cl on true
),
at_risk as (
  select distinct rc.client_id
  from rs_client rc
  where rc.client_id is not null
    and not exists (
      select 1 from visits v
      where v.client_id = rc.client_id and v.deleted_at is null
        and v.scheduled_date >= current_date and v.completed_at is null
    )
),
jobs_by_status as (
  select job_status, count(*) as n, coalesce(sum(uninvoiced_total), 0) as uninvoiced
  from jobs where company_id = p_company_id and deleted_at is null group by job_status
),
late as (
  select count(*) as n, min(v.scheduled_date) as oldest
  from visits v
  join jobs j on j.id = v.job_id and j.deleted_at is null and j.job_status <> 'archived'
  where v.company_id = p_company_id and v.deleted_at is null and v.completed_at is null
    and v.scheduled_date < current_date
    and upper(coalesce(v.title, '')) not like '%BILLING%'
)
select case when not (select ok from allowed) then null else jsonb_build_object(
  'as_of', current_date,
  'attention', jsonb_build_object(
    'requires_invoicing_count', coalesce((select n from jobs_by_status where job_status = 'requires_invoicing'), 0),
    'requires_invoicing_value', coalesce((select uninvoiced from jobs_by_status where job_status = 'requires_invoicing'), 0),
    'action_required', coalesce((select n from jobs_by_status where job_status = 'action_required'), 0),
    'unscheduled_jobs', coalesce((select n from jobs_by_status where job_status = 'unscheduled'), 0),
    'late_visits', (select n from late),
    'oldest_late_visit', (select oldest from late),
    'at_risk_clients', (select count(*) from at_risk),
    'at_risk_services_total', (select count(*) from active_rs),
    'at_risk_services_matched', (select count(*) from rs_client where client_id is not null)
  ),
  'booked', jsonb_build_object(
    'months', coalesce((select jsonb_agg(jsonb_build_object(
        'month', to_char(m, 'YYYY-MM'), 'recurring', recurring, 'oneoff', oneoff,
        'total', total, 'visits', visits, 'unpriced', unpriced
      ) order by m) from by_month), '[]'::jsonb),
    'total', coalesce((select round(sum(total), 2) from by_month), 0),
    'visits', coalesce((select sum(visits) from by_month), 0),
    'unpriced_visits', coalesce((select sum(unpriced) from by_month), 0),
    'horizon_months', greatest(1, least(24, coalesce(p_months, 6))),
    'first_month_partial', extract(day from current_date) > 1
  )
) end
$$;


ALTER FUNCTION public.scoreboard_home_pulse(p_company_id uuid, p_months integer) OWNER TO postgres;

--
-- Name: scoreboard_invoice_ar(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.scoreboard_invoice_ar(p_company_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  with allowed as (select public.scoreboard_reports_allowed(p_company_id) ok),
  candidates as (
    select i.id, i.invoice_number, i.client_id, i.issued_date, i.due_date, i.invoice_status,
      i.outstanding_balance as balance,
      coalesce(current_date - i.due_date, 0) as days_past_due,
      c.name as client_name
    from invoices i
    left join clients c on c.id = i.client_id
    where i.company_id = p_company_id
      and i.deleted_at is null
      and i.outstanding_balance > 0
      and i.invoice_status <> 'draft'
  ),
  open_invoices as (
    select * from candidates where invoice_status <> 'paid'
  ),
  bucketed as (
    select *,
      case
        when days_past_due <= 0  then 'Current'
        when days_past_due <= 30 then '1-30 days'
        when days_past_due <= 60 then '31-60 days'
        else '60+ days'
      end as bucket
    from open_invoices
  )
  select case when not (select ok from allowed) then null else jsonb_build_object(
    'as_of',      current_date,
    'total_ar',   coalesce((select round(sum(balance), 2) from bucketed), 0),
    'open_count', (select count(*) from bucketed),
    'overdue_total', coalesce((select round(sum(balance), 2) from bucketed where days_past_due > 0), 0),
    'overdue_count', (select count(*) from bucketed where days_past_due > 0),
    'paid_status_still_owing_count', (select count(*) from candidates where invoice_status = 'paid'),
    'paid_status_still_owing_value', coalesce((select round(sum(balance), 2) from candidates where invoice_status = 'paid'), 0),
    'draft_count', (select count(*) from invoices
                    where company_id = p_company_id and deleted_at is null and invoice_status = 'draft'),
    'draft_value', coalesce((select round(sum(total), 2) from invoices
                    where company_id = p_company_id and deleted_at is null and invoice_status = 'draft'), 0),
    'credit_count',   (select count(*) from invoices
                       where company_id = p_company_id and deleted_at is null and outstanding_balance < 0),
    'credit_balance', coalesce((select round(sum(outstanding_balance), 2) from invoices
                       where company_id = p_company_id and deleted_at is null and outstanding_balance < 0), 0),
    'buckets', coalesce((
      select jsonb_agg(b order by b->>'sort')
      from (
        select jsonb_build_object(
          'bucket',  bucket,
          'sort',    min(case bucket when 'Current' then 0 when '1-30 days' then 1 when '31-60 days' then 2 else 3 end),
          'count',   count(*),
          'balance', round(sum(balance), 2)
        ) b
        from bucketed group by bucket
      ) x
    ), '[]'::jsonb),
    'invoices', coalesce((
      select jsonb_agg(r order by (r->>'balance')::numeric desc)
      from (
        select jsonb_build_object(
          'id', id, 'invoice_number', invoice_number, 'client_id', client_id,
          'client_name', coalesce(nullif(trim(client_name), ''), 'Unknown customer'),
          'balance', round(balance, 2), 'days_past_due', days_past_due,
          'issued_date', issued_date, 'status', invoice_status
        ) r
        from bucketed order by balance desc limit 100
      ) y
    ), '[]'::jsonb)
  ) end;
$$;


ALTER FUNCTION public.scoreboard_invoice_ar(p_company_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION scoreboard_invoice_ar(p_company_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.scoreboard_invoice_ar(p_company_id uuid) IS 'Revenue & Invoicing report 8.3 - what is owed right now. Deliberately takes NO date range: AR is point-in-time. Open means outstanding_balance > 0, NOT invoice_status.';


--
-- Name: scoreboard_invoice_window(uuid, date, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.scoreboard_invoice_window(p_company_id uuid, p_start date, p_end date) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  with allowed as (select public.scoreboard_reports_allowed(p_company_id) ok),
  scoped as (
    select
      i.*,
      (i.invoice_status = 'draft') as is_draft,
      (i.total - i.outstanding_balance) as collected,
      case
        when i.paid_at is null or i.issued_date is null then null
        else greatest(0, (i.paid_at at time zone 'America/Chicago')::date - i.issued_date)
      end as days_to_pay,
      case
        when j.id is null then 'Unlinked'
        when j.is_recurring then 'Recurring'
        else 'One-off'
      end as job_kind
    from invoices i
    left join jobs j on j.id = i.job_id and j.deleted_at is null
    where i.company_id = p_company_id
      and i.deleted_at is null
      and i.issued_date between p_start and p_end
  ),
  billed as (select * from scoped where not is_draft)
  select case when not (select ok from allowed) then null else jsonb_build_object(
    'invoiced',        coalesce((select round(sum(total), 2) from billed), 0),
    'collected',       coalesce((select round(sum(collected), 2) from billed), 0),
    'still_owed',      coalesce((select round(sum(greatest(outstanding_balance, 0)), 2) from billed), 0),
    'invoice_count',   (select count(*) from billed),
    'avg_invoice',     (select round(avg(total), 2) from billed),
    'subtotal',        coalesce((select round(sum(subtotal), 2) from billed), 0),
    'tax',             coalesce((select round(sum(tax_amount), 2) from billed), 0),
    'tips',            coalesce((select round(sum(tips_total), 2) from billed), 0),
    'discounts',       coalesce((select round(sum(discount_amount), 2) from billed), 0),
    'median_days_to_pay', (select percentile_disc(0.5) within group (order by days_to_pay)
                           from billed where days_to_pay is not null),
    'avg_days_to_pay',    (select round(avg(days_to_pay), 1) from billed where days_to_pay is not null),
    'paid_count',         (select count(*) from billed where days_to_pay is not null),
    'draft_count',     (select count(*) from scoped where is_draft),
    'draft_value',     coalesce((select round(sum(total), 2) from scoped where is_draft), 0),
    'earliest_invoice', (select min(issued_date) from invoices
                         where company_id = p_company_id and deleted_at is null),
    'monthly', coalesce((
      select jsonb_agg(m order by m->>'month')
      from (
        select jsonb_build_object(
          'month',     to_char(date_trunc('month', issued_date), 'YYYY-MM'),
          'invoiced',  round(sum(total), 2),
          'collected', round(sum(collected), 2),
          'count',     count(*)
        ) m
        from billed group by date_trunc('month', issued_date)
      ) x
    ), '[]'::jsonb),
    'mix', coalesce((
      select jsonb_agg(k order by (k->>'invoiced')::numeric desc)
      from (
        select jsonb_build_object('kind', job_kind, 'count', count(*), 'invoiced', round(sum(total), 2)) k
        from billed group by job_kind
      ) y
    ), '[]'::jsonb)
  ) end;
$$;


ALTER FUNCTION public.scoreboard_invoice_window(p_company_id uuid, p_start date, p_end date) OWNER TO postgres;

--
-- Name: FUNCTION scoreboard_invoice_window(p_company_id uuid, p_start date, p_end date); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.scoreboard_invoice_window(p_company_id uuid, p_start date, p_end date) IS 'Revenue & Invoicing report 8.3 - what was billed and collected in a window. Drafts excluded from every total and reported separately. Collected is derived from outstanding_balance, not payments_total.';


--
-- Name: scoreboard_ir_repair_ticket(uuid, date, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.scoreboard_ir_repair_ticket(p_company_id uuid, p_start date, p_end date) RETURNS TABLE(ticket_count bigint, avg_value numeric, median_value numeric, total_value numeric)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  WITH tickets AS (
    SELECT v.id AS visit_id, SUM(li.total) AS ticket_total
    FROM public.visits v
    JOIN public.line_items li
      ON li.parent_external_id = v.external_id AND li.parent_type='visit' AND li.company_id=p_company_id
     AND li.deleted_at IS NULL AND li.dept_prefix='IR' AND li.total <> 0
     AND li.name NOT ILIKE '%Service Plan%'
     AND li.name NOT ILIKE 'IR - Irrigation Installation%'
     AND li.name NOT ILIKE '%Drainage System Installation%'
    WHERE v.company_id=p_company_id AND v.deleted_at IS NULL AND v.visit_status='COMPLETED'
      AND v.completed_at::date BETWEEN p_start AND p_end
      AND ((SELECT auth.uid()) IS NULL OR EXISTS (
        SELECT 1 FROM public.user_profiles up WHERE up.id=(SELECT auth.uid())
          AND up.company_id=p_company_id AND (up.role='admin' OR up.can_access_scoreboards)))
    GROUP BY v.id HAVING SUM(li.total) <> 0
  )
  SELECT count(*)::bigint, round(avg(ticket_total),2),
         round((percentile_cont(0.5) WITHIN GROUP (ORDER BY ticket_total))::numeric,2),
         round(sum(ticket_total),2)
  FROM tickets
$$;


ALTER FUNCTION public.scoreboard_ir_repair_ticket(p_company_id uuid, p_start date, p_end date) OWNER TO postgres;

--
-- Name: scoreboard_lead_items(uuid, date, date, text, text[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.scoreboard_lead_items(p_company_id uuid, p_start date, p_end date, p_basis text DEFAULT 'sold'::text, p_stages text[] DEFAULT NULL::text[]) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
with allowed as (
  select public.scoreboard_reports_allowed(p_company_id) ok
),
cfg as (
  select case when lower(coalesce(p_basis, 'sold')) = 'created' then 'created' else 'sold' end basis
),
base as (
  select l.id,
         l.service,
         nullif(btrim(l.salesperson), '') salesperson,
         l.stage,
         l.first_name, l.last_name,
         case when (select basis from cfg) = 'created' then l.lead_creation_date else l.sold_date end basis_date
  from leads l
  where (select ok from allowed)
    and l.company_id = p_company_id
),
scoped as (
  select * from base
  where basis_date between p_start and p_end
    and (p_stages is null or cardinality(p_stages) = 0 or stage = any(p_stages))
),
exploded as (
  select s.id, s.salesperson, s.first_name, s.last_name, s.basis_date,
         nullif(btrim(v), '') value
  from scoped s
  left join lateral unnest(s.service) v on true
),
per_item as (
  select value,
         mode() within group (order by salesperson) salesperson,
         count(distinct id) leads
  from exploded
  where value is not null
  group by value, lower(salesperson)
),
units_base as (
  select e.id, e.value, e.salesperson, e.basis_date,
    lower(regexp_replace(btrim(coalesce(e.first_name,'') || ' ' || coalesce(e.last_name,'')), '\s+', ' ', 'g')) as lead_key,
    '%' || array_to_string(
      (select array_agg(t) from unnest(regexp_split_to_array(
          lower(regexp_replace(e.value, '\s*[-–—/]\s*', '-', 'g')), '[-\s]+')) t
        where t <> ''), '%') || '%' as pat
  from exploded e
  where e.value is not null
),
cli as (
  select distinct on (lower(regexp_replace(c.name, '\s+', ' ', 'g')))
         lower(regexp_replace(c.name, '\s+', ' ', 'g')) as k, c.id
  from clients c
  where c.company_id = p_company_id
  order by 1, c.id
),
units_client as (
  select ub.*, cl.id as client_id
  from units_base ub
  left join cli cl on cl.k = ub.lead_key
),
pats as (select distinct pat from units_base),
inv_ev as (
  select p.pat, i.client_id,
    max(li.unit_price) filter (where i.issued_date between p_start and p_end) as price,
    (array_agg(i.invoice_number order by li.unit_price desc nulls last, i.issued_date)
       filter (where i.issued_date between p_start and p_end))[1] as inv_no,
    bool_or(i.issued_date < p_start) as prior
  from pats p
  join line_items li
    on li.parent_type = 'invoice' and li.company_id = p_company_id
   and li.deleted_at is null and li.name ilike p.pat
  join invoices i
    on i.id = li.parent_id and i.deleted_at is null and i.issued_date <= p_end
  group by p.pat, i.client_id
),
vis_ev as (
  select distinct p.pat, v.client_id
  from pats p
  join line_items li
    on li.parent_type = 'visit' and li.company_id = p_company_id
   and li.deleted_at is null and li.name ilike p.pat
  join visits v
    on v.id = li.parent_id and v.deleted_at is null and v.scheduled_date < p_start
),
units as (
  select uc.id, uc.value, uc.salesperson, uc.lead_key, uc.basis_date, uc.client_id,
         ie.price, ie.inv_no,
         (coalesce(ie.prior, false) or ve.client_id is not null) as prior_history
  from units_client uc
  left join inv_ev ie on ie.pat = uc.pat and ie.client_id = uc.client_id
  left join vis_ev ve on ve.pat = uc.pat and ve.client_id = uc.client_id
)
select jsonb_build_object(
  'basis', (select basis from cfg),
  'start', p_start,
  'end', p_end,
  'stages', coalesce(to_jsonb(p_stages), '[]'::jsonb),
  'rows', coalesce((
    select jsonb_agg(jsonb_build_object(
             'value', value,
             'salesperson', salesperson,
             'leads', leads
           ) order by leads desc, value)
    from per_item
  ), '[]'::jsonb),
  'units', coalesce((
    select jsonb_agg(jsonb_build_object(
      'lead_id', u.id,
      'value', u.value,
      'salesperson', u.salesperson,
      'client', u.lead_key,
      'sold_date', u.basis_date,
      'matched_client', (u.client_id is not null),
      'invoice_price', u.price,
      'invoice_number', u.inv_no,
      'prior_history', u.prior_history
    ) order by u.basis_date, u.value)
    from units u
  ), '[]'::jsonb),
  'coverage', jsonb_build_object(
    'leads', (select count(*) from scoped),
    'no_service', (select count(*) from scoped where service is null or cardinality(service) = 0),
    'multi_service', (select count(*) from scoped where cardinality(service) > 1),
    'no_salesperson', (select count(*) from scoped where salesperson is null),
    'unmatched_clients', (select count(*) from units where client_id is null),
    'earliest', (select min(basis_date) from base),
    'latest', (select max(basis_date) from base)
  )
)
$$;


ALTER FUNCTION public.scoreboard_lead_items(p_company_id uuid, p_start date, p_end date, p_basis text, p_stages text[]) OWNER TO postgres;

--
-- Name: scoreboard_line_item_names(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.scoreboard_line_item_names(p_company_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  with allowed as (select public.scoreboard_reports_allowed(p_company_id) ok),
  agg as (
    select li.name,
           (array_agg(li.dept_prefix order by li.dept_prefix nulls last))[1] as dept_prefix,
           count(*)                    as lines,
           round(sum(li.total), 2)     as total_value
    from public.line_items li
    where li.company_id = p_company_id
      and li.deleted_at is null
      and coalesce(trim(li.name), '') <> ''
    group by li.name
  )
  select case when not (select ok from allowed) then null else coalesce((
    select jsonb_agg(jsonb_build_object(
             'name',        name,
             'dept_prefix', dept_prefix,
             'lines',       lines,
             'total_value', total_value
           ) order by abs(coalesce(total_value, 0)) desc, name)
    from agg
  ), '[]'::jsonb) end
$$;


ALTER FUNCTION public.scoreboard_line_item_names(p_company_id uuid) OWNER TO postgres;

--
-- Name: scoreboard_people(uuid, date, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.scoreboard_people(p_company_id uuid, p_start date, p_end date) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
declare
  v_crew  jsonb;
  v_sales jsonb;
  v_comms jsonb;
  v_out   jsonb;
begin
  if not public.scoreboard_reports_allowed(p_company_id) then
    return null;
  end if;

  v_crew  := public.scoreboard_crew_labor(p_company_id, p_start, p_end)::jsonb;
  v_sales := public.scoreboard_sales(p_company_id, p_start, p_end)::jsonb;
  v_comms := public.scoreboard_communications(p_company_id, p_start, p_end)::jsonb;

  with crew_people as (
    select (p->>'employee_id')::uuid              as emp_id,
           p->>'department'                       as dept,
           (p->>'hours')::numeric                 as hours,
           nullif(p->>'revenue','')::numeric      as revenue,
           nullif(p->>'rev_per_hour','')::numeric as rph,
           nullif(p->>'labor_cost','')::numeric   as labor_cost,
           (p->>'rankable')::boolean              as rankable,
           (p->>'attributable')::boolean          as attributable
    from jsonb_array_elements(coalesce(v_crew->'people', '[]'::jsonb)) p
  ),
  roster as (
    select e.id as emp_id,
           e.user_id,
           e.is_active,
           coalesce(e.is_field_labor, false) as is_field,
           coalesce(nullif(hu.display_name,''), nullif(e.preferred_name,''),
                    e.first_name, 'Unknown')  as disp,
           lower(split_part(coalesce(nullif(hu.display_name,''), nullif(e.preferred_name,''),
                                     e.first_name, ''), ' ', 1)) as fkey
    from employees e
    left join hub_users hu on hu.id = e.user_id
    where e.company_id = p_company_id
  ),
  fkey_counts as (
    select fkey, count(*) n from roster where fkey <> '' group by 1
  ),
  sales_rows as (
    select lower(trim(s->>'name'))          as skey,
           s->>'name'                       as sname,
           (s->>'leads')::int               as leads,
           (s->>'won')::int                 as won,
           (s->>'competed_won')::int        as competed_won,
           (s->>'upsold')::int              as upsold,
           (s->>'decided')::int             as decided,
           nullif(s->>'close_rate','')::numeric as close_rate,
           (s->>'value')::numeric           as value,
           (s->>'upsold_value')::numeric    as upsold_value
    from jsonb_array_elements(coalesce(v_sales->'by_salesperson', '[]'::jsonb)) s
  ),
  sales_closed_rows as (
    select lower(trim(s->>'name'))          as skey,
           (s->>'won')::int                 as won,
           (s->>'competed_won')::int        as competed_won,
           (s->>'upsold')::int              as upsold,
           (s->>'value')::numeric           as value,
           (s->>'upsold_value')::numeric    as upsold_value
    from jsonb_array_elements(coalesce(v_sales->'by_salesperson_closed', '[]'::jsonb)) s
  ),
  phone as (
    select coalesce(c.transferred_to_user_id, c.handled_by) as uid,
           count(*) filter (
             where c.direction = 'inbound' and c.answered_at is not null and not c.handled_by_ai
           ) as answered,
           count(*) filter (where c.direction = 'outbound') as placed,
           percentile_cont(0.5) within group (
             order by extract(epoch from (c.answered_at - c.created_at))
           ) filter (
             where c.direction = 'inbound' and c.answered_at is not null and not c.handled_by_ai
               and c.answered_at >= c.created_at
               and c.answered_at - c.created_at < interval '10 minutes'
           ) as med
    from calls c
    where c.company_id = p_company_id
      and (c.created_at at time zone 'America/Chicago')::date between p_start and p_end
      and coalesce(c.transferred_to_user_id, c.handled_by) is not null
    group by 1
  ),
  texts as (
    select m.sent_by as uid, count(*) as sent
    from txt_messages m
    where m.company_id = p_company_id
      and m.direction = 'outbound'
      and m.sent_by is not null
      and (m.created_at at time zone 'America/Chicago')::date between p_start and p_end
    group by 1
  ),
  people as (
    select r.emp_id, r.user_id, r.disp, r.is_active, r.is_field,
           cp.dept, cp.hours, cp.revenue, cp.rph, cp.rankable, cp.attributable, cp.labor_cost,
           sr.leads, sr.won, sr.competed_won, sr.upsold, sr.decided, sr.close_rate,
           sr.value as sold, sr.upsold_value,
           scr.won as won_closed, scr.upsold as upsold_closed,
           scr.value as sold_closed, scr.upsold_value as upsold_value_closed,
           ph.answered, ph.placed, ph.med, tx.sent
    from roster r
    left join crew_people cp on cp.emp_id = r.emp_id
    left join fkey_counts  fc on fc.fkey  = r.fkey
    left join sales_rows   sr on sr.skey  = r.fkey and coalesce(fc.n, 0) = 1
    left join sales_closed_rows scr on scr.skey = r.fkey and coalesce(fc.n, 0) = 1
    left join phone        ph on ph.uid   = r.user_id
    left join texts        tx on tx.uid   = r.user_id
    where r.is_active
       or cp.emp_id is not null or sr.skey is not null
       or scr.skey is not null
       or ph.uid is not null or tx.uid is not null
  ),
  depts as (
    select cp.dept as department,
           count(*)                                  as people,
           round(sum(cp.hours), 1)                   as hours,
           round(sum(coalesce(cp.revenue, 0)), 2)    as revenue,
           case when sum(cp.hours) > 0
                then round(sum(coalesce(cp.revenue, 0)) / sum(cp.hours), 2) end as rev_per_hour
    from crew_people cp
    where cp.dept is not null
    group by 1
  ),
  unmatched as (
    select sr.sname, sr.leads, sr.won, sr.value
    from sales_rows sr
    left join fkey_counts fc on fc.fkey = sr.skey
    where fc.fkey is null or fc.n > 1
  )
  select jsonb_build_object(
    'coverage', v_crew->'coverage',
    'rate_min_sample', coalesce((v_sales->>'rate_min_sample')::int, 10),
    'sale_stages', coalesce(v_sales->'sale_stages', '[]'::jsonb),
    'people', (
      select coalesce(jsonb_agg(jsonb_build_object(
        'user_id',        p.user_id,
        'employee_id',    p.emp_id,
        'name',           p.disp,
        'department',     p.dept,
        'is_active',      p.is_active,
        'is_field_labor', p.is_field,
        'sales', jsonb_build_object(
          'leads',      coalesce(p.leads, 0),
          'won',        coalesce(p.won, 0),
          'competed_won', coalesce(p.competed_won, 0),
          'upsold',       coalesce(p.upsold, 0),
          'decided',    coalesce(p.decided, 0),
          'close_rate', p.close_rate,
          'sold_value', coalesce(p.sold, 0),
          'upsold_value', coalesce(p.upsold_value, 0),
          'won_closed',          coalesce(p.won_closed, 0),
          'upsold_closed',       coalesce(p.upsold_closed, 0),
          'sold_value_closed',   coalesce(p.sold_closed, 0),
          'upsold_value_closed', coalesce(p.upsold_value_closed, 0),
          'avg_deal_closed',      case when coalesce(p.won_closed, 0) > 0 then round(p.sold_closed / p.won_closed, 2) end,
          'avg_deal',   case when coalesce(p.won, 0) > 0 then round(p.sold / p.won, 2) end
        ),
        'field', jsonb_build_object(
          'hours',        coalesce(p.hours, 0),
          'revenue',      p.revenue,
          'rev_per_hour', p.rph,
          'labor_cost',   p.labor_cost,
          -- Their pay over the work credited to THEM -- both halves belong to the
          -- same person, which is the whole reason this is honest and the company
          -- ratio cannot be split. Null unless they are rankable and have credited
          -- revenue: a share of nothing is unmeasurable, not 0%.
          'labor_pct',    case when coalesce(p.rankable, false) and coalesce(p.revenue, 0) > 0
                               then round(100 * p.labor_cost / p.revenue, 1) end,
          'rankable',     coalesce(p.rankable, false),
          'attributable', coalesce(p.attributable, false)
        ),
        'phone', jsonb_build_object(
          'calls_answered',    coalesce(p.answered, 0),
          'calls_placed',      coalesce(p.placed, 0),
          'median_answer_sec', round(p.med::numeric, 1),
          'texts_sent',        coalesce(p.sent, 0)
        )
      ) order by coalesce(p.sold, 0) + coalesce(p.revenue, 0) desc), '[]'::jsonb)
      from people p
    ),
    'departments', (
      select coalesce(jsonb_agg(to_jsonb(d) order by d.revenue desc), '[]'::jsonb) from depts d
    ),
    'office', jsonb_build_object(
      'inbound_calls',     v_comms->'inbound_calls',
      'missed',            v_comms->'missed',
      'missed_pct',        v_comms->'missed_pct',
      'median_answer_sec', v_comms->'median_answer_sec',
      'texts_in',          v_comms->'texts_in',
      'texts_out',         v_comms->'texts_out',
      'median_reply_sec',  v_comms->'median_reply_sec'
    ),
    'unmatched_sales', (
      select coalesce(jsonb_agg(jsonb_build_object(
        'name', u.sname, 'leads', u.leads, 'won', u.won, 'sold_value', u.value
      ) order by u.leads desc), '[]'::jsonb) from unmatched u
    )
  ) into v_out;

  return v_out;
end
$$;


ALTER FUNCTION public.scoreboard_people(p_company_id uuid, p_start date, p_end date) OWNER TO postgres;

--
-- Name: scoreboard_quotes(uuid, date, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.scoreboard_quotes(p_company_id uuid, p_start date, p_end date) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  with allowed as (select public.scoreboard_reports_allowed(p_company_id) ok),
  cohort as (
    select q.*,
      -- ⚠ `sent_at ?? created_at`. Five converted quotes were never formally sent
      -- (sold on the spot, then converted), so a sent-only cohort silently drops real
      -- wins. The count of these is returned so the card can say so.
      coalesce(q.sent_at, q.external_created_at) as cohort_at,
      (q.quote_status in ('approved','converted')) as won,
      (q.quote_status = 'archived') as lost,
      (q.quote_status in ('awaiting_response','changes_requested')) as still_open,
      -- One rep, one row — the same normalisation `scoreboard_sales` needed.
      coalesce(nullif(trim(q.salesperson_external_id),''), 'unassigned') as rep_key,
      -- Line items with no recognised prefix get their own named bucket rather than
      -- being dropped, the way unallocated labour hours do in Service Lines.
      case when q.service_codes is null or cardinality(q.service_codes) = 0
           then 'Unclassified' else q.service_codes[1] end as service_code
    from jobber_quotes q
    where q.company_id = p_company_id
      and q.deleted_at is null
      -- A draft was never shown to anyone, so it is not a quote that can be won or
      -- lost. Heroes currently holds none; other tenants will.
      and coalesce(q.quote_status,'') <> 'draft'
      and coalesce(q.sent_at, q.external_created_at)::date between p_start and p_end
  ),
  win_days as (
    select extract(epoch from (coalesce(approved_at, converted_at) - sent_at)) / 86400.0 as d
    from cohort
    where won and sent_at is not null
      and coalesce(approved_at, converted_at) is not null
      -- Same guard as time-to-close in §8.2: a decision stamped before the send date
      -- is a migration artefact, not a negative duration.
      and coalesce(approved_at, converted_at) >= sent_at
  )
  select case when (select ok from allowed) then jsonb_build_object(
    'sent',            (select count(*) from cohort),
    'won',             (select count(*) from cohort where won),
    'lost',            (select count(*) from cohort where lost),
    'still_open',      (select count(*) from cohort where still_open),
    'decided',         (select count(*) from cohort where won or lost),
    'sold_on_the_spot',(select count(*) from cohort where sent_at is null),
    'viewed',          (select count(*) from cohort where sent_at is not null and client_viewed_at is not null),
    'never_viewed',    (select count(*) from cohort where sent_at is not null and client_viewed_at is null),
    'no_salesperson',  (select count(*) from cohort where rep_key = 'unassigned'),
    'rate_min_sample', 10,
    'win_rate', (select case when count(*) filter (where won or lost) >= 10
                  then round(100.0 * count(*) filter (where won) / count(*) filter (where won or lost), 1)
                end from cohort),
    'median_days_to_win',
      (select round(percentile_cont(0.5) within group (order by d)::numeric, 1) from win_days),
    'win_time_sample', (select count(*) from win_days),

    'by_month', coalesce((
      select jsonb_agg(m order by m->>'month')
      from (
        select jsonb_build_object(
          'month', to_char(date_trunc('month', cohort_at), 'YYYY-MM'),
          'sent', count(*),
          'won', count(*) filter (where won),
          'decided', count(*) filter (where won or lost),
          'win_rate', case when count(*) filter (where won or lost) >= 10
                      then round(100.0 * count(*) filter (where won) / count(*) filter (where won or lost), 1) end
        ) m
        from cohort group by date_trunc('month', cohort_at)
      ) a
    ), '[]'::jsonb),

    'by_salesperson', coalesce((
      select jsonb_agg(p order by (p->>'sent')::int desc)
      from (
        select jsonb_build_object(
          'rep_id', c.rep_key,
          'name', coalesce(nullif(trim(u.name),''), case when c.rep_key='unassigned' then 'Unassigned' else 'Unknown user' end),
          'sent', count(*),
          'won', count(*) filter (where c.won),
          'decided', count(*) filter (where c.won or c.lost),
          'win_rate', case when count(*) filter (where c.won or c.lost) >= 10
                      then round(100.0 * count(*) filter (where c.won) / count(*) filter (where c.won or c.lost), 1) end
        ) p
        from cohort c
        left join jobber_users u
          on u.company_id = p_company_id and u.external_id = c.rep_key
        group by c.rep_key, u.name
      ) z
    ), '[]'::jsonb),

    'by_service', coalesce((
      select jsonb_agg(s order by (s->>'sent')::int desc)
      from (
        select jsonb_build_object(
          'code', service_code,
          'sent', count(*),
          'won', count(*) filter (where won),
          'decided', count(*) filter (where won or lost),
          'win_rate', case when count(*) filter (where won or lost) >= 10
                      then round(100.0 * count(*) filter (where won) / count(*) filter (where won or lost), 1) end
        ) s
        from cohort group by service_code
      ) y
    ), '[]'::jsonb)
  ) end;
$$;


ALTER FUNCTION public.scoreboard_quotes(p_company_id uuid, p_start date, p_end date) OWNER TO postgres;

--
-- Name: scoreboard_quotes_open(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.scoreboard_quotes_open(p_company_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  with allowed as (select public.scoreboard_reports_allowed(p_company_id) ok),
  open_q as (
    select q.*,
      (now()::date - q.sent_at::date) as days_out,
      case when q.service_codes is null or cardinality(q.service_codes) = 0
           then 'Unclassified' else q.service_codes[1] end as service_code
    from jobber_quotes q
    where q.company_id = p_company_id
      and q.deleted_at is null
      and q.quote_status in ('awaiting_response','changes_requested')
      and q.sent_at is not null
  )
  select case when (select ok from allowed) then jsonb_build_object(
    'as_of', now(),
    'open_total',     (select count(*) from open_q),
    'never_opened',   (select count(*) from open_q where client_viewed_at is null),
    'opened_no_reply',(select count(*) from open_q where client_viewed_at is not null),
    'oldest_days',    (select max(days_out) from open_q),
    'approved_not_converted', (
      select count(*) from jobber_quotes
      where company_id = p_company_id and deleted_at is null and quote_status = 'approved'
    ),
    'aging', jsonb_build_object(
      'd0_7',   (select count(*) from open_q where days_out <= 7),
      'd8_14',  (select count(*) from open_q where days_out between 8 and 14),
      'd15_30', (select count(*) from open_q where days_out between 15 and 30),
      'd31',    (select count(*) from open_q where days_out > 30)
    ),
    'list_cap', 100,
    'list_total', (select count(*) from open_q),
    'list', coalesce((
      select jsonb_agg(r order by (r->>'days_out')::int desc)
      from (
        select jsonb_build_object(
          'quote_number', o.quote_number,
          'client', coalesce(nullif(trim(c.company_name),''), nullif(trim(c.name),''), 'Unknown'),
          'client_id', o.client_id,
          'days_out', o.days_out,
          'viewed', o.client_viewed_at is not null,
          'service', o.service_code,
          'salesperson', coalesce(nullif(trim(u.name),''), 'Unassigned'),
          'jobber_uri', o.jobber_web_uri
        ) r
        from open_q o
        left join clients c on c.id = o.client_id
        left join jobber_users u
          on u.company_id = p_company_id and u.external_id = o.salesperson_external_id
        order by o.days_out desc
        limit 100
      ) w
    ), '[]'::jsonb)
  ) end;
$$;


ALTER FUNCTION public.scoreboard_quotes_open(p_company_id uuid) OWNER TO postgres;

--
-- Name: scoreboard_recurring_book(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.scoreboard_recurring_book(p_company_id uuid) RETURNS TABLE(job_id uuid, client_id uuid, dept_prefix text, display_name text, has_phc boolean, has_bwp boolean, annual_value numeric, addon_names text[], visits_per_year integer, is_priced boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
  with active_jobs as (
    select j.id, j.client_id
    from public.jobs j
    join public.clients c on c.id = j.client_id
    where j.company_id   = p_company_id
      and j.is_recurring = true
      and j.job_status  <> 'archived'
      and j.deleted_at   is null
      and coalesce(j.title, '') not ilike '%billing%'
      and not (
        coalesce(c.email, '') ilike '%fakemail%'
        or regexp_replace(coalesce(c.phone, ''), '\D', '', 'g') = '2812540991'
      )
      and (
        (select auth.uid()) is null
        or exists (
          select 1 from public.user_profiles up
          where up.id = (select auth.uid())
            and up.company_id = p_company_id
            and (up.role = 'admin' or up.can_access_scoreboards)
        )
      )
  ),
  defs as (
    select * from public.recurring_program_definitions
    where company_id = p_company_id
  ),
  job_items as (
    select li.parent_id as job_id,
           li.name,
           regexp_replace(li.name, '\s*-\s*T[0-9]+$', '') as norm_name,
           li.total
    from public.line_items li
    join active_jobs aj on aj.id = li.parent_id
    where li.company_id  = p_company_id
      and li.parent_type = 'job'
      and li.deleted_at  is null
  ),
  -- The job's cadence comes from its BASE program, and is the fallback for any
  -- add-on that does not state its own.
  job_vpy as (
    select ji.job_id, max(d.visits_per_year) as vpy
    from job_items ji
    join defs d on d.line_item_name = ji.norm_name and d.is_auxiliary = false
    where d.visits_per_year is not null
    group by ji.job_id
  ),
  job_annual as (
    select jv.job_id,
           sum(ji.total * coalesce(d.visits_per_year, jv.vpy)) as annual_value
    from job_vpy jv
    join job_items ji on ji.job_id = jv.job_id
    left join defs d on d.line_item_name = ji.norm_name
    where
      -- base programs with a cadence
      (d.is_auxiliary = false and d.visits_per_year is not null)
      -- recurring ADD-ONS (PHC, BWP …) — this is what was missing
      or d.is_auxiliary = true
      -- discounts carry no definition but are genuinely recurring credits
      or ji.name ilike '%discount%'
    group by jv.job_id
  ),
  job_addons as (
    select ji.job_id,
           array_agg(distinct d.display_name) as names
    from job_items ji
    join defs d on d.line_item_name = ji.norm_name and d.is_auxiliary = true
    group by ji.job_id
  ),
  -- Retained ONLY for the legacy hardcoded WF board. Both go when it is retired.
  job_aux_legacy as (
    select ji.job_id,
           bool_or(ji.name = 'WF - Plant Health Care')  as has_phc,
           bool_or(ji.name = 'WF - Bed Weed Prevention') as has_bwp
    from job_items ji
    group by ji.job_id
  ),
  job_base as (
    select distinct on (ji.job_id, d.dept_prefix)
           ji.job_id, d.dept_prefix, d.display_name, d.visits_per_year
    from job_items ji
    join defs d on d.line_item_name = ji.norm_name
    where d.is_auxiliary = false
    order by ji.job_id, d.dept_prefix, d.display_name
  )
  select
    aj.id       as job_id,
    aj.client_id,
    jb.dept_prefix,
    jb.display_name,
    coalesce(jal.has_phc, false) as has_phc,
    coalesce(jal.has_bwp, false) as has_bwp,
    coalesce(jan.annual_value, 0) as annual_value,
    coalesce(jad.names, '{}'::text[]) as addon_names,
    jb.visits_per_year::integer,
    (jan.annual_value is not null) as is_priced
  from active_jobs aj
  join job_base jb          on jb.job_id  = aj.id
  left join job_annual jan  on jan.job_id = aj.id
  left join job_aux_legacy jal on jal.job_id = aj.id
  left join job_addons jad  on jad.job_id = aj.id
$_$;


ALTER FUNCTION public.scoreboard_recurring_book(p_company_id uuid) OWNER TO postgres;

--
-- Name: scoreboard_reports_allowed(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.scoreboard_reports_allowed(p_company_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select
    (select auth.uid()) is null
    or exists (
      select 1 from user_profiles up
      where up.id = (select auth.uid())
        and up.company_id = p_company_id
        and (up.role = 'admin' or up.can_access_reports or up.can_access_scoreboards)
    );
$$;


ALTER FUNCTION public.scoreboard_reports_allowed(p_company_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION scoreboard_reports_allowed(p_company_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.scoreboard_reports_allowed(p_company_id uuid) IS 'Shared authorization guard for Reports/Scoreboards widget sources. company_id arrives as a parameter, so every SECURITY DEFINER source must verify the caller belongs to that company.';


--
-- Name: scoreboard_revenue_by_source(uuid, date, date, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.scoreboard_revenue_by_source(p_company_id uuid, p_start date, p_end date, p_credit_rule text DEFAULT 'acquisition'::text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  with allowed as (select public.scoreboard_reports_allowed(p_company_id) ok),
  rule as (
    select case when p_credit_rule = 'recent_touch' then 'recent_touch' else 'acquisition' end c
  ),
  scoped as (
    select i.id, i.client_id, i.total, coalesce(i.payments_total, 0) as paid
    from invoices i, allowed a
    where a.ok
      and i.company_id = p_company_id
      and i.deleted_at is null
      and i.issued_date >= p_start
      and i.issued_date <= p_end
  ),
  cli as (
    select distinct c.id, c.email, c.phone, c.name,
      public.churn_normalize_source(
        p_company_id, nullif(btrim(c.custom_fields->'HLC105 Lead Source'->>'value'), '')
      ) as jobber_src
    from scoped s join clients c on c.id = s.client_id
    where c.company_id = p_company_id
  ),
  labelled as (
    select cli.id, cli.jobber_src,
      (
        select public.churn_normalize_source(p_company_id, l.lead_source)
        from leads l
        where l.company_id = p_company_id
          and coalesce(l.lead_source, '') <> ''
          and (
            (coalesce(cli.email, '') <> '' and lower(l.email) = lower(cli.email))
            or (regexp_replace(coalesce(cli.phone, ''), '\D', '', 'g') <> ''
                and regexp_replace(coalesce(l.phone, ''), '\D', '', 'g')
                  = regexp_replace(coalesce(cli.phone, ''), '\D', '', 'g'))
            or (coalesce(cli.name, '') <> ''
                and lower(btrim(coalesce(l.first_name, '') || ' ' || coalesce(l.last_name, '')))
                  = lower(btrim(cli.name)))
          )
        order by l.created_at desc nulls last
        limit 1
      ) as tracker_src
    from cli
  ),
  credited as (
    select s.id, s.total, s.paid,
      coalesce(
        case when (select c from rule) = 'recent_touch'
             then coalesce(b.tracker_src, b.jobber_src)
             else coalesce(b.jobber_src, b.tracker_src) end,
        'Other / Unknown'
      ) as src,
      b.id as client_id
    from scoped s join labelled b on b.id = s.client_id
  ),
  rows as (
    select r.src,
      coalesce(max(m.source_group), 'Other') as source_group,
      coalesce(max(m.cost_type), 'Unknown')  as cost_type,
      round(sum(r.total), 2)                 as invoiced,
      round(sum(r.paid), 2)                  as collected,
      count(*)                               as invoice_count,
      count(distinct r.client_id)            as client_count
    from credited r
    left join lead_sources_master m
      on m.company_id = p_company_id
     and lower(m.master_source) = lower(r.src)
    group by r.src
  )
  select case when not (select ok from allowed) then null::jsonb else jsonb_build_object(
    'credit_rule', (select c from rule),
    'invoiced',    coalesce((select round(sum(invoiced), 2)   from rows), 0),
    'collected',   coalesce((select round(sum(collected), 2)  from rows), 0),
    'invoices',    coalesce((select sum(invoice_count)::int   from rows), 0),
    'clients',     coalesce((select sum(client_count)::int    from rows), 0),
    'unknown',     coalesce((select invoiced from rows where src = 'Other / Unknown'), 0),
    'by_source', coalesce((
      select jsonb_agg(x order by (x->>'invoiced')::numeric desc)
      from (
        select jsonb_build_object(
          'source',        src,
          'source_group',  source_group,
          'cost_type',     cost_type,
          'invoiced',      invoiced,
          'collected',     collected,
          'invoice_count', invoice_count,
          'client_count',  client_count
        ) x
        from rows
      ) y
    ), '[]'::jsonb)
  ) end
$$;


ALTER FUNCTION public.scoreboard_revenue_by_source(p_company_id uuid, p_start date, p_end date, p_credit_rule text) OWNER TO postgres;

--
-- Name: scoreboard_sales(uuid, date, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.scoreboard_sales(p_company_id uuid, p_start date, p_end date) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  with allowed as (select public.scoreboard_reports_allowed(p_company_id) ok),
  sale_stages as (
    select key from public.tracker_stages
    where company_id = p_company_id and counts_as_sale = true
  ),
  cohort as (
    select l.*,
      (l.stage = 'closed_won') as competed_won,
      (l.stage in (select key from sale_stages)) as upsold,
      (l.stage = 'closed_won' or l.stage in (select key from sale_stages)) as won,
      (l.stage in ('closed_won','closed_lost')) as decided,
      (l.stage = 'closed_other') as junk,
      (l.stage not in ('closed_won','closed_lost','closed_other')
        and l.stage not in (select key from sale_stages)) as open_still,
      coalesce(nullif(initcap(trim(lower(l.salesperson))),''), 'Unassigned') as rep
    from leads l
    where l.company_id = p_company_id
      and l.lead_creation_date between p_start and p_end
  ),
  closed_cohort as (
    select l.*,
      (l.stage = 'closed_won') as competed_won,
      (l.stage in (select key from sale_stages)) as upsold,
      (l.stage = 'closed_won' or l.stage in (select key from sale_stages)) as won,
      coalesce(nullif(initcap(trim(lower(l.salesperson))),''), 'Unassigned') as rep
    from leads l
    where l.company_id = p_company_id
      and l.sold_date between p_start and p_end
  ),
  lost as (
    select regexp_replace(regexp_replace(coalesce(nullif(trim(status),''),'Not given'), '[—–-]+', '-', 'g'),
                          '\s*-\s*', ' - ', 'g') as reason,
           count(*) n
    from cohort where stage = 'closed_lost'
    group by 1
  ),
  days as (
    select (sold_date - lead_creation_date) d
    from cohort
    where competed_won and sold_date is not null and sold_date >= lead_creation_date
  ),
  attempts as (
    select count(distinct la.lead_id) leads_with, count(*) total
    from lead_attempts la join cohort c on c.id = la.lead_id
    where la.company_id = p_company_id
  )
  select case when not (select ok from allowed) then null else jsonb_build_object(
    'leads',        (select count(*) from cohort),
    'won',          (select count(*) filter (where won) from cohort),
    'competed_won', (select count(*) filter (where competed_won) from cohort),
    'upsold',       (select count(*) filter (where upsold) from cohort),
    'upsold_value', coalesce((select round(sum(annual_value) filter (where upsold),2) from cohort), 0),
    'sale_stages',  (select coalesce(jsonb_agg(key order by key), '[]'::jsonb) from sale_stages),
    'lost',         (select count(*) filter (where stage='closed_lost') from cohort),
    'decided',      (select count(*) filter (where decided) from cohort),
    'open',         (select count(*) filter (where open_still) from cohort),
    'excluded_junk',(select count(*) filter (where junk) from cohort),
    'close_rate',   (select case when count(*) filter (where decided) > 0
                      then round(100.0 * count(*) filter (where competed_won) / count(*) filter (where decided), 1) end
                     from cohort),
    'won_value',    coalesce((select round(sum(annual_value) filter (where won),2) from cohort), 0),
    'avg_deal',     (select round(avg(annual_value) filter (where won and annual_value > 0),2) from cohort),
    'median_days_to_close', (select percentile_disc(0.5) within group (order by d) from days),
    'avg_days_to_close',    (select round(avg(d),1) from days),
    'close_time_sample',    (select count(*) from days),
    'attempts_leads',  (select leads_with from attempts),
    'attempts_total',  (select total from attempts),
    'rate_min_sample', 10,

    'by_month', coalesce((
      select jsonb_agg(m order by m->>'month')
      from (
        select jsonb_build_object(
          'month', to_char(date_trunc('month', lead_creation_date), 'YYYY-MM'),
          'leads', count(*),
          'won',   count(*) filter (where won),
          'competed_won', count(*) filter (where competed_won),
          'upsold', count(*) filter (where upsold),
          'decided', count(*) filter (where decided),
          'won_value', coalesce(round(sum(annual_value) filter (where won),2), 0),
          'competed_value', coalesce(round(sum(annual_value) filter (where competed_won),2), 0),
          'upsold_value', coalesce(round(sum(annual_value) filter (where upsold),2), 0),
          'close_rate', case when count(*) filter (where decided) > 0
                        then round(100.0 * count(*) filter (where competed_won) / count(*) filter (where decided), 1) end
        ) m
        from cohort group by date_trunc('month', lead_creation_date)
      ) x
    ), '[]'::jsonb),

    'by_source', coalesce((
      select jsonb_agg(s order by (s->>'leads')::int desc)
      from (
        select jsonb_build_object(
          'source', coalesce(nullif(trim(lead_source),''), 'Other / Unknown'),
          'leads', count(*),
          'won', count(*) filter (where won),
          'competed_won', count(*) filter (where competed_won),
          'upsold', count(*) filter (where upsold),
          'decided', count(*) filter (where decided),
          'close_rate', case when count(*) filter (where decided) >= 10
                        then round(100.0 * count(*) filter (where competed_won) / count(*) filter (where decided), 1) end,
          'value', coalesce(round(sum(annual_value) filter (where won),2), 0)
        ) s
        from cohort group by coalesce(nullif(trim(lead_source),''), 'Other / Unknown')
      ) y
    ), '[]'::jsonb),

    'by_salesperson', coalesce((
      select jsonb_agg(p order by (p->>'won')::int desc)
      from (
        select jsonb_build_object(
          'name', rep,
          'leads', count(*),
          'won', count(*) filter (where won),
          'competed_won', count(*) filter (where competed_won),
          'decided', count(*) filter (where decided),
          'close_rate', case when count(*) filter (where decided) >= 10
                        then round(100.0 * count(*) filter (where competed_won) / count(*) filter (where decided), 1) end,
          'value', coalesce(round(sum(annual_value) filter (where won),2), 0),
          'upsold', count(*) filter (where upsold),
          'upsold_value', coalesce(round(sum(annual_value) filter (where upsold),2), 0)
        ) p
        from cohort group by rep
      ) z
    ), '[]'::jsonb),

    'won_closed',           (select count(*) from closed_cohort where won),
    'won_value_closed',     (select coalesce(round(sum(annual_value) filter (where won),2), 0) from closed_cohort),
    'upsold_closed',        (select count(*) from closed_cohort where upsold),
    'upsold_value_closed',  (select coalesce(round(sum(annual_value) filter (where upsold),2), 0) from closed_cohort),
    'avg_deal_closed',      (select case when count(*) filter (where won) > 0 then round(sum(annual_value) filter (where won) / count(*) filter (where won), 2) end from closed_cohort),

    'by_salesperson_closed', coalesce((
      select jsonb_agg(p order by (p->>'value')::numeric desc)
      from (
        select jsonb_build_object(
          'name', rep,
          'won', count(*) filter (where won),
          'competed_won', count(*) filter (where competed_won),
          'upsold', count(*) filter (where upsold),
          'value', coalesce(round(sum(annual_value) filter (where won),2), 0),
          'upsold_value', coalesce(round(sum(annual_value) filter (where upsold),2), 0)
        ) p
        from closed_cohort group by rep
      ) zc
    ), '[]'::jsonb),

    'lost_reasons', coalesce((
      select jsonb_agg(r order by (r->>'count')::int desc)
      from (select jsonb_build_object('reason', reason, 'count', n) r from lost) w
    ), '[]'::jsonb),

    'open_by_stage', coalesce((
      select jsonb_agg(o order by (o->>'count')::int desc)
      from (
        select jsonb_build_object('stage', stage, 'count', count(*)) o
        from cohort where open_still group by stage
      ) v
    ), '[]'::jsonb)
  ) end;
$$;


ALTER FUNCTION public.scoreboard_sales(p_company_id uuid, p_start date, p_end date) OWNER TO postgres;

--
-- Name: FUNCTION scoreboard_sales(p_company_id uuid, p_start date, p_end date); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.scoreboard_sales(p_company_id uuid, p_start date, p_end date) IS 'Sales and Pipeline 8.2 from the Lead Tracker. Cohort = leads CREATED in the window (matches the Office board). Close rate counts only closed_won + closed_lost; closed_other is junk (Bad Lead / Unreachable / Duplicate) and is excluded but reported. Lost reasons are dash-normalised so one reason does not split in two.';


--
-- Name: scoreboard_sales_person_trend(uuid, date, date, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.scoreboard_sales_person_trend(p_company_id uuid, p_start date, p_end date, p_grain text DEFAULT 'month'::text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  with allowed as (select public.scoreboard_reports_allowed(p_company_id) ok),
  g as (
    select case when lower(coalesce(p_grain,'month')) = 'week' then 'week' else 'month' end as grain
  ),
  sale_stages as (
    select key from public.tracker_stages
    where company_id = p_company_id and counts_as_sale = true
  ),
  cohort as (
    select
      to_char(date_trunc((select grain from g), l.lead_creation_date), 'YYYY-MM-DD') as b,
      coalesce(nullif(initcap(trim(lower(l.salesperson))),''), 'Unassigned')          as rep,
      (l.stage = 'closed_won' or l.stage in (select key from sale_stages))            as won,
      coalesce(l.annual_value, 0)                                                     as annual_value
    from leads l
    where l.company_id = p_company_id
      and l.lead_creation_date between p_start and p_end
  ),
  per_bucket as (
    select b,
           round(coalesce(sum(annual_value) filter (where won), 0), 2) as total,
           count(*) filter (where won) as cnt
    from cohort group by b
  ),
  per_person as (
    select b, rep,
           round(coalesce(sum(annual_value) filter (where won), 0), 2) as total,
           count(*) filter (where won) as cnt
    from cohort group by b, rep
  )
  select case when not (select ok from allowed) then null else jsonb_build_object(
    'grain', (select grain from g),
    'start', p_start,
    'end',   p_end,
    'periods', coalesce((
      select jsonb_agg(jsonb_build_object('b', b, 'total', total, 'count', cnt) order by b)
      from per_bucket
    ), '[]'::jsonb),
    'people', coalesce((
      select jsonb_agg(jsonb_build_object('b', b, 'k', rep, 'name', rep, 'total', total, 'count', cnt)
             order by b, rep)
      from per_person
    ), '[]'::jsonb)
  ) end;
$$;


ALTER FUNCTION public.scoreboard_sales_person_trend(p_company_id uuid, p_start date, p_end date, p_grain text) OWNER TO postgres;

--
-- Name: scoreboard_service_lines(uuid, date, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.scoreboard_service_lines(p_company_id uuid, p_start date, p_end date) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
  with allowed as (select public.scoreboard_reports_allowed(p_company_id) ok),
  -- A day under an hour company-wide is a test punch, not a working day. Keying
  -- coverage off any row at all let a single 0.02-hour punch on 2026-05-29 set the
  -- floor three days before anyone actually worked, pulling 34 completed visits and
  -- $2,974.75 of revenue into the measured window against essentially no labour --
  -- which flatters every line. The same rule guards the far end, so a trailing
  -- stray punch cannot extend the window either.
  day_totals as (
    select te.date d, sum(te.total_hours) h
    from time_entries te
    where te.company_id = p_company_id and te.total_hours > 0
    group by te.date
  ),
  coverage as (select min(d) first_day, max(d) last_day from day_totals where h >= 1),
  eff as (select greatest(p_start, c.first_day) s, least(p_end, c.last_day) e, c.first_day, c.last_day from coverage c),
  tech as (
    select e.id, e.hourly_rate, e.pay_type,
      (select ju.external_id from jobber_users ju
        where ju.company_id = e.company_id and ju.name ilike '%' || e.last_name || '%'
          and (ju.name ilike '%' || e.first_name || '%'
               or (nullif(e.preferred_name,'') is not null and ju.name ilike '%' || e.preferred_name || '%'))
        order by ju.is_active desc nulls last, ju.external_id limit 1) jid
    from employees e where e.company_id = p_company_id and e.is_field_labor
  ),
  vis as (
    select v.id, v.external_id, v.job_id, v.tech_external_user_ids,
      (v.completed_at at time zone 'America/Chicago')::date d
    from visits v, eff
    where v.company_id = p_company_id and v.deleted_at is null
      and v.visit_status = 'COMPLETED'
      and (v.completed_at at time zone 'America/Chicago')::date between eff.s and eff.e
      and upper(coalesce(v.title,'')) not like '%BILLING%'
  ),
  -- Service line of each visit, from the line item then the job then the title prefix.
  vis_dept as (
    select vis.id, vis.external_id, vis.job_id, vis.tech_external_user_ids, vis.d,
      coalesce(
        (select li.dept_prefix from line_items li
          where li.parent_external_id = vis.external_id and li.parent_type='visit'
            and li.company_id = p_company_id and li.deleted_at is null
            and li.dept_prefix is not null limit 1),
        j.dept_prefix,
        substring(upper(coalesce(j.title,'')) from '^(WF|IR|PW|MO|LD)'),
        'Other') dept,
      j.is_recurring
    from vis join jobs j on j.id = vis.job_id and j.deleted_at is null
  ),
  rev_recurring as (
    select vd.dept, sum(li.total) amt
    from vis_dept vd
    join line_items li on li.parent_external_id = vd.external_id and li.parent_type='visit'
      and li.company_id = p_company_id and li.deleted_at is null
    where vd.is_recurring
    group by vd.dept
  ),
  rev_oneoff as (
    select vd.dept, sum(j.total / nullif(jc.n,0)) amt
    from vis_dept vd
    join jobs j on j.id = vd.job_id
    join lateral (select count(*) n from visits v2
                  where v2.job_id = j.id and v2.deleted_at is null and v2.visit_status='COMPLETED') jc on true
    where not vd.is_recurring
    group by vd.dept
  ),
  visit_counts as (select dept, count(distinct id) n from vis_dept group by dept),
  -- Hours split across the lines each tech actually worked that day.
  tech_day_dept as (
    select t.id emp, vd.d, vd.dept, count(distinct vd.id) n
    from tech t join vis_dept vd on t.jid = any(vd.tech_external_user_ids)
    where t.jid is not null
    group by 1,2,3
  ),
  tech_day_tot as (select emp, d, sum(n) tot from tech_day_dept group by 1,2),
  -- Overtime. FLSA pays 1.5x past 40 hours in a Mon-Sun week, so the premium is a
  -- WEEKLY fact while this report splits an employee's hours DAILY across service
  -- lines. The half-time premium is therefore spread across every hour of that week
  -- as a blended rate, so a line's cost never depends on which day of the week the
  -- work happened to fall on. Measured against the alternative -- charging the
  -- premium to the hours that actually crossed 40 -- the two differ by under $10 on
  -- any line, and Pet Waste (the line this report exists to flag) has no overtime at
  -- all, so the choice is immaterial and the stable rule is the better one.
  --
  -- Weeks are read UNCLIPPED by the report window: a range starting mid-week still
  -- needs to know whether that whole week crossed 40, or its hours get priced flat.
  emp_days as (
    select te.employee_id emp, te.date d, sum(te.total_hours) h
    from time_entries te join tech t on t.id = te.employee_id
    where te.company_id = p_company_id and te.total_hours > 0 and t.pay_type = 'hourly'
    group by 1,2
  ),
  week_mult as (
    select emp, date_trunc('week', d)::date w,
      case when sum(h) > 0 then 1 + 0.5 * greatest(sum(h) - 40, 0) / sum(h) else 1 end mult
    from emp_days group by 1,2
  ),
  hours as (
    select te.employee_id emp, te.date d, te.total_hours h, t.hourly_rate, t.pay_type,
      coalesce(wm.mult, 1) mult
    from time_entries te
      join tech t on t.id = te.employee_id
      left join week_mult wm on wm.emp = te.employee_id and wm.w = date_trunc('week', te.date)::date,
      eff
    where te.company_id = p_company_id and te.total_hours > 0
      and te.date between eff.s and eff.e
  ),
  labor as (
    select tdd.dept,
      sum(h.h * tdd.n::numeric / tdt.tot) hrs,
      sum(h.h * tdd.n::numeric / tdt.tot * coalesce(h.hourly_rate,0) * h.mult) cost,
      sum(h.h * tdd.n::numeric / tdt.tot * coalesce(h.hourly_rate,0) * (h.mult - 1)) ot_premium
    from hours h
    join tech_day_tot tdt on tdt.emp = h.emp and tdt.d = h.d
    join tech_day_dept tdd on tdd.emp = h.emp and tdd.d = h.d
    where h.pay_type = 'hourly'
    group by tdd.dept
  ),
  unassigned as (
    select coalesce(round(sum(h.h),1),0) hrs,
      coalesce(round(sum(h.h * coalesce(h.hourly_rate,0) * h.mult),2),0) cost,
      coalesce(round(sum(h.h * coalesce(h.hourly_rate,0) * (h.mult - 1)),2),0) ot_premium
    from hours h left join tech_day_tot tdt on tdt.emp = h.emp and tdt.d = h.d
    where tdt.emp is null and h.pay_type = 'hourly'
  ),
  lines as (
    select coalesce(rr.dept, ro.dept, l.dept, vc.dept) dept,
      coalesce(rr.amt,0) rec, coalesce(ro.amt,0) one,
      coalesce(rr.amt,0) + coalesce(ro.amt,0) revenue,
      coalesce(l.hrs,0) hrs, coalesce(l.cost,0) cost,
      coalesce(l.ot_premium,0) ot_premium, coalesce(vc.n,0) visits
    from rev_recurring rr
    full outer join rev_oneoff ro on ro.dept = rr.dept
    full outer join labor l on l.dept = coalesce(rr.dept, ro.dept)
    full outer join visit_counts vc on vc.dept = coalesce(rr.dept, ro.dept, l.dept)
  )
  select case when not (select ok from allowed) then null else jsonb_build_object(
    'coverage', jsonb_build_object(
      'timeclock_first', (select first_day from eff),
      'timeclock_last',  (select last_day from eff),
      'effective_start', (select s from eff),
      'effective_end',   (select e from eff),
      'requested_start', p_start,
      'requested_end',   p_end,
      'clamped', (select (s <> p_start or e <> p_end) from eff),
      'has_data', (select (s <= e) from eff)
    ),
    'revenue_total',  coalesce((select round(sum(revenue),2) from lines), 0),
    'labor_total',    coalesce((select round(sum(cost),2) from lines), 0) + (select cost from unassigned),
    'labor_allocated',coalesce((select round(sum(cost),2) from lines), 0),
    'hours_total',    coalesce((select round(sum(hrs),1) from lines), 0) + (select hrs from unassigned),
    'unassigned_hours', (select hrs from unassigned),
    'unassigned_cost',  (select cost from unassigned),
    -- The overtime premium carried inside labor_total, so the uplift is auditable
    -- rather than buried in a rate.
    'labor_overtime_premium', coalesce((select round(sum(ot_premium),2) from lines), 0) + (select ot_premium from unassigned),
    -- Coverage of the product mapping, so the absence of a materials column is a
    -- stated gap rather than an implied zero.
    'material_mapping_line_items', (select count(*) from service_products
                                    where company_id = p_company_id and deleted_at is null and is_active),
    'lines', coalesce((
      select jsonb_agg(x order by (x->>'revenue')::numeric desc)
      from (
        select jsonb_build_object(
          'dept', dept,
          'revenue', round(revenue,2),
          'revenue_recurring', round(rec,2),
          'revenue_oneoff', round(one,2),
          'visits', visits,
          'hours', round(hrs,1),
          'labor_cost', round(cost,2),
          'labor_overtime', round(ot_premium,2),
          'after_labor', round(revenue - cost,2),
          'after_labor_pct', case when revenue > 0 then round(100*(revenue-cost)/revenue,1) end,
          'rev_per_hour', case when hrs > 0 then round(revenue/hrs,2) end
        ) x
        from lines where revenue > 0 or hrs > 0
      ) y
    ), '[]'::jsonb)
  ) end;
$_$;


ALTER FUNCTION public.scoreboard_service_lines(p_company_id uuid, p_start date, p_end date) OWNER TO postgres;

--
-- Name: FUNCTION scoreboard_service_lines(p_company_id uuid, p_start date, p_end date); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.scoreboard_service_lines(p_company_id uuid, p_start date, p_end date) IS 'Service Line Profitability 8.8 (rescoped from per-job: the timeclock has no job link). Labor allocated by the visits each tech actually completed each day, NOT by their department field. Days with no visits are returned as UNASSIGNED so nothing is dropped. Revenue includes one-off work - recurring-only makes irrigation look like it loses money. Materials excluded: only 4 of 87 line items are mapped, so charging them to one line would be an artefact.';


--
-- Name: scoreboard_service_lines_unclassified(uuid, date, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.scoreboard_service_lines_unclassified(p_company_id uuid, p_start date, p_end date) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  -- The visits that landed in Service Lines' "Other / Unclassified" bucket.
  -- The window, the visit filter and the dept precedence are COPIED VERBATIM from
  -- scoreboard_service_lines so the list cannot disagree with the tile above it.
  -- Diff the two whenever either changes.
  with allowed as (select public.scoreboard_reports_allowed(p_company_id) ok),
  coverage as (
    select min(te.date) first_day, max(te.date) last_day
    from time_entries te where te.company_id = p_company_id and te.total_hours > 0
  ),
  eff as (select greatest(p_start, c.first_day) s, least(p_end, c.last_day) e from coverage c),
  vis as (
    select v.id, v.external_id, v.job_id, v.title,
      (v.completed_at at time zone 'America/Chicago')::date d
    from visits v, eff
    where v.company_id = p_company_id and v.deleted_at is null
      and v.visit_status = 'COMPLETED'
      and (v.completed_at at time zone 'America/Chicago')::date between eff.s and eff.e
      and upper(coalesce(v.title,'')) not like '%BILLING%'
  ),
  vis_dept as (
    select vis.*, j.title job_title, j.dept_prefix job_dept, j.is_recurring, j.total job_total,
      j.client_id,
      coalesce(
        (select li.dept_prefix from line_items li
          where li.parent_external_id = vis.external_id and li.parent_type='visit'
            and li.company_id = p_company_id and li.deleted_at is null
            and li.dept_prefix is not null limit 1),
        j.dept_prefix,
        substring(upper(coalesce(j.title,'')) from '^(WF|IR|PW|MO|LD)'),
        'Other') dept
    from vis join jobs j on j.id = vis.job_id and j.deleted_at is null
  ),
  other as (select * from vis_dept where dept = 'Other'),
  priced as (
    select o.*,
      case when o.is_recurring then (
        select coalesce(sum(li.total),0) from line_items li
        where li.parent_external_id = o.external_id and li.parent_type='visit'
          and li.company_id = p_company_id and li.deleted_at is null)
      else o.job_total / nullif((select count(*) from visits v2
        where v2.job_id = o.job_id and v2.deleted_at is null and v2.visit_status='COMPLETED'),0)
      end revenue,
      (select string_agg(li.name, ' · ' order by li.name) from line_items li
        where li.parent_external_id = o.external_id and li.parent_type='visit'
          and li.company_id = p_company_id and li.deleted_at is null) item_names
    from other o
  )
  select case when not (select ok from allowed) then null else
    coalesce((select jsonb_agg(jsonb_build_object(
      'client',    coalesce(c.name,'—'),
      'job_title', coalesce(p.job_title,'—'),
      'items',     coalesce(p.item_names,'no line item on the visit'),
      'completed', p.d,
      'revenue',   round(coalesce(p.revenue,0), 2)
    ) order by p.d desc) from priced p left join clients c on c.id = p.client_id), '[]'::jsonb)
  end;
$$;


ALTER FUNCTION public.scoreboard_service_lines_unclassified(p_company_id uuid, p_start date, p_end date) OWNER TO postgres;

--
-- Name: scoreboard_source_scorecard(uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.scoreboard_source_scorecard(p_company_id uuid, p_year integer) RETURNS TABLE(source text, source_group text, cost_type text, total_customers bigint, active_count bigint, churned_count bigint, retention_pct numeric, new_in_year bigint, active_annual_value numeric, avg_annual_value numeric, avg_tenure_months numeric, est_ltv numeric, unresolved_count bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  with gate as (
    select 1 where (select auth.uid()) is null
      or exists (
        select 1 from public.user_profiles up
        where up.id = (select auth.uid())
          and up.company_id = p_company_id
          and (up.role = 'admin' or up.can_access_scoreboards)
      )
  ),
  scope as (
    select rs.*,
      case
        when rs.cancelled_status = 'Cancelled'
         and extract(year from rs.cancel_date) = p_year then 'churned'
        when rs.cancelled_status = 'Active' then 'active'
      end as bucket
    from public.recurring_services rs, gate
    where rs.company_id = p_company_id
      and (rs.cancelled_status = 'Active'
        or (rs.cancelled_status = 'Cancelled' and extract(year from rs.cancel_date) = p_year))
  ),
  resolved as (
    select s.*,
      public.churn_resolve_source(p_company_id, s.lead_source, s.email, s.phone, s.name) as src,
      cl.external_created_at as client_since
    from scope s
    left join lateral (
      select c.external_created_at
      from public.clients c
      where c.company_id = p_company_id
        and (
          (coalesce(s.email,'') <> '' and lower(c.email) = lower(s.email))
          or (regexp_replace(coalesce(s.phone,''),'\D','','g') <> ''
              and regexp_replace(coalesce(c.phone,''),'\D','','g') = regexp_replace(s.phone,'\D','','g'))
        )
      order by (lower(c.email) = lower(coalesce(s.email,''))) desc
      limit 1
    ) cl on true
  )
  select
    coalesce(r.src, 'Other / Unknown')                                   as source,
    coalesce(max(m.source_group), 'Other')                               as source_group,
    coalesce(max(m.cost_type), 'Unknown')                                as cost_type,
    count(*)                                                             as total_customers,
    count(*) filter (where r.bucket = 'active')                          as active_count,
    count(*) filter (where r.bucket = 'churned')                         as churned_count,
    round(100.0 * count(*) filter (where r.bucket = 'active')
      / nullif(count(*), 0), 1)                                          as retention_pct,
    count(*) filter (where extract(year from r.sold_date) = p_year)      as new_in_year,
    coalesce(sum(r.annual_value) filter (where r.bucket = 'active'), 0)  as active_annual_value,
    round(avg(r.annual_value) filter (where r.bucket = 'active'), 0)     as avg_annual_value,
    round(avg(
      extract(epoch from (
        case when r.bucket = 'churned' then r.cancel_date::timestamptz else now() end
        - r.client_since
      )) / 2629800.0
    ) filter (where r.client_since is not null), 1)                      as avg_tenure_months,
    round(
      coalesce(avg(r.annual_value) filter (where r.bucket = 'active'), 0)
      * coalesce(avg(
          extract(epoch from (
            case when r.bucket = 'churned' then r.cancel_date::timestamptz else now() end
            - r.client_since
          )) / 2629800.0
        ) filter (where r.client_since is not null), 0) / 12.0
    , 0)                                                                 as est_ltv,
    count(*) filter (where r.src is null)                                as unresolved_count
  from resolved r
  left join public.lead_sources_master m
    on m.company_id = p_company_id and lower(m.master_source) = lower(coalesce(r.src, 'Other / Unknown'))
  group by coalesce(r.src, 'Other / Unknown')
  order by total_customers desc
$$;


ALTER FUNCTION public.scoreboard_source_scorecard(p_company_id uuid, p_year integer) OWNER TO postgres;

--
-- Name: scoreboard_source_scorecard_range(uuid, date, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.scoreboard_source_scorecard_range(p_company_id uuid, p_start date, p_end date) RETURNS TABLE(source text, source_group text, cost_type text, total_customers bigint, active_count bigint, churned_count bigint, retention_pct numeric, new_in_year bigint, active_annual_value numeric, avg_annual_value numeric, avg_tenure_months numeric, est_ltv numeric, unresolved_count bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  with gate as (
    select 1 where (select auth.uid()) is null
      or exists (
        select 1 from public.user_profiles up
        where up.id = (select auth.uid())
          and up.company_id = p_company_id
          and (up.role = 'admin' or up.can_access_scoreboards)
      )
  ),
  scope as (
    select rs.*,
      case
        when rs.cancelled_status = 'Cancelled'
         and rs.cancel_date >= p_start and rs.cancel_date <= p_end then 'churned'
        when rs.cancelled_status = 'Active' then 'active'
      end as bucket
    from public.recurring_services rs, gate
    where rs.company_id = p_company_id
      and (rs.cancelled_status = 'Active'
        or (rs.cancelled_status = 'Cancelled'
            and rs.cancel_date >= p_start and rs.cancel_date <= p_end))
  ),
  resolved as (
    select s.*,
      public.churn_resolve_source(p_company_id, s.lead_source, s.email, s.phone, s.name) as src,
      cl.external_created_at as client_since
    from scope s
    left join lateral (
      select c.external_created_at
      from public.clients c
      where c.company_id = p_company_id
        and (
          (coalesce(s.email,'') <> '' and lower(c.email) = lower(s.email))
          or (regexp_replace(coalesce(s.phone,''),'\D','','g') <> ''
              and regexp_replace(coalesce(c.phone,''),'\D','','g') = regexp_replace(s.phone,'\D','','g'))
        )
      order by (lower(c.email) = lower(coalesce(s.email,''))) desc
      limit 1
    ) cl on true
  )
  select
    coalesce(r.src, 'Other / Unknown')                                   as source,
    coalesce(max(m.source_group), 'Other')                               as source_group,
    coalesce(max(m.cost_type), 'Unknown')                                as cost_type,
    count(*)                                                             as total_customers,
    count(*) filter (where r.bucket = 'active')                          as active_count,
    count(*) filter (where r.bucket = 'churned')                         as churned_count,
    round(100.0 * count(*) filter (where r.bucket = 'active')
      / nullif(count(*), 0), 1)                                          as retention_pct,
    count(*) filter (where r.sold_date >= p_start and r.sold_date <= p_end) as new_in_year,
    coalesce(sum(r.annual_value) filter (where r.bucket = 'active'), 0)  as active_annual_value,
    round(avg(r.annual_value) filter (where r.bucket = 'active'), 0)     as avg_annual_value,
    round(avg(
      extract(epoch from (
        case when r.bucket = 'churned' then r.cancel_date::timestamptz else now() end
        - r.client_since
      )) / 2629800.0
    ) filter (where r.client_since is not null), 1)                      as avg_tenure_months,
    round(
      coalesce(avg(r.annual_value) filter (where r.bucket = 'active'), 0)
      * coalesce(avg(
          extract(epoch from (
            case when r.bucket = 'churned' then r.cancel_date::timestamptz else now() end
            - r.client_since
          )) / 2629800.0
        ) filter (where r.client_since is not null), 0) / 12.0
    , 0)                                                                 as est_ltv,
    count(*) filter (where r.src is null)                                as unresolved_count
  from resolved r
  left join public.lead_sources_master m
    on m.company_id = p_company_id and lower(m.master_source) = lower(coalesce(r.src, 'Other / Unknown'))
  group by coalesce(r.src, 'Other / Unknown')
  order by total_customers desc
$$;


