--
-- Name: scoreboard_tech_hours(uuid, date, date, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.scoreboard_tech_hours(p_company_id uuid, p_start date, p_end date, p_employee_id uuid) RETURNS numeric
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT COALESCE(SUM(te.total_hours), 0)
  FROM time_entries te
  WHERE te.company_id  = p_company_id
    AND te.employee_id = p_employee_id
    AND te.date BETWEEN p_start AND p_end
    AND (
      (SELECT auth.uid()) IS NULL
      OR EXISTS (
        SELECT 1 FROM user_profiles up
        WHERE up.id = (SELECT auth.uid())
          AND up.company_id = p_company_id
          AND (up.role = 'admin' OR up.can_access_scoreboards)
      )
    )
$$;


ALTER FUNCTION public.scoreboard_tech_hours(p_company_id uuid, p_start date, p_end date, p_employee_id uuid) OWNER TO postgres;

--
-- Name: scoreboard_tech_revenue(uuid, date, date, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.scoreboard_tech_revenue(p_company_id uuid, p_start date, p_end date, p_bucket text, p_tech_external_id text) RETURNS TABLE(bucket date, dept text, total numeric)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  WITH allowed AS (
    SELECT ((SELECT auth.uid()) IS NULL OR EXISTS (
      SELECT 1 FROM user_profiles up WHERE up.id=(SELECT auth.uid())
        AND up.company_id=p_company_id AND (up.role='admin' OR up.can_access_scoreboards))) AS ok
  ),
  recurring AS (
    SELECT date_trunc(CASE WHEN p_bucket='week' THEN 'week' ELSE 'month' END, v.completed_at)::date AS bucket,
           COALESCE(li.dept_prefix, j.dept_prefix, 'Other') AS dept, li.total AS amt
    FROM visits v
    JOIN jobs j ON j.id=v.job_id AND j.deleted_at IS NULL AND j.is_recurring=true
    JOIN line_items li ON li.parent_external_id=v.external_id AND li.parent_type='visit'
      AND li.company_id=p_company_id AND li.deleted_at IS NULL
    WHERE v.company_id=p_company_id AND v.deleted_at IS NULL AND v.visit_status='COMPLETED'
      AND v.completed_at::date BETWEEN p_start AND p_end AND UPPER(COALESCE(v.title,'')) NOT LIKE '%BILLING%'
      AND p_tech_external_id = ANY(v.tech_external_user_ids)
  ),
  oneoff AS (
    SELECT date_trunc(CASE WHEN p_bucket='week' THEN 'week' ELSE 'month' END, v.completed_at)::date AS bucket,
           COALESCE(j.dept_prefix, substring(UPPER(COALESCE(j.title,'')) from '^(WF|IR|PW|MO|LD)'), 'Other') AS dept,
           j.total / NULLIF(jc.n,0) AS amt
    FROM visits v
    JOIN jobs j ON j.id=v.job_id AND j.deleted_at IS NULL AND j.is_recurring=false
    JOIN LATERAL (SELECT count(*) n FROM visits v2 WHERE v2.job_id=j.id AND v2.deleted_at IS NULL AND v2.visit_status='COMPLETED') jc ON true
    WHERE v.company_id=p_company_id AND v.deleted_at IS NULL AND v.visit_status='COMPLETED'
      AND v.completed_at::date BETWEEN p_start AND p_end AND UPPER(COALESCE(v.title,'')) NOT LIKE '%BILLING%'
      AND p_tech_external_id = ANY(v.tech_external_user_ids)
      AND NOT EXISTS (SELECT 1 FROM install_labor_credits c WHERE c.company_id=p_company_id AND c.job_id=j.id)
  ),
  credits AS (
    SELECT date_trunc(CASE WHEN p_bucket='week' THEN 'week' ELSE 'month' END, c.credit_date)::date AS bucket,
           COALESCE(j.dept_prefix, substring(UPPER(COALESCE(j.title,'')) from '^(WF|IR|PW|MO|LD)'), 'Other') AS dept,
           c.credit_amount AS amt
    FROM install_labor_credits c JOIN jobs j ON j.id=c.job_id
    WHERE c.company_id=p_company_id AND c.credit_date BETWEEN p_start AND p_end
      AND c.jobber_user_external_id = p_tech_external_id
  )
  SELECT t.bucket, t.dept, SUM(t.amt) AS total
  FROM (SELECT bucket,dept,amt FROM recurring WHERE (SELECT ok FROM allowed)
        UNION ALL SELECT bucket,dept,amt FROM oneoff WHERE (SELECT ok FROM allowed)
        UNION ALL SELECT bucket,dept,amt FROM credits WHERE (SELECT ok FROM allowed)) t
  GROUP BY t.bucket, t.dept
  ORDER BY t.bucket, t.dept
$$;


ALTER FUNCTION public.scoreboard_tech_revenue(p_company_id uuid, p_start date, p_end date, p_bucket text, p_tech_external_id text) OWNER TO postgres;

--
-- Name: scoreboard_techs_hours(uuid, date, date, uuid[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.scoreboard_techs_hours(p_company_id uuid, p_start date, p_end date, p_employee_ids uuid[]) RETURNS TABLE(employee_id uuid, hours numeric)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  select e.employee_id, coalesce(sum(te.total_hours), 0) as hours
  from unnest(p_employee_ids) as e(employee_id)
  left join time_entries te
    on te.employee_id = e.employee_id
   and te.company_id  = p_company_id
   and te.date between p_start and p_end
  where (
    (select auth.uid()) is null
    or exists (
      select 1 from user_profiles up
      where up.id = (select auth.uid())
        and up.company_id = p_company_id
        and (up.role = 'admin' or up.can_access_scoreboards)
    )
  )
  group by e.employee_id
$$;


ALTER FUNCTION public.scoreboard_techs_hours(p_company_id uuid, p_start date, p_end date, p_employee_ids uuid[]) OWNER TO postgres;

--
-- Name: scoreboard_techs_revenue(uuid, date, date, text, text[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.scoreboard_techs_revenue(p_company_id uuid, p_start date, p_end date, p_bucket text, p_tech_external_ids text[]) RETURNS TABLE(tech_external_id text, bucket date, dept text, total numeric)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  WITH allowed AS (
    SELECT ((SELECT auth.uid()) IS NULL OR EXISTS (
      SELECT 1 FROM user_profiles up WHERE up.id=(SELECT auth.uid())
        AND up.company_id=p_company_id AND (up.role='admin' OR up.can_access_scoreboards))) AS ok
  ),
  recurring AS (
    SELECT tech.tid AS tech_external_id,
           date_trunc(CASE WHEN p_bucket='week' THEN 'week' ELSE 'month' END, v.completed_at)::date AS bucket,
           COALESCE(li.dept_prefix, j.dept_prefix, 'Other') AS dept, li.total AS amt
    FROM unnest(p_tech_external_ids) AS tech(tid)
    JOIN visits v ON tech.tid = ANY(v.tech_external_user_ids)
      AND v.company_id=p_company_id AND v.deleted_at IS NULL AND v.visit_status='COMPLETED'
      AND v.completed_at::date BETWEEN p_start AND p_end AND UPPER(COALESCE(v.title,'')) NOT LIKE '%BILLING%'
    JOIN jobs j ON j.id=v.job_id AND j.deleted_at IS NULL AND j.is_recurring=true
    JOIN line_items li ON li.parent_external_id=v.external_id AND li.parent_type='visit'
      AND li.company_id=p_company_id AND li.deleted_at IS NULL
  ),
  oneoff AS (
    SELECT tech.tid AS tech_external_id,
           date_trunc(CASE WHEN p_bucket='week' THEN 'week' ELSE 'month' END, v.completed_at)::date AS bucket,
           COALESCE(j.dept_prefix, substring(UPPER(COALESCE(j.title,'')) from '^(WF|IR|PW|MO|LD)'), 'Other') AS dept,
           j.total / NULLIF(jc.n,0) AS amt
    FROM unnest(p_tech_external_ids) AS tech(tid)
    JOIN visits v ON tech.tid = ANY(v.tech_external_user_ids)
      AND v.company_id=p_company_id AND v.deleted_at IS NULL AND v.visit_status='COMPLETED'
      AND v.completed_at::date BETWEEN p_start AND p_end AND UPPER(COALESCE(v.title,'')) NOT LIKE '%BILLING%'
    JOIN jobs j ON j.id=v.job_id AND j.deleted_at IS NULL AND j.is_recurring=false
    JOIN LATERAL (SELECT count(*) n FROM visits v2 WHERE v2.job_id=j.id AND v2.deleted_at IS NULL AND v2.visit_status='COMPLETED') jc ON true
    WHERE NOT EXISTS (SELECT 1 FROM install_labor_credits c WHERE c.company_id=p_company_id AND c.job_id=j.id)
  ),
  credits AS (
    SELECT c.jobber_user_external_id AS tech_external_id,
           date_trunc(CASE WHEN p_bucket='week' THEN 'week' ELSE 'month' END, c.credit_date)::date AS bucket,
           COALESCE(j.dept_prefix, substring(UPPER(COALESCE(j.title,'')) from '^(WF|IR|PW|MO|LD)'), 'Other') AS dept,
           c.credit_amount AS amt
    FROM install_labor_credits c JOIN jobs j ON j.id=c.job_id
    WHERE c.company_id=p_company_id AND c.credit_date BETWEEN p_start AND p_end
      AND c.jobber_user_external_id = ANY(p_tech_external_ids)
  )
  SELECT t.tech_external_id, t.bucket, t.dept, SUM(t.amt) AS total
  FROM (SELECT tech_external_id,bucket,dept,amt FROM recurring WHERE (SELECT ok FROM allowed)
        UNION ALL SELECT tech_external_id,bucket,dept,amt FROM oneoff WHERE (SELECT ok FROM allowed)
        UNION ALL SELECT tech_external_id,bucket,dept,amt FROM credits WHERE (SELECT ok FROM allowed)) t
  GROUP BY t.tech_external_id, t.bucket, t.dept
  ORDER BY t.tech_external_id, t.bucket, t.dept
$$;


ALTER FUNCTION public.scoreboard_techs_revenue(p_company_id uuid, p_start date, p_end date, p_bucket text, p_tech_external_ids text[]) OWNER TO postgres;

--
-- Name: scoreboard_ticket_size(uuid, date, date, text[], text[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.scoreboard_ticket_size(p_company_id uuid, p_start date, p_end date, p_lines text[] DEFAULT NULL::text[], p_exclude text[] DEFAULT NULL::text[]) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  with allowed as (select public.scoreboard_reports_allowed(p_company_id) ok),
  ex as (
    -- Escape LIKE metacharacters. An exclusion typed as "Slip Fix 1_inch" would
    -- otherwise widen itself into a wildcard and quietly drop more rows than it
    -- names, giving a silently wrong average rather than an error.
    select '%' || replace(replace(replace(f, '\', '\\'), '%', '\%'), '_', '\_') || '%' as pat
    from unnest(coalesce(p_exclude, '{}'::text[])) f
    where coalesce(trim(f), '') <> ''
  ),
  tickets as (
    select v.id as visit_id, li.dept_prefix, sum(li.total) as ticket_total
    from public.visits v
    join public.line_items li
      on li.parent_external_id = v.external_id
     and li.parent_type = 'visit'
     and li.company_id = p_company_id
     and li.deleted_at is null
     and li.total <> 0
     and (p_lines is null or li.dept_prefix = any(p_lines))
     and not exists (select 1 from ex where li.name ilike ex.pat)
    where v.company_id = p_company_id
      and v.deleted_at is null
      and v.visit_status = 'COMPLETED'
      and v.completed_at::date between p_start and p_end
    -- Grain is (visit, line): a visit carrying a sprinkler repair AND a lawn
    -- treatment is two tickets, one per line, which is the only grouping where a
    -- per-line average means anything.
    group by v.id, li.dept_prefix
    having sum(li.total) <> 0
  )
  select case when not (select ok from allowed) then null else jsonb_build_object(
    'ticket_count',  (select count(*) from tickets),
    'avg_value',     (select round(avg(ticket_total), 2) from tickets),
    'median_value',  (select round((percentile_cont(0.5) within group (order by ticket_total))::numeric, 2) from tickets),
    'total_value',   (select round(sum(ticket_total), 2) from tickets),
    'by_line', coalesce((
      select jsonb_agg(x order by (x->>'total_value')::numeric desc)
      from (
        select jsonb_build_object(
          'line',         coalesce(dept_prefix, 'Unassigned'),
          'ticket_count', count(*),
          'avg_value',    round(avg(ticket_total), 2),
          'median_value', round((percentile_cont(0.5) within group (order by ticket_total))::numeric, 2),
          'total_value',  round(sum(ticket_total), 2)
        ) x
        from tickets group by dept_prefix
      ) y
    ), '[]'::jsonb)
  ) end
$$;


ALTER FUNCTION public.scoreboard_ticket_size(p_company_id uuid, p_start date, p_end date, p_lines text[], p_exclude text[]) OWNER TO postgres;

--
-- Name: scoreboard_ticket_size(uuid, date, date, text[], text[], text[], text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.scoreboard_ticket_size(p_company_id uuid, p_start date, p_end date, p_lines text[], p_exclude text[], p_items text[], p_items_mode text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  with allowed as (select public.scoreboard_reports_allowed(p_company_id) ok),
  ex as (
    select '%' || replace(replace(replace(f, '\', '\\'), '%', '\%'), '_', '\_') || '%' as pat
    from unnest(coalesce(p_exclude, '{}'::text[])) f
    where coalesce(trim(f), '') <> ''
  ),
  picked as (
    select lower(regexp_replace(btrim(i), '\s+', ' ', 'g')) as k
    from unnest(coalesce(p_items, '{}'::text[])) i
    where coalesce(trim(i), '') <> ''
  ),
  mode as (select case when lower(coalesce(p_items_mode, 'include')) = 'exclude'
                       then 'exclude' else 'include' end m),
  scoped as (
    select li.name, li.total, li.dept_prefix, v.id as visit_id,
           (select count(*) from picked) as n_picked,
           (select m from mode) as m
    from public.visits v
    join public.line_items li
      on li.parent_external_id = v.external_id
     and li.parent_type = 'visit'
     and li.company_id = p_company_id
     and li.deleted_at is null
     and li.total <> 0
     and (p_lines is null or li.dept_prefix = any(p_lines))
     and not exists (select 1 from ex where li.name ilike ex.pat)
    where v.company_id = p_company_id
      and v.deleted_at is null
      and v.visit_status = 'COMPLETED'
      and v.completed_at::date between p_start and p_end
  ),
  marked as (
    select s.*,
           case
             when s.n_picked = 0 then true
             when s.m = 'exclude'
               then not exists (select 1 from picked p
                                where p.k = lower(regexp_replace(btrim(s.name), '\s+', ' ', 'g')))
             else      exists (select 1 from picked p
                                where p.k = lower(regexp_replace(btrim(s.name), '\s+', ' ', 'g')))
           end as counted
    from scoped s
  ),
  tickets as (
    select visit_id, dept_prefix, sum(total) as ticket_total
    from marked where counted
    group by visit_id, dept_prefix
    having sum(total) <> 0
  )
  select case when not (select ok from allowed) then null else jsonb_build_object(
    'ticket_count',  (select count(*) from tickets),
    'avg_value',     (select round(avg(ticket_total), 2) from tickets),
    'median_value',  (select round((percentile_cont(0.5) within group (order by ticket_total))::numeric, 2) from tickets),
    'total_value',   (select round(sum(ticket_total), 2) from tickets),
    'off_list_lines', (select count(*) from marked where not counted),
    'off_list_value', (select round(sum(total), 2) from marked where not counted),
    'by_line', coalesce((
      select jsonb_agg(x order by (x->>'total_value')::numeric desc)
      from (
        select jsonb_build_object(
          'line',         coalesce(dept_prefix, 'Unassigned'),
          'ticket_count', count(*),
          'avg_value',    round(avg(ticket_total), 2),
          'median_value', round((percentile_cont(0.5) within group (order by ticket_total))::numeric, 2),
          'total_value',  round(sum(ticket_total), 2)
        ) x
        from tickets group by dept_prefix
      ) y
    ), '[]'::jsonb)
  ) end
$$;


ALTER FUNCTION public.scoreboard_ticket_size(p_company_id uuid, p_start date, p_end date, p_lines text[], p_exclude text[], p_items text[], p_items_mode text) OWNER TO postgres;

--
-- Name: scoreboard_ticket_size_by_tech(uuid, date, date, text[], text[], text, text[], text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.scoreboard_ticket_size_by_tech(p_company_id uuid, p_start date, p_end date, p_lines text[], p_items text[], p_items_mode text, p_techs text[], p_tech_credit text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  with allowed as (select public.scoreboard_reports_allowed(p_company_id) ok),
  picked as (
    select lower(regexp_replace(btrim(i), '\s+', ' ', 'g')) as k
    from unnest(coalesce(p_items, '{}'::text[])) i
    where coalesce(trim(i), '') <> ''
  ),
  wanted_techs as (
    select lower(regexp_replace(btrim(t), '\s+', ' ', 'g')) as k
    from unnest(coalesce(p_techs, '{}'::text[])) t
    where coalesce(trim(t), '') <> ''
  ),
  mode as (select case when lower(coalesce(p_items_mode, 'include')) = 'exclude'
                       then 'exclude' else 'include' end m),
  credit as (select case when lower(coalesce(p_tech_credit, 'each')) = 'split'
                         then 'split' else 'each' end c),
  scoped as (
    select li.name, li.total, li.dept_prefix, v.id as visit_id,
           coalesce(v.tech_external_user_ids, array[]::text[]) as techs
    from public.visits v
    join public.line_items li
      on li.parent_external_id = v.external_id
     and li.parent_type = 'visit'
     and li.company_id = p_company_id
     and li.deleted_at is null
     and li.total <> 0
     and (p_lines is null or li.dept_prefix = any(p_lines))
    where v.company_id = p_company_id
      and v.deleted_at is null
      and v.visit_status = 'COMPLETED'
      and v.completed_at::date between p_start and p_end
  ),
  marked as (
    select s.*,
           case
             when (select count(*) from picked) = 0 then true
             when (select m from mode) = 'exclude'
               then not exists (select 1 from picked p
                                where p.k = lower(regexp_replace(btrim(s.name), '\s+', ' ', 'g')))
             else      exists (select 1 from picked p
                                where p.k = lower(regexp_replace(btrim(s.name), '\s+', ' ', 'g')))
           end as counted
    from scoped s
  ),
  tickets as (
    select visit_id, dept_prefix, techs, sum(total) as ticket_total
    from marked where counted
    group by visit_id, dept_prefix, techs
    having sum(total) <> 0
  ),
  per_tech as (
    select coalesce(nullif(ju.name, ''), 'Unknown (' || left(t.tid, 8) || ')') as tech_name,
           case when (select c from credit) = 'split'
                then tk.ticket_total / nullif(array_length(tk.techs, 1), 0)
                else tk.ticket_total end as ticket_total
    from tickets tk
    cross join lateral unnest(tk.techs) as t(tid)
    left join public.jobber_users ju
      on ju.company_id = p_company_id and ju.external_id = t.tid
    union all
    select 'Nobody assigned', tk.ticket_total
    from tickets tk
    where coalesce(array_length(tk.techs, 1), 0) = 0
  ),
  selected as (
    select * from per_tech
    where (select count(*) from wanted_techs) = 0
       or lower(regexp_replace(btrim(tech_name), '\s+', ' ', 'g')) in (select k from wanted_techs)
  )
  select case when not (select ok from allowed) then null else jsonb_build_object(
    'ticket_count',  (select count(*) from selected),
    'avg_value',     (select round(avg(ticket_total), 2) from selected),
    'median_value',  (select round((percentile_cont(0.5) within group (order by ticket_total))::numeric, 2) from selected),
    'total_value',   (select round(sum(ticket_total), 2) from selected),
    'off_list_lines', (select count(*) from marked where not counted),
    'off_list_value', (select round(sum(total), 2) from marked where not counted),
    'shared_tickets', (select count(*) from tickets where coalesce(array_length(techs, 1), 0) > 1),
    'credit_mode',    (select c from credit),
    'by_tech', coalesce((
      select jsonb_agg(x order by (x->>'ticket_count')::int desc, x->>'tech')
      from (
        select jsonb_build_object(
          'tech',         tech_name,
          'ticket_count', count(*),
          'avg_value',    round(avg(ticket_total), 2),
          'median_value', round((percentile_cont(0.5) within group (order by ticket_total))::numeric, 2),
          'total_value',  round(sum(ticket_total), 2)
        ) x
        from selected group by tech_name
      ) y
    ), '[]'::jsonb)
  ) end
$$;


ALTER FUNCTION public.scoreboard_ticket_size_by_tech(p_company_id uuid, p_start date, p_end date, p_lines text[], p_items text[], p_items_mode text, p_techs text[], p_tech_credit text) OWNER TO postgres;

--
-- Name: scoreboard_visit_revenue(uuid, date, date, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.scoreboard_visit_revenue(p_company_id uuid, p_start date, p_end date, p_bucket text) RETURNS TABLE(bucket date, dept text, total numeric)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
  WITH allowed AS (
    SELECT ((SELECT auth.uid()) IS NULL
        OR EXISTS (
          SELECT 1 FROM user_profiles up
          WHERE up.id = (SELECT auth.uid())
            AND up.company_id = p_company_id
            AND (up.role = 'admin' OR up.can_access_scoreboards)
        )) AS ok
  ),
  -- Recurring jobs: each visit carries its own per-visit charge.
  -- Membership plan lines ARE counted. A previous comment here claimed they rode on
  -- a visit only to be invoiced and were not per-visit revenue; measured per job on
  -- 2026-08-17 that is false — the plan line lands on EVERY completed visit at
  -- exactly annual / visits-per-year (Silver $99.90, Bronze $97.50, both exact), so
  -- excluding it dropped the whole recurring half of the irrigation book.
  recurring AS (
    SELECT date_trunc(CASE WHEN p_bucket = 'week' THEN 'week' ELSE 'month' END, v.completed_at)::date AS bucket,
           COALESCE(li.dept_prefix, j.dept_prefix, 'Other') AS dept,
           li.total AS amt
    FROM visits v
    JOIN jobs j
      ON j.id = v.job_id AND j.deleted_at IS NULL AND j.is_recurring = true
    JOIN line_items li
      ON li.parent_external_id = v.external_id
     AND li.parent_type = 'visit'
     AND li.deleted_at IS NULL
     AND li.company_id = p_company_id
    WHERE v.company_id = p_company_id
      AND v.deleted_at IS NULL
      AND v.visit_status = 'COMPLETED'
      AND v.completed_at::date BETWEEN p_start AND p_end
      AND UPPER(COALESCE(v.title, '')) NOT LIKE '%BILLING%'
  ),
  -- One-off jobs (repairs, installs): count the job total ONCE, at its latest completed
  -- visit date in the window. Summing visit line items would multi-count multi-visit
  -- installs (the full install price is copied onto every visit of the job).
  oneoff AS (
    SELECT date_trunc(CASE WHEN p_bucket = 'week' THEN 'week' ELSE 'month' END, mv.max_completed)::date AS bucket,
           COALESCE(j.dept_prefix,
                    substring(UPPER(COALESCE(j.title, '')) from '^(WF|IR|PW|MO|LD)'),
                    'Other') AS dept,
           j.total AS amt
    FROM jobs j
    JOIN LATERAL (
      SELECT max(v.completed_at) AS max_completed, count(*) AS n
      FROM visits v
      WHERE v.job_id = j.id
        AND v.deleted_at IS NULL
        AND v.visit_status = 'COMPLETED'
        AND v.completed_at::date BETWEEN p_start AND p_end
    ) mv ON mv.n > 0
    WHERE j.company_id = p_company_id
      AND j.deleted_at IS NULL
      AND j.is_recurring = false
      AND UPPER(COALESCE(j.title, '')) NOT LIKE '%BILLING%'
  )
  SELECT t.bucket, t.dept, SUM(t.amt) AS total
  FROM (
    SELECT bucket, dept, amt FROM recurring WHERE (SELECT ok FROM allowed)
    UNION ALL
    SELECT bucket, dept, amt FROM oneoff    WHERE (SELECT ok FROM allowed)
  ) t
  GROUP BY t.bucket, t.dept
  ORDER BY t.bucket, t.dept
$_$;


ALTER FUNCTION public.scoreboard_visit_revenue(p_company_id uuid, p_start date, p_end date, p_bucket text) OWNER TO postgres;

--
-- Name: scoreboard_visit_revenue_trend(uuid, date, date, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.scoreboard_visit_revenue_trend(p_company_id uuid, p_start date, p_end date, p_grain text DEFAULT 'month'::text, p_tech_credit text DEFAULT 'each'::text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $_$
with allowed as (select public.scoreboard_reports_allowed(p_company_id) ok),
g as (
  select case when lower(coalesce(p_grain, 'month')) = 'week' then 'week' else 'month' end gr,
         case when lower(coalesce(p_tech_credit, 'each')) = 'split' then 'split' else 'each' end credit
),
vis as (
  select v.id, v.external_id, v.job_id, v.tech_external_user_ids techs,
         date_trunc((select gr from g), (v.completed_at at time zone 'America/Chicago')::date)::date b,
         j.dept_prefix jdept, j.title jtitle, j.is_recurring, j.total jtotal
  from visits v
  join jobs j on j.id = v.job_id and j.deleted_at is null
  where (select ok from allowed)
    and v.company_id = p_company_id and v.deleted_at is null
    and v.visit_status = 'COMPLETED'
    and (v.completed_at at time zone 'America/Chicago')::date between p_start and p_end
    and upper(coalesce(v.title, '')) not like '%BILLING%'
),
rec as (
  select vis.id vid, vis.b, coalesce(li.dept_prefix, vis.jdept, 'Other') dept,
         li.total amt, vis.techs, vis.job_id
  from vis
  join line_items li on li.parent_external_id = vis.external_id and li.parent_type = 'visit'
   and li.company_id = p_company_id and li.deleted_at is null
  where vis.is_recurring
),
oneoff as (
  select vis.id vid, vis.b,
         coalesce(vis.jdept, substring(upper(coalesce(vis.jtitle, '')) from '^(WF|IR|PW|MO|LD)'), 'Other') dept,
         vis.jtotal / nullif(jc.n, 0) amt, vis.techs, vis.job_id
  from vis
  join lateral (
    select count(*) n from visits v2
    where v2.job_id = vis.job_id and v2.deleted_at is null and v2.visit_status = 'COMPLETED'
  ) jc on true
  where not vis.is_recurring
),
parts as (select * from rec union all select * from oneoff),
credited_jobs as (select distinct job_id from install_labor_credits where company_id = p_company_id),
periods as (select b, sum(amt) total, count(distinct vid) visits from parts group by b),
lines as (select b, dept, sum(amt) total from parts group by b, dept),
tech_parts as (
  select p.b, p.dept, t.tid,
         case when (select credit from g) = 'split'
              then p.amt / nullif(array_length(p.techs, 1), 0)
              else p.amt end amt
  from parts p
  cross join lateral unnest(coalesce(p.techs, array[]::text[])) as t(tid)
  where not exists (select 1 from credited_jobs cj where cj.job_id = p.job_id)
  union all
  -- ⚠ used as-is under BOTH credit modes: a credit row is already one person's share.
  select date_trunc((select gr from g), c.credit_date)::date b,
         coalesce(j.dept_prefix, substring(upper(coalesce(j.title, '')) from '^(WF|IR|PW|MO|LD)'), 'Other') dept,
         c.jobber_user_external_id tid, c.credit_amount amt
  from install_labor_credits c join jobs j on j.id = c.job_id
  where c.company_id = p_company_id and c.credit_date between p_start and p_end
    and c.jobber_user_external_id is not null
),
techs as (
  select tp.b, tp.tid,
         coalesce(nullif(ju.name, ''), 'Unknown (' || left(tp.tid, 8) || ')') name,
         sum(tp.amt) total
  from tech_parts tp
  left join jobber_users ju on ju.company_id = p_company_id and ju.external_id = tp.tid
  group by tp.b, tp.tid, ju.name
),
line_techs as (
  select tp.b, tp.dept, tp.tid,
         coalesce(nullif(ju.name, ''), 'Unknown (' || left(tp.tid, 8) || ')') name,
         sum(tp.amt) total
  from tech_parts tp
  left join jobber_users ju on ju.company_id = p_company_id and ju.external_id = tp.tid
  group by tp.b, tp.dept, tp.tid, ju.name
  union all
  select p.b, p.dept, null::text tid, 'Nobody assigned' name, sum(p.amt) total
  from parts p
  where coalesce(array_length(p.techs, 1), 0) = 0
    and not exists (select 1 from credited_jobs cj where cj.job_id = p.job_id)
  group by p.b, p.dept
),
-- ⚠ Credited installs are EXCLUDED here. gaps exists to say how much the by-tech view
-- overstates, and credited jobs do not overstate at all — counting them made the
-- honesty line itself dishonest by $997.
gaps as (
  select
    coalesce(sum(amt) filter (where coalesce(array_length(techs, 1), 0) = 0), 0) unattributed_revenue,
    count(distinct vid) filter (where coalesce(array_length(techs, 1), 0) = 0) unattributed_visits,
    count(distinct vid) filter (where coalesce(array_length(techs, 1), 0) > 1) shared_visits,
    coalesce(sum(amt * (coalesce(array_length(techs, 1), 1) - 1))
             filter (where coalesce(array_length(techs, 1), 0) > 1), 0) shared_overlap
  from parts p
  where not exists (select 1 from credited_jobs cj where cj.job_id = p.job_id)
)
select jsonb_build_object(
  'grain',       (select gr from g),
  'tech_credit', (select credit from g),
  'start',       p_start,
  'end',         p_end,
  'total',       coalesce((select sum(total) from periods), 0),
  'periods',     coalesce((select jsonb_agg(jsonb_build_object('b', b, 'total', total, 'visits', visits) order by b) from periods), '[]'::jsonb),
  'lines',       coalesce((select jsonb_agg(jsonb_build_object('b', b, 'k', dept, 'total', total) order by b, dept) from lines), '[]'::jsonb),
  'techs',       coalesce((select jsonb_agg(jsonb_build_object('b', b, 'k', tid, 'name', name, 'total', total) order by b, name) from techs), '[]'::jsonb),
  'line_techs',  coalesce((select jsonb_agg(jsonb_build_object('b', b, 'd', dept, 'k', tid, 'name', name, 'total', total) order by b, dept, name) from line_techs), '[]'::jsonb),
  'shared_visits',        (select shared_visits from gaps),
  'shared_overlap',       case when (select credit from g) = 'split' then 0 else (select shared_overlap from gaps) end,
  'unattributed_revenue', (select unattributed_revenue from gaps),
  'unattributed_visits',  (select unattributed_visits from gaps),
  'install_credits_applied', (select count(*) from install_labor_credits c
                              where c.company_id = p_company_id and c.credit_date between p_start and p_end)
)
where (select ok from allowed)
$_$;


ALTER FUNCTION public.scoreboard_visit_revenue_trend(p_company_id uuid, p_start date, p_end date, p_grain text, p_tech_credit text) OWNER TO postgres;

--
-- Name: scoreboard_wf_technicians(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.scoreboard_wf_technicians(p_company_id uuid) RETURNS TABLE(employee_id uuid, jobber_external_id text, display_name text, salesperson_name text)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
  SELECT
    e.id AS employee_id,
    (SELECT ju.external_id FROM jobber_users ju
      WHERE ju.company_id = e.company_id
        AND ju.name ILIKE '%' || e.last_name || '%'
        AND (ju.name ILIKE '%' || e.first_name || '%'
             OR (NULLIF(e.preferred_name, '') IS NOT NULL AND ju.name ILIKE '%' || e.preferred_name || '%'))
      ORDER BY ju.is_active DESC NULLS LAST, ju.external_id
      LIMIT 1) AS jobber_external_id,
    COALESCE(NULLIF(e.preferred_name, ''), e.first_name) || ' ' || e.last_name AS display_name,
    COALESCE(NULLIF(e.preferred_name, ''), e.first_name) AS salesperson_name
  FROM employees e
  WHERE e.company_id = p_company_id
    AND e.is_active
    AND e.job_title ILIKE '%WF%'
    AND (
      (SELECT auth.uid()) IS NULL
      OR EXISTS (
        SELECT 1 FROM user_profiles up
        WHERE up.id = (SELECT auth.uid())
          AND up.company_id = p_company_id
          AND (up.role = 'admin' OR up.can_access_scoreboards)
      )
    )
  ORDER BY e.last_name, e.first_name
$$;


ALTER FUNCTION public.scoreboard_wf_technicians(p_company_id uuid) OWNER TO postgres;

--
-- Name: search_hub_messages(text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.search_hub_messages(p_query text, p_limit integer DEFAULT 30) RETURNS TABLE(id uuid, content text, created_at timestamp with time zone, room_id uuid, conversation_id uuid, parent_id uuid, sender_display_name text, sender_avatar_url text, room_name text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_company uuid;
  v_room_ids uuid[];
  v_conv_ids uuid[];
  v_tsq_text text;
  v_query tsquery;
BEGIN
  IF v_uid IS NULL THEN RETURN; END IF;
  IF length(coalesce(p_query, '')) < 2 THEN RETURN; END IF;

  SELECT up.company_id INTO v_company FROM user_profiles up WHERE up.id = v_uid;
  IF v_company IS NULL THEN RETURN; END IF;

  -- Build a prefix AND tsquery from alphanumeric word tokens (e.g. "lawn 50" -> "lawn:* & 50:*").
  -- Sanitizing to [a-z0-9] tokens guarantees to_tsquery() never sees special syntax.
  SELECT string_agg(tok || ':*', ' & ')
  INTO v_tsq_text
  FROM (
    SELECT unnest(regexp_split_to_array(lower(regexp_replace(p_query, '[^a-z0-9]+', ' ', 'gi')), '\s+')) AS tok
  ) s
  WHERE tok <> '';

  IF v_tsq_text IS NULL OR v_tsq_text = '' THEN RETURN; END IF;

  BEGIN
    v_query := to_tsquery('english', v_tsq_text);
  EXCEPTION WHEN others THEN
    RETURN;
  END;

  -- to_tsquery can produce an empty query (all stopwords); that matches nothing.
  IF v_query IS NULL OR v_query::text = '' THEN RETURN; END IF;

  v_room_ids := array(SELECT rm.room_id FROM room_members rm WHERE rm.user_id = v_uid);
  v_conv_ids := array(SELECT cm.conversation_id FROM conversation_members cm WHERE cm.user_id = v_uid);

  RETURN QUERY
  SELECT m.id, m.content, m.created_at, m.room_id, m.conversation_id, m.parent_id,
         hu.display_name, hu.avatar_url, r.name
  FROM messages m
  LEFT JOIN hub_users hu ON hu.id = m.sender_id
  LEFT JOIN rooms r ON r.id = m.room_id
  WHERE m.company_id = v_company
    AND m.deleted_at IS NULL
    AND to_tsvector('english', m.content) @@ v_query
    AND (
      (m.room_id IS NOT NULL AND m.room_id = ANY(v_room_ids))
      OR (m.conversation_id IS NOT NULL AND m.conversation_id = ANY(v_conv_ids))
    )
  ORDER BY m.created_at DESC
  LIMIT greatest(1, least(coalesce(p_limit, 30), 100));
END;
$$;


ALTER FUNCTION public.search_hub_messages(p_query text, p_limit integer) OWNER TO postgres;

--
-- Name: service_mapping_line_item_names(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.service_mapping_line_item_names(p_company_id uuid) RETURNS TABLE(name text, uses bigint)
    LANGUAGE sql STABLE
    AS $$
  select name, count(*) as uses
  from public.line_items
  where company_id = p_company_id and deleted_at is null and name is not null and name <> ''
  group by name
  order by count(*) desc, name asc
$$;


