--
-- Name: set_sold_date_on_status(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.set_sold_date_on_status() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF (NEW.status IN ('Sold', 'Sold — Upsell')) AND
     (OLD.status IS NULL OR OLD.status NOT IN ('Sold', 'Sold — Upsell')) AND
     NEW.sold_date IS NULL THEN
    NEW.sold_date = CURRENT_DATE;
  END IF;
  RETURN NEW;
END;
$$;


