--
-- Name: txt_latest_messages(uuid[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.txt_latest_messages(conv_ids uuid[]) RETURNS TABLE(conversation_id uuid, body text, media_count integer, direction text)
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  select distinct on (m.conversation_id)
    m.conversation_id,
    m.body,
    coalesce(array_length(m.media_urls, 1), 0)::int as media_count,
    m.direction
  from txt_messages m
  where m.conversation_id = any(conv_ids)
  order by m.conversation_id, m.created_at desc
$$;


ALTER FUNCTION public.txt_latest_messages(conv_ids uuid[]) OWNER TO postgres;

