--
-- Name: commission_plans; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.commission_plans (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    employee_id uuid NOT NULL,
    label text NOT NULL,
    basis text NOT NULL,
    rate_kind text DEFAULT 'percent'::text NOT NULL,
    rate numeric(12,4),
    tiers jsonb,
    threshold numeric(14,2),
    cap numeric(14,2),
    line_prefix text,
    items text[],
    active boolean DEFAULT true NOT NULL,
    sort_order integer DEFAULT 0 NOT NULL,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    period text DEFAULT 'month'::text NOT NULL,
    tier_mode text DEFAULT 'marginal'::text NOT NULL,
    verify_source text,
    min_price numeric,
    exclude_renewals boolean DEFAULT false NOT NULL,
    effective_from date,
    effective_to date,
    CONSTRAINT commission_plans_basis_chk CHECK ((basis = ANY (ARRAY['new_sales_value'::text, 'new_sales_count'::text, 'upsell_value'::text, 'upsell_count'::text, 'sales_value'::text, 'sales_count'::text, 'revenue_produced'::text, 'line_revenue'::text, 'item_count'::text, 'rev_per_hour'::text, 'company_rev_per_hour'::text, 'labor_pct'::text, 'company_labor_pct'::text]))),
    CONSTRAINT commission_plans_basis_kind_chk CHECK (
CASE
    WHEN (basis = ANY (ARRAY['rev_per_hour'::text, 'company_rev_per_hour'::text, 'labor_pct'::text, 'company_labor_pct'::text])) THEN (rate_kind = ANY (ARRAY['target_flat'::text, 'target_tiered'::text]))
    ELSE (rate_kind = ANY (ARRAY['percent'::text, 'per_unit'::text, 'tiered'::text]))
END),
    CONSTRAINT commission_plans_effective_chk CHECK (((effective_from IS NULL) OR (effective_to IS NULL) OR (effective_from <= effective_to))),
    CONSTRAINT commission_plans_items_chk CHECK (((basis <> 'item_count'::text) OR ((items IS NOT NULL) AND (array_length(items, 1) > 0)))),
    CONSTRAINT commission_plans_line_chk CHECK (((basis <> 'line_revenue'::text) OR (line_prefix IS NOT NULL))),
    CONSTRAINT commission_plans_minprice_chk CHECK (((min_price IS NULL) OR (verify_source IS NOT NULL))),
    CONSTRAINT commission_plans_nonneg_chk CHECK (((COALESCE(rate, (0)::numeric) >= (0)::numeric) AND (COALESCE(threshold, (0)::numeric) >= (0)::numeric) AND (COALESCE(cap, (0)::numeric) >= (0)::numeric))),
    CONSTRAINT commission_plans_period_chk CHECK ((period = ANY (ARRAY['month'::text, 'commission_weeks'::text, 'week'::text]))),
    CONSTRAINT commission_plans_rate_kind_chk CHECK ((rate_kind = ANY (ARRAY['percent'::text, 'per_unit'::text, 'tiered'::text, 'target_flat'::text, 'target_tiered'::text]))),
    CONSTRAINT commission_plans_rate_present_chk CHECK ((((rate_kind = ANY (ARRAY['tiered'::text, 'target_tiered'::text])) AND (tiers IS NOT NULL)) OR ((rate_kind <> ALL (ARRAY['tiered'::text, 'target_tiered'::text])) AND (rate IS NOT NULL)))),
    CONSTRAINT commission_plans_target_chk CHECK (((rate_kind <> 'target_flat'::text) OR (threshold IS NOT NULL))),
    CONSTRAINT commission_plans_tier_mode_chk CHECK ((tier_mode = ANY (ARRAY['marginal'::text, 'flat'::text]))),
    CONSTRAINT commission_plans_verify_chk CHECK (((verify_source IS NULL) OR (verify_source = 'invoice'::text)))
);


ALTER TABLE public.commission_plans OWNER TO postgres;

--
-- Name: COLUMN commission_plans.period; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.commission_plans.period IS 'month = the window as asked for (default, and what every rule meant before this existed); commission_weeks = W1-W4 summed as one window; week = each of W1-W4 judged separately and summed. Bonus weeks are computed in lib/scoreboards/widgets/windows.ts and passed to scoreboard_commission_production as buckets.';


--
-- Name: COLUMN commission_plans.tier_mode; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.commission_plans.tier_mode IS 'marginal (default) = each band pays only on the slice above its floor; flat = the band reached pays its rate on the whole figure.';


--
-- Name: COLUMN commission_plans.verify_source; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.commission_plans.verify_source IS 'null (default) = a counted unit is the Lead Tracker row alone; invoice = the unit must be backed by a matching invoice line in the period.';


--
-- Name: COLUMN commission_plans.exclude_renewals; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.commission_plans.exclude_renewals IS 'With verify_source, drops a unit whose customer already had this item before the period start - checked against BOTH invoice and visit line items, because the invoice mirror only reaches 2026-01-02.';


