--
-- Name: hub_users_with_presence; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.hub_users_with_presence WITH (security_invoker='on') AS
 SELECT hu.id,
    hu.company_id,
    hu.display_name,
    hu.avatar_url,
    hu.is_bot,
    hu.status,
    hu.status_text,
    hu.status_emoji,
    hu.status_until,
    hu.last_active_at,
    hu.created_at,
    hu.claude_allowed,
    e.id AS employee_id,
    e.pay_type,
    e.is_active AS employee_is_active,
    public.is_employee_clocked_in(e.id) AS is_clocked_in,
        CASE
            WHEN (hu.status = 'dnd'::text) THEN 'dnd'::text
            WHEN (hu.status = 'busy'::text) THEN 'busy'::text
            WHEN hu.is_bot THEN 'available'::text
            WHEN (lower(COALESCE(e.pay_type, ''::text)) = 'hourly'::text) THEN
            CASE
                WHEN public.is_employee_clocked_in(e.id) THEN 'available'::text
                ELSE 'offline'::text
            END
            ELSE
            CASE
                WHEN (hu.last_active_at >= (now() - '00:15:00'::interval)) THEN 'available'::text
                ELSE 'offline'::text
            END
        END AS effective_status
   FROM (public.hub_users hu
     LEFT JOIN public.employees e ON ((e.user_id = hu.id)));


