    gross_pay numeric,
    wages_cost numeric GENERATED ALWAYS AS (((COALESCE(regular_earnings, (0)::numeric) + COALESCE(overtime_earnings, (0)::numeric)) + COALESCE(commission, (0)::numeric))) STORED,
    off_cycle boolean DEFAULT false,
    check_date date
);


