--
-- Name: products_with_cost; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.products_with_cost AS
 SELECT id,
    company_id,
    category_id,
    name,
    description,
    package_price,
    package_size,
    unit,
    epa_reg_number,
    active_ingredient,
    notes,
    batch_number,
    batch_date,
    is_active,
    sort_order,
    created_at,
    updated_at,
    application_rate,
    rate_basis,
    label_url,
    deleted_at,
        CASE
            WHEN ((package_size IS NOT NULL) AND (application_rate IS NOT NULL) AND (application_rate <> (0)::numeric)) THEN (package_size / application_rate)
            ELSE NULL::numeric
        END AS coverage_k,
        CASE
            WHEN ((package_price IS NOT NULL) AND (package_size IS NOT NULL) AND (application_rate IS NOT NULL) AND (application_rate <> (0)::numeric)) THEN round((package_price / (package_size / application_rate)), 4)
            ELSE NULL::numeric
        END AS cost_per_k
   FROM public.products p;


ALTER VIEW public.products_with_cost OWNER TO postgres;

