-- Name: report_goals; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.report_goals (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    metric text NOT NULL,
    grain text NOT NULL,
    period_start date NOT NULL,
    period_end date NOT NULL,
    target numeric(14,2) NOT NULL,
    created_by uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    employee_id uuid,
    repeats boolean DEFAULT false NOT NULL,
    CONSTRAINT report_goals_check CHECK ((period_end >= period_start)),
    CONSTRAINT report_goals_grain_check CHECK ((grain = ANY (ARRAY['month'::text, 'quarter'::text, 'year'::text]))),
    CONSTRAINT report_goals_target_check CHECK ((target > (0)::numeric))
);


ALTER TABLE public.report_goals OWNER TO postgres;

--
-- Name: COLUMN report_goals.employee_id; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.report_goals.employee_id IS 'NULL = a company-wide target. Set = that employee''s own target. Keyed on employees.id (never a name) because the Crew and People reports spell the same person differently ("Mike Cyplik" vs "Mike"), so a name-keyed goal could not match both sources. Same key commission_plans uses, so goals and commission agree on who a person is.';


--
-- Name: COLUMN report_goals.repeats; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.report_goals.repeats IS 'True = a template applying to every period of this grain from period_start onward. period_start/period_end still describe the FIRST period, so nothing that reads a single period needs to know about repetition. A non-repeating row for the same metric/grain/period/person wins over the template.';


