--
-- Name: voice_routing_directory; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.voice_routing_directory (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    label text NOT NULL,
    kind text DEFAULT 'person'::text NOT NULL,
    description text DEFAULT ''::text NOT NULL,
    dest_kind text DEFAULT 'user'::text NOT NULL,
    dest_value text DEFAULT ''::text NOT NULL,
    enabled boolean DEFAULT true NOT NULL,
    sort_order integer DEFAULT 0 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT voice_routing_directory_dest_kind_check CHECK ((dest_kind = ANY (ARRAY['user'::text, 'cell'::text, 'ring_group'::text, 'extension'::text, 'voicemail'::text]))),
    CONSTRAINT voice_routing_directory_kind_check CHECK ((kind = ANY (ARRAY['person'::text, 'department'::text])))
);


ALTER TABLE public.voice_routing_directory OWNER TO postgres;

--
-- Name: voice_scheduling_services; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.voice_scheduling_services (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    company_id uuid NOT NULL,
    line_item text NOT NULL,
    mode text DEFAULT 'appointment'::text NOT NULL,
    enabled boolean DEFAULT true NOT NULL,
    duration_minutes integer DEFAULT 60 NOT NULL,
    max_per_day integer DEFAULT 4 NOT NULL,
    time_frames jsonb DEFAULT '[]'::jsonb NOT NULL,
    offered_days integer[] DEFAULT '{}'::integer[] NOT NULL,
    assigned_user_ids jsonb DEFAULT '[]'::jsonb NOT NULL,
    lead_days integer DEFAULT 1 NOT NULL,
    horizon_days integer DEFAULT 30 NOT NULL,
    commitment text DEFAULT 'request'::text NOT NULL,
    frequencies jsonb DEFAULT '[]'::jsonb NOT NULL,
    sort_order integer DEFAULT 0 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    job_title_template text,
    CONSTRAINT voice_scheduling_services_commitment_check CHECK ((commitment = ANY (ARRAY['request'::text, 'direct'::text]))),
    CONSTRAINT voice_scheduling_services_duration_minutes_check CHECK (((duration_minutes >= 1) AND (duration_minutes <= 480))),
    CONSTRAINT voice_scheduling_services_horizon_days_check CHECK (((horizon_days >= 1) AND (horizon_days <= 365))),
    CONSTRAINT voice_scheduling_services_lead_days_check CHECK (((lead_days >= 0) AND (lead_days <= 60))),
    CONSTRAINT voice_scheduling_services_max_per_day_check CHECK (((max_per_day >= 1) AND (max_per_day <= 100))),
    CONSTRAINT voice_scheduling_services_mode_check CHECK ((mode = ANY (ARRAY['appointment'::text, 'recurring'::text])))
);


ALTER TABLE public.voice_scheduling_services OWNER TO postgres;

