--
-- Name: visits visits_admin_all; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY visits_admin_all ON public.visits USING (((company_id = public.get_my_company_id()) AND (EXISTS ( SELECT 1
   FROM public.user_profiles up
  WHERE ((up.id = ( SELECT auth.uid() AS uid)) AND (up.role = 'admin'::text)))))) WITH CHECK (((company_id = public.get_my_company_id()) AND (EXISTS ( SELECT 1
   FROM public.user_profiles up
  WHERE ((up.id = ( SELECT auth.uid() AS uid)) AND (up.role = 'admin'::text))))));


